/* ÇEVİRİ ko · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ko","olay",{
"OLAYLAR_EK5:1684-08-06:0":{"b": ["아야마우라(레프카다)를 베네치아에 빼앗김", "e6905fee"], "d": ["신성 동맹에 가담한 베네치아의 함대는 도시를 포격한 뒤 이오니아해의 아야마우라(레프카다)섬을 점령했다. 같은 해 프레베자도 함락되면서 아드리아해 어귀에서 오스만의 통제는 무너졌다. 이 상실들은 모로시니가 3년 안에 모레아 전체를 장악하게 되는 작전의 첫걸음이었다.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["코론을 베네치아에 빼앗김", "2ed762bc"], "d": ["모로시니가 이끄는 베네치아군은 모레아반도 남서쪽 끝의 코론 요새를 점령했고, 도시는 이후 30년 동안 베네치아의 통치 아래 남게 된다. 코론의 함락은 모레아 정복을 겨냥한 베네치아 작전의 첫 번째 큰 성과였다. 이 요새는 1715년에야 실라흐다르 알리 파샤가 이끄는 오스만군이 되찾을 수 있었다.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["아테네 수복 — 베네치아의 철수", "03393b46"], "d": ["1687년 9월 아크로폴리스를 포격하여 파르테논을 폭파한 모로시니는 아테네에서 겨울을 난 뒤 도시를 지켜 낼 수 없음을 깨달았다. 페스트의 유행, 보급의 어려움, 오스만군의 전열 정비에 직면하자 베네치아 수비대는 도시를 비우고 모레아로 철수했다. 이로써 아테네는 전투 없이 다시 오스만의 통치로 돌아왔으나, 파르테논이 입은 파괴는 돌이킬 수 없었다.", "79c8586a"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["베네치아의 에우보이아(네그로폰테) 포위 격퇴", "aae7e6a0"], "d": ["모레아를 장악한 뒤 에게해로 향한 모로시니는 석 달이 넘는 포위전으로 에우보이아(네그로폰테)를 점령하려 했다. 그러나 1687-1688년 겨울에 강화된 방어 시설과 수비대의 저항 앞에서 큰 손실을 입고 철수해야 했다. 이 실패는 에게해에서 베네치아의 진출을 멈추게 했고 모로시니의 군사적 명성을 흔들었다. 에우보이아는 카를로비츠 조약에서도 오스만의 수중에 남게 된다.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["카니제 요새를 오스트리아에 빼앗김", "553b45f3"], "d": ["1690년 1월부터 6만 명의 합스부르크군에게 엄중히 봉쇄당한 카니제는 몇 달 동안 지원을 받지 못한 채 버티다가, 마지막 수비대장 무스타파 파샤가 서명한 항복 협정으로 넘어갔다. 이로써 티랴키 하산 파샤의 영웅적인 방어로 기억되는 이 요새에서 90년에 걸친 오스만의 지배가 끝났다. 카니제의 상실은 서부 헝가리에서 오스만의 마지막 큰 거점이 무너진 것이었다.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["아흐메드 2세의 즉위", "52947b14"], "d": ["쉴레이만 2세가 죽자 마흔아홉 살의 동생 아흐메드 2세가 에디르네에서 왕위에 올랐다. 그의 치세는 신성 동맹 전쟁의 가장 힘든 시기와 겹쳤다. 즉위 두 달 뒤 슬란카멘에서 대재상 파즐 무스타파 파샤가 전사했다. 반면 그의 시대에 시행된 말리카네(종신 징세 청부) 제도는 오스만 재정의 장기적 구조를 바꾼 가장 중요한 조치 가운데 하나가 되었다.", "d3441b14"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["이란인의 바스라 점령", "a9cdf3a3"], "d": ["오스만 국가가 서쪽에서 신성 동맹 전쟁에 매여 있는 동안, 바스라는 1690년의 페스트 유행 뒤 먼저 문타피크 부족의 셰이크 마니에게, 이어 후베이제의 칸 페레줄라에게 약탈당했다. 이 혼란을 틈타 이란인은 1696년에 도시를 점령하고 바스라에 수비대를 남겼다.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["이스탄불 조약 — 아조프를 러시아에 할양", "79db4724"], "d": ["카를로비츠에서 러시아와는 2년의 휴전만 맺을 수 있었으며, 항구적인 강화는 1년 반에 걸친 힘겨운 협상 끝에 이스탄불에서 체결되었다. 오스만 국가는 1696년에 잃은 아조프 요새와 그 주변 영토를 공식적으로 러시아에 넘기고, 크림 칸이 모스크바에서 받던 연례 세금을 포기했다. 그 대가로 러시아는 이스탄불에 상주 대사를 둘 권리를 얻었다. 이로써 흑해 북안에서 러시아의 존재가 법적으로 인정되었다.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["달타반 무스타파 파샤의 쿠르나·바스라 탈환", "7adb777d"], "d": ["카를로비츠 조약 뒤 바그다드 총독 겸 바스라 총사령관(세라스케르)에 임명된 달타반 무스타파 파샤는 알레포, 라카, 시바스, 카라만의 병력과 비레지크에서 내려온 하천 함대를 이끌고 남쪽으로 진군했다. 주변의 부족 셰이크들은 하나둘 복종했고, 이란의 바스라 수비 대장 다우드 칸은 도시를 버렸으며, 쿠르나와 바스라는 다시 오스만의 통치에 들어왔다.", "60abbe06"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["바그다드에서 콜레멘(맘루크) 통치의 시작", "abe52618"], "d": ["조지아 출신의 하산 파샤가 바그다드 총독에 임명되면서, 이라크에서는 중앙에서 임명한 총독 대신 자신의 노예 가운데서 길러 낸 지배 집단이 주도권을 쥐는 시대가 시작되었다. 1749년 쉴레이만 파샤가 총독이 되면서 이 체제는 확고히 자리 잡았고, 바브알리는 이제 원하는 사람이 아니라 영향력을 장악한 콜레멘 중 한 사람을 임명해야 했다. 이 반(半)자치 구조는 이란 국경을 방어하는 데에는 쓸모가 있었으나, 한 세기 반 동안 이라크에 대한 중앙 권력의 통제를 약화시켰다.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["튀니스에서 후사인 왕조의 수립", "cb1a98f9"], "d": ["알제의 군대가 튀니스를 침공하여 생긴 권력 공백 속에서, 튀르크계 시파히 아아 후사인 이븐 알리는 베이의 자리를 장악하고 오스만 술탄에 대한 충성을 밝힘으로써 정통성을 얻었다. 그가 세운 왕조는 1705-1735년과 1756-1957년에 튀니스를 다스렸으며, 오자크(군단)의 통치는 아버지에게서 아들로 이어지는 베이 체제로 대체되었다. 이로써 서방 오자크(가르프 오자클라르)에서 중앙에 속하면서도 사실상 자치적인 왕조 구조의 첫 사례가 탄생했다.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["스페인으로부터 오랑(바흐란)과 메르스엘케비르 탈환", "b67ce06a"], "d": ["알제 오자크의 베일레르베이 군대는 2세기 동안 스페인 수비대의 수중에 있던 오랑과 그 항구 메르스엘케비르를 긴 포위 끝에 점령했다. 이것은 서지중해에서 오스만의 보호를 받던 서방 오자크들이 스페인을 상대로 거둔 가장 큰 성공이었으며, 알제의 서쪽 측면을 확보했다. 도시는 1732년 다시 스페인에 점령되지만, 1792년에 확정적으로 되찾게 된다.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["프루트 조약 — 아조프와 타간로크의 회복", "bac5d2a1"], "d": ["프루트강 변에서 포위된 러시아군이 항복하면서 체결된 7개 조항의 조약은 아조프 요새를 그 토지 및 군수품과 함께 오스만에 반환한다고 규정했다. 타간로크, 카멘카, 예니칼레의 방어 시설은 허물어야 했고, 양측은 이 지역에 새 요새를 짓지 않기로 했다. 표트르 1세가 보로네시와 아조프에 16년 동안 구축한 함대와 기지 체계는 무너졌고, 러시아의 흑해 진출은 약 50년 늦어졌다.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["트리폴리타니아에서 카라만리 왕조의 수립", "e1105d4a"], "d": ["오자크 아아들의 다툼에 지친 트리폴리타니아에서 기병 장교 아흐메드 카라만리가 통치권을 장악하고, 이스탄불에서 받은 베일레르베이 임명장(베라트)으로 자신의 지위를 공식화했다. 아흐메드 파샤, 그의 아들 메흐메드 파샤, 손자 유수프 파샤를 거치며 1711-1835년에 이어지는 왕조가 생겨났고, 자체 함대를 만들고 유럽 국가들과 직접 조약을 체결하는 반(半)독립적 구조가 나타났다. 이 시대는 1835년 이 주가 중앙의 직할이 되면서야 끝난다.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["러시아와의 에디르네 조약", "14901a70"], "d": ["프루트에서 한 약속이 이행되지 않아 두 차례 더 선전포고가 이루어졌고, 마침내 러시아가 약속 사항을 받아들이면서 에디르네에서 항구적인 강화가 체결되었다. 조약은 프루트의 조건을 확인했다. 러시아는 폴란드의 일에 간섭하지 않고, 카자크 영토에서 철수하며, 스웨덴 국왕 '철두(鐵頭)' 칼 12세(데미르바시 샤를)의 귀국을 방해하지 않기로 했다. 이렇게 북부 전선이 닫힘으로써 오스만 국가는 모레아와 베네치아 전선으로 눈을 돌릴 수 있었다. 같은 날짜에 편입된 다른 곳: 호틴.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["베네치아에 대한 선전포고 — 모레아 원정의 준비", "d970b122"], "d": ["베네치아가 몬테네그로 반란자들을 지원하고, 오스만 상선을 압류하며, 카를로비츠에서 얻은 모레아를 무거운 세금으로 짓눌렀다는 것을 이유로 디반에서 전쟁이 결정되었다. 대재상 실라흐다르 다마드 알리 파샤가 준비한 원정은 이듬해 100일도 안 되어 모레아반도 전체를 되찾는 것으로 결실을 맺는다. 그러나 이 성공은 오스트리아를 움직이게 했고, 1716년 훨씬 더 힘겨운 전쟁의 문을 열게 된다.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["티노스: 에게해에 남은 베네치아의 마지막 섬의 항복", "4abec891"], "d": ["모레아 원정에 나선 함대는 항로상에 있던, 에게해에서 베네치아의 수중에 남은 유일한 섬 티노스 앞에 닻을 내렸다. 낙소스 공국이 1566년에 무너졌음에도 라틴계 주민 덕분에 150년을 더 베네치아 깃발을 내걸었던 이 섬은 짧은 포위 끝에 피를 흘리지 않고 항복했다. 이로써 에게해에서 베네치아의 마지막 발자취가 지워졌고, 이 바다는 온전히 오스만의 내해가 되었다.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["나프플리온 정복 — 모레아의 요충 요새", "62a5808a"], "d": ["모레아에서 베네치아의 수도이자 가장 강력한 요새였던 나프플리온은 9일간의 포격 끝에 팔라미디 보루가 점령되면서 함락되었다. 요새가 이토록 빨리 점령되자 반도의 나머지 지역의 저항도 꺾였다. 카를로비츠에서 잃은 모레아의 수복은 사실상 여기에서 완료되었다. 같은 날짜에 본 아틀라스에서 베네치아에서 오스만으로 넘어가는 다른 정착지는 아르고스로, 나프플리온의 상위 중심지 연쇄를 따른다(TDV anabolu; 명시된 근사치).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["모돈의 항복", "43faa909"], "d": ["나프플리온이 함락된 뒤 모레아 남서쪽 끝의 모돈 요새는 육지에서는 군대에, 바다에서는 함대에 포위되어 곧 항복했다. 베네치아가 동지중해 항해에 200년 동안 이용한 이 항구는 배들이 물과 식량을 싣는 필수 기항지였다. 이 항구의 상실로 베네치아 함대의 에게해 활동 능력은 끝났다.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["코론의 항복 — 모레아 원정의 완수", "e4b9c8a4"], "d": ["메세니아만 입구를 장악한 코론 요새가 항복하면서 모레아반도의 베네치아 통치는 완전히 끝났다. 카를로비츠에서 잃은 반도는 원정이 시작된 지 겨우 석 달 만에 전부 되찾았다. 같은 원정이 이어지는 가운데 1715년 9월에는 이오니아해의 아야마브라(레프카다)섬도 베네치아에게서 빼앗았다. 이 속도는 베네치아로 하여금 오스트리아를 전쟁에 끌어들이지 않을 수 없게 했고, 3년 뒤 파사로비츠로 가는 길이 열렸다.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["추하섬(키티라) 점령", "494de6c6"], "d": ["모레아반도의 점령이 끝난 뒤 반도 남단의 추하섬(키티라)은 함대에 접수되었다. 이오니아해와 에게해 사이의 통로를 감시하는 이 섬은 베네치아가 이 해역을 통제하는 데 이용한 전초 기지였다. 그러나 이 섬은 오스만이 계속 보유한 섬으로 남지 못하고, 3년 뒤 파사로비츠에서 베네치아에 반환되었다.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["오스트리아와 베네치아의 동맹 — 1716-1718년 오스만-오스트리아 전쟁의 문", "99511ca2"], "d": ["오스만이 베네치아로부터 모레아를 되찾자, 오스트리아는 카를로비츠 조약이 위반되었다고 주장하며 베네치아와 동맹 조약을 체결했다. 오이겐 공은 대재상에게 보낸 서한에서 베네치아로부터 빼앗은 곳들을 반환하라고 요구했다. 다부트파샤 진영에서의 협의에서 대재상 알리 파샤의 압박으로 오스트리아에 선전포고가 이루어졌고, 이를 위해 셰이휠이슬람에게서 파트와를 받았다.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["대재상 알리 파샤의 오스트리아 원정 출정", "2fbdce42"], "d": ["오스트리아에 선전포고한 뒤, 총사령관(세르다르 이 에크렘) 알리 파샤는 10만 명이 넘는 군대를 이끌고 오스트리아 원정에 나섰고, 함대는 같은 해 여름 코르푸로 향했다. 군대는 베오그라드에서 페트로바라딘으로 진군하게 되며, 8월 초의 패전에서 대재상은 전사하게 된다.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["페트로바라딘(바라딘) 패전 — 다마드 알리 파샤의 전사", "265c1d81"], "d": ["베오그라드를 거쳐 다뉴브강을 건넌 오스만군은 페트로바라딘 앞에서 오이겐 공이 이끄는 오스트리아군과 맞섰다. 첫 공격에서 예니체리의 돌격이 적의 참호를 압박했으나, 기병 날개가 무너지면서 대열은 흩어졌다. 대재상 실라흐다르 다마드 알리 파샤는 이마에 총탄을 맞고 전사했으며, 진영과 포병 장비는 통째로 적의 손에 넘어갔다. 오스만 연대기가 '바라딘의 해'라고 부르는 이 패전은 테메슈바르, 그리고 이듬해 베오그라드의 상실로 이어지는 연쇄의 첫 고리였다.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["코르푸 포위의 실패", "b2aa7011"], "d": ["모레아의 세라스케르 카라 무스타파 파샤는 육지에서, 카푸단 파샤(해군 총사령관) 자늠 호자 메흐메드 파샤는 함대로 바다에서 코르푸를 압박했다. 이 섬은 아드리아해에서 베네치아의 핵심 거점이었다. 그러나 요새의 매우 강력한 방어 시설, 베네치아 함대가 데려온 증원군, 다뉴브 전선에서 전해진 패전 소식 때문에 포위는 해제되었다. 코르푸를 점령하지 못한 것은 모레아 재정복으로 고조된 분위기를 식혔고, 전쟁의 무게중심을 헝가리로 옮겨 놓았다.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["테메슈바르(티미쇼아라)를 오스트리아에 상실", "27fe1365"], "d": ["페테르바라딘 패전 뒤 오이겐 공은 곧바로 테메슈바르로 진격했고, 요새는 40일이 넘는 포위 끝에 항복 협정을 맺고 넘겨졌다. 1552년 카누니 시대에 정복되어 164년 동안 베일레르베이령의 중심지로서 헝가리 방어의 동쪽 기둥으로 여겨지던 도시는 이렇게 상실되었다. 테메슈바르의 함락으로 바나트 지역 전체가 오스트리아에 넘어갔고, 오스만 국경은 도나우강 남쪽으로 밀려났다. 같은 날짜에 본 아틀라스에서 오스만에서 합스부르크로 넘어가는 다른 정착지는 차코바르, 파체트, 카란셰베시(카란세베슈)로, 테메슈바르 주의 이양과 함께한 것이다(TDV timisvar; 지점 단위의 날짜는 사료에 없음, 상위 중심지 연쇄, 명시된 근사치).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["하람(예니 팔란카) 요새를 오스트리아에 인도 — 바나트의 도나우강변 상실", "38ee4c6d"], "d": ["테메슈바르 함락 뒤 바나트의 나머지를 점령하는 임무를 맡은 오스트리아 기병 장군 메르시는 11월 14일 도나우강변의 하람(예니 팔란카)으로 진격했다. 11월 16일 그가 요새에 도착하자 200명의 오스만 수비대는 백기를 올리고 자유 철수를 조건으로 항복했다. 이로써 1552년 이래 오스만의 수중에 있던 남부 바나트의 도나우 방어선도 오스트리아에 넘어갔다. 같은 날짜에 본 아틀라스에서 오스만에서 합스부르크로 넘어가는 다른 정착지는 베르셰츠로, 하람의 상위 중심지 연쇄를 따른다(Bánlaky 0019/1703; 명시된 근사치).", "5b54ecb0"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["동방 원정: 트빌리시 점령과 이란 전쟁의 시작", "78343dc2"], "d": ["사파비 국가가 아프간의 침입으로 무너지고 러시아가 카스피해 연안까지 남하하자, 오스만 국가는 그 공백이 전적으로 러시아의 세력권에 들어가지 않도록 동쪽으로 군대를 보냈다. 트빌리시를 점령하여 조지아를 오스만의 통치에 편입했고, 이어 간자, 예레반, 나흐치반 방향으로 진격을 계속했다. 튤립 시대의 평화로운 겉모습 뒤에서 수행된 이 원정은 13년 동안 이어지다가 결국 획득한 모든 땅을 돌려주는 것으로 끝나게 될 기나긴 동방 모험의 시작이었다.", "5c412d91"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["이스탄불 분할 협정(무카세멘나메) — 러시아와의 이란 분할", "fce8eec2"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["타브리즈 점령 — 아제르바이잔의 장악", "e502a4f7"], "d": ["1년 전의 시도가 실패한 뒤 다시 포위된 타브리즈는 거리마다 벌어진 격렬한 전투 끝에 오스만군에 항복했다. 타브리즈 주에 속한 마란드, 마라게, 소부크불라크(마하바드)도 오스만의 통치에 들어왔다. 같은 해 로리, 간자, 아르다빌, 호라마바드도 점령되어, 이스탄불 분할 협정에서 오스만의 몫으로 돌아간 지역들이 실제로 점령되었다. 동방에서 도달한 이 판도는 페르하드 파샤 조약 시대 이후 가장 앞선 국경이었으나, 이를 유지하는 일은 군대와 재정에 무거운 부담을 안겼다.", "e0953563"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["하마단 조약 — 서부 이란의 오스만 편입", "94a29dc3"], "d": ["아프간 통치자 아슈라프 샤와 체결한 조약으로 4년간 이어진 전쟁이 끝났고, 오스만 국가가 점령한 서부 이란의 영토가 법적으로 인정되었다. 아슈라프 샤는 그 대가로 오스만 술탄의 칼리프 지위를 인정하고, 이란에서 술탄의 이름으로 후트바를 낭독하게 하겠다고 약속했다. 이 외교적 승리는 오래가지 못했다. 나디르 샤가 1730년에 시작한 반격이 몇 해 안에 조약의 성과를 모두 쓸어 버리게 된다.", "fd0174b9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["아흐메드 파샤 조약 — 서부 이란 대부분의 반환", "590d839f"], "d": ["나디르 샤가 말라예르에서 거둔 승리와 잇따른 이란의 공세에 직면하여, 바그다드 총독 아흐메드 파샤는 중앙 정부와 협의하지 않고 강화 문서에 서명했다. 조약에 따라 아라스강이 국경으로 정해졌고, 하마단, 케르만샤, 아르달란, 아르다빌, 타브리즈 같은 서부 이란의 도시들은 이란에 반환되었으며, 간자와 트빌리시는 오스만에 남았다. 이스탄불에서 반발을 산 이 문서는 나디르 샤도 불충분하다고 여겼고, 1732년이 채 가기도 전에 전쟁이 다시 불붙었다. 본 아틀라스는 호이의 연쇄를 따르는 코투르도 이 날짜에 오스만에서 사파비로 넘어간 것으로 본다(TDV hoy; 코투르에 해당하는 날짜는 사료에 없음 — 명시된 근사치).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["오랑(바흐란)을 다시 스페인에 상실", "20485027"], "d": ["스페인 국왕 펠리페 5세가 보낸 대규모 상륙 함대가 몬테마르 백작의 지휘 아래 오랑 앞에 나타나, 알제 오자크의 병력을 격파하고 도시를 탈환했다. 24년 전에 정복했던 이 항구는 다시 60년 동안 스페인 수비대의 수중에 남게 된다. 서지중해에서 서방 오자크들이 지닌 힘의 한계를 보여 준 이 상실은 1792년 오랑을 최종적으로 정복하고서야 만회할 수 있었다.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["훔바라 부대(박격포·폭탄병 부대)의 유럽식 개혁과 훔바라하네 설립", "d980cf2a"], "d": ["오스만에 출사한 프랑스 출신의 훔바라즈 아흐메드 파샤는 대재상 헤키모을루 알리 파샤의 후원을 받아 훔바라 부대를 봉급을 받는 유럽식 편제의 부대로 만들었다. 보스니아에서 모집한 병사 300명에게 산술과 기하학에 바탕을 둔 정규 교육을 실시했고, 조직·장비·퇴역에 관한 새 규정을 마련했으며, 당대의 기술로 박격포 100문과 폭탄 5만 발을 제작했다. 기하학을 가르친 훔바라하네는 오스만에서 근대 군사 공학 교육의 첫 맹아로 여겨진다.", "181b7161"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["이스탄불 조약 — 남캅카스를 이란에 양도", "8c205aab"], "d": ["4년간 이어진 제2차 이란 전쟁은 아르파차이 패전과 간자·트빌리시 상실 뒤에 체결된 조약으로 끝났다. 오스만 국가는 1723년 이래 점령한 남캅카스와 서부 이란의 모든 영토에서 철수했고, 국경은 1639년의 카스르에 시린 선으로 되돌아갔다. 13년에 걸친 동방 원정이 남긴 것은 무거운 재정 부담과 텅 빈 국고였다. 그 대신 동부 전선이 닫힌 것은 러시아와 새로 시작된 전쟁을 위해 매우 중대한 이득이었다.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["외지(오차키우) 요새가 러시아에 함락", "f93e61f3"], "d": ["뮌니히 원수가 지휘하는 러시아군은 드니프로강 하구의 외지 요새를 포위했다. 화약고가 폭발하면서 방어가 무너졌고, 요새는 막대한 인명 손실을 내며 함락되었다. 흑해 북서 해안의 자물쇠로 여겨지던 외지의 상실은 러시아에 크림으로 가는 길을 열어 주었고, 이스탄불에 큰 공황을 불러일으켰다. 이듬해 러시아는 전염병과 보급난 때문에 요새를 비우게 되며, 요새는 다시 오스만에 넘어간다.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["바냐루카 승리 — 보스니아를 구하다", "f603865a"], "d": ["오스트리아군이 보스니아에 들어와 바냐루카를 포위하자, 보스니아 총독 헤키모을루 알리 파샤는 현지 주민에게서 모은 병력을 이끌고 구원에 나서 수적으로 우세한 적에게 큰 패배를 안겼다. 이 승리는 오스트리아의 보스니아 점령 계획을 첫 수에서부터 무너뜨렸고, 주의 북부는 완전히 수복되었다. 바냐루카는 1683년 이후 오스트리아 앞에서 계속 후퇴하던 오스만군의 사기를 되살린 전환점 가운데 하나가 되었다.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["히사르즈크(그로츠카) 승리 — 베오그라드로 가는 길이 열리다", "2101cdff"], "d": ["베오그라드를 지키기 위해 진군하던 오스트리아군은 도나우강변의 좁은 골짜기에서 매복에 걸려, 온종일 이어진 전투에서 큰 손실을 입었다. 발리스 원수의 병력이 무질서하게 베오그라드로 퇴각하는 동안 오스만군은 요새 앞까지 육박하여 포위를 시작했다. 히사르즈크는 카를로비츠 이래 오스트리아를 상대로 거둔 가장 결정적인 야전 승리였으며, 베오그라드 탈환을 직접 가능하게 했다.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["니시 조약 — 러시아와의 강화, 아조프의 중립화와 크림의 습격 중지", "674f974e"], "d": ["오스트리아가 베오그라드에서 강화에 동의하자 홀로 남게 된 러시아는 프랑스 대사 빌뇌브의 중재로 전쟁을 끝낼 수밖에 없었다. 아조프 요새의 방어 시설을 허물고 그 지역을 두 나라 사이의 중립 지대로 선포했으며, 러시아는 흑해에 군함과 상선을 두지 않는다는 조건을 받아들였다. 이로써 바다로 진출하려는 러시아의 목표는 한 세대 더 미루어졌고, 오스만 국가는 18세기에 마지막으로 이득을 보고 협상 테이블에서 일어섰다.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["외지가 러시아 점령에서 돌아오다: 1739년 강화에 따라 요새를 허문 뒤 인도", "7ecc2bef"], "d": ["러시아는 1737년 7월 11일 외지를 점령했다. 1739년 러시아와 맺은 강화에 따라 요새의 방어 시설을 허문 뒤 다시 오스만에 인도했다. 오스만은 이아시 조약 이전인 1788년까지 외지를 보유했다.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["모술 방어전 — 나디르 샤의 격퇴", "c03ffbc1"], "d": ["키르쿠크와 아르빌을 점령하고 모술 앞에 이른 나디르 샤는 40일 동안 도시에 포격을 가하고 잇따라 총공격을 감행했다. 총독 후세인 파샤 알잘릴리가 도시 주민까지 무장시켜 벌인 방어전은 이란군이 큰 손실을 입고 포위를 풀 수밖에 없게 만들었다. 모술이 버텨 냄으로써 이라크 전체의 상실을 막았고, 도시에서 잘릴리 가문의 영향력은 한 세기 동안 공고해졌다.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["디리야 동맹 — 나지드에서 제1차 사우드 토후국의 수립", "188751bf"], "d": ["우야이나에서 추방된 학자 무함마드 이븐 압둘와하브를 디리야에서 보호하게 된 아미르 무함마드 이븐 사우드는, 그와 함께 정치 권력을 종교적 포교에 봉사하게 하는 동맹을 맺었다. 이 협약은 사우드 가문의 새로운 역사를 열었고, 흩어져 있던 나지드의 오아시스 토후국들을 하나의 운동 아래 결집시켰다. 반세기 안에 카르발라, 메카, 메디나까지 뻗게 될 이 세력은 오스만 국가가 히자즈에 대한 지배권을 지키지 않을 수 없게 만든다.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["케르덴 조약 — 오스만·이란 전쟁의 종결", "1d3a919e"], "d": ["4년간 이어진 마지막 전쟁 뒤에 체결된 조약으로 1639년의 카스르에 시린 국경이 그대로 갱신되었고, 양측 모두 영토상의 이득을 얻지 못했다. 자파리파를 다섯 번째 법학파로 인정해 달라는 나디르 샤의 끈질긴 요구는 받아들여지지 않았으나, 그 대신 이란인 순례자들이 자유롭게 성지 순례를 하고 서로 사절을 교환하기로 결정했다. 두 세기를 넘긴 오스만·이란 전쟁은 이렇게 사실상 막을 내렸으며, 이 국경은 오늘날까지 대체로 유지되고 있다.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["마흐무드 1세의 죽음과 오스만 3세의 즉위", "30203700"], "d": ["24년의 치세 동안 베오그라드 조약으로 잃었던 땅을 되찾고 훔바라 부대의 개혁을 후원한 마흐무드 1세는 금요 예배 행차에서 돌아오던 중 세상을 떠났다. 그 뒤를 이어 58세가 될 때까지 카페스(왕자 유폐처) 생활을 한 동생 오스만 3세가 즉위했다. 짧고 불안한 치세가 시작되었고, 3년 동안 대재상을 여섯 번 갈아 치운 오스만 3세 시대에는 국정에 뚜렷한 침체가 이어졌다.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["오스만 3세의 죽음과 무스타파 3세의 즉위", "3ac10f85"], "d": ["3년의 치세 끝에 오스만 3세가 세상을 떠나자, 개혁 사상에 열려 있고 국정에 깊은 관심을 보이던 무스타파 3세가 즉위했다. 새 술탄은 대재상 코자 라그브 파샤의 경륜에 의지하여 재정을 바로잡고 군대를 쇄신하려 했으며, 드 토트 남작의 속사 포병대가 이 시기에 창설되었다. 그러나 1768년에 뛰어든 러시아 전쟁이 17년 치세의 모든 성과를 가려 버리게 된다.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["러시아에 대한 선전 포고 — 발타 사건과 1768~1774년 전쟁의 시작", "9c6aabe0"], "d": ["폴란드의 바르 연맹을 추격하던 러시아와 카자크 부대가 오스만 국경의 발타 마을을 습격해 불태우자, 디완(국무회의)은 전쟁을 결정했고 러시아 사절은 예디쿨레에 투옥되었다. 진지한 군사적 준비도 없이, 여섯 달 앞서 선포하고 뛰어든 이 전쟁은 처음부터 불리하게 흘러갔다. 6년 동안 이어질 이 싸움은 체슈메 기습, 카르탈 패전, 크림 점령을 거치며 오스만 역사에서 가장 뼈아픈 연패 가운데 하나가 된다.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["호틴 요새를 러시아에 상실", "66d43ea4"], "d": ["골리친 공이 지휘하는 러시아군의 두 차례 시도는 격퇴되었으나, 카메네츠와 호틴 사이에서 대재상이 패배하자 군대는 후퇴했고 수비대는 요새를 비웠다. 도나우강 북쪽에서 가장 강력한 오스만 요새가 저항 없이 넘어가면서 왈라키아와 몰다비아의 문이 러시아에 열렸다. 두 공국은 같은 해에 점령되었고, 호틴은 1774년 퀴취크 카이나르자 조약으로야 되찾을 수 있었다.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["카르탈(카훌) 평원의 패전", "6f408eaf"], "d": ["체슈메에서 함대가 불탄 지 3주 뒤, 도나우강 일대의 오스만 주력군은 카르탈 평원에서 수적으로는 훨씬 적지만 규율 잡힌 루먄체프 원수의 부대 앞에 와해되었다. 진영과 군수품, 수백 문의 대포가 적의 손에 넘어갔고, 도주하던 부대는 도나우강을 건너다 큰 손실을 입었다. 같은 여름에 함대와 지상군이 모두 궤멸하면서 킬리야, 아케르만, 이즈마일, 벤데르가 잇따라 함락되고 크림이 점령되기에 이르렀다.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["러시아의 크림반도 점령", "217837b0"], "d": ["1년 전 부자크를 장악한 러시아군은 돌고루코프 공의 지휘 아래 오르 카프(페레코프)를 돌파하여 크림반도 전체를 침공했다. 칸은 폐위되었고 친러파인 사히브 기라이가 그 자리에 앉혀져, 칸국을 오스만에서 떼어 내는 첫걸음이 내디뎌졌다. 3세기 동안 오스만의 북쪽 방패였던 크림의 상실은 1774년의 독립과 1783년의 직접 병합으로 이어지는 과정의 시작이었다.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["무스타파 3세의 죽음과 압뒬하미드 1세의 즉위", "42cba8e2"], "d": ["러시아 전쟁이 가장 위태롭던 때 세상을 떠난 무스타파 3세의 뒤를 이어, 43년을 궁정의 카페스(왕자 유폐처)에서 보낸 동생 압뒬하미드 1세가 49세의 나이로 즉위했다. 국가가 가장 어려운 시기 가운데 하나를 넘겨받은 새 술탄은 같은 해에 체결될 퀴취크 카이나르자 조약의 가혹한 조건과 맞서야 했다. 15년에 걸친 그의 치세는 크림의 상실과 새로운 러시아 전쟁으로 점철되었고, 1789년 외지 함락 소식을 읽다가 일으킨 뇌졸중으로 끝나게 된다.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["코즐루자 패전 — 퀴취크 카이나르자로 이어진 패배", "8e0542f9"], "d": ["슈멘 앞에 집결한 오스만군은 코즐루자에서 수보로프와 카멘스키의 연합 종대에 패했고, 군대의 대부분이 흩어졌다. 이 패전으로 발칸에서 저항할 병력은 남지 않게 되었으며, 러시아 선봉대가 슈멘을 포위하고 대재상의 사령부가 위협을 받았다. 한 달이 채 되기도 전에 퀴취크 카이나르자에서 협상에 나서 이례적으로 가혹한 조건을 받아들인 것은 이 패배의 직접적인 결과이다.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["부코비나(북부 몰다비아)를 오스트리아에 양도", "190f9caa"], "d": ["퀴취크 카이나르자가 초래한 약점을 이용하여, 오스트리아는 몰다비아와 트란실바니아를 잇는 부코비나 지역을 요구했고, 전쟁을 하지 않고 위협과 뇌물로 이 땅을 손에 넣었다. 호틴 남서쪽의 비옥하고 전략적인 이 지역을 잃으면서 몰다비아 공국은 사실상 둘로 갈라졌다. 총알 한 발 쏘지 않고 이루어진 이 양도는 오스만 국가가 이제 억지력을 잃었음을 가장 분명하게 보여 주는 징표 가운데 하나로 여겨졌다. 1775년 부코비나의 양도로 수체아바와 체르노비츠가 오스트리아에 넘어갔다(날짜 미확인).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["바스라가 이란에 점령되다", "0161e709"], "d": ["잔드 왕조의 통치자 카림 칸의 동생 사디크 칸은 1년에 걸친 포위 끝에 바스라를 점령했고, 오스만 국가는 바스라만에서 가장 중요한 항구를 잃었다. 이 점령은 인도 무역로와 대추야자·진주 수입, 이라크의 남부 방어를 직접 뒤흔들었다. 이 도시는 1779년 카림 칸의 죽음으로 이란에서 왕위 다툼이 벌어진 틈에야 되찾을 수 있었다.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["아이날르카바크 해석 협정(텐키흐나메) — 크림에 관한 잠정 타협", "9b3b0468"], "d": ["크림 칸국의 수장을 누구로 할 것인가를 두고 전쟁 직전까지 갔던 두 나라는 프랑스의 중재로 아이날르카바크 별궁에서 해석 문서에 서명했다. 러시아는 크림에서 군대를 철수하기로, 오스만 국가는 친러파 샤힌 기라이의 칸위를 인정하기로 합의했으며, 크림에 대한 술탄의 종교적 칼리프 권한이 확인되었다. 4년간 지속될 이 위태로운 균형은 1783년 러시아가 반도를 직접 병합하면서 완전히 무너지게 된다.", "8a428802"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["러시아에 대한 선전 포고 — 1787~1792년 오스만·러시아 전쟁의 시작", "3bfb870c"], "d": ["예카테리나 2세의 과시적인 크림 순행과 조지아에 대한 보호령 설정에 대해, 디완(국무회의)은 병합을 되돌릴 목적으로 전쟁을 결정했고 러시아 사절은 다시 예디쿨레에 갇혔다. 그러나 군대는 준비되어 있지 않았고 국고는 비어 있었으며 동맹국을 찾는 노력은 성과가 없었다. 5년간 이어질 이 전쟁은 외지의 학살을 동반한 함락, 이즈마일의 상실, 이아시 조약의 가혹한 조건으로 끝나게 된다.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["오스트리아의 참전 — 두 전선의 싸움", "ae912290"], "d": ["1781년 러시아와 맺은 비밀 동맹에 따라 오스트리아 황제 요제프 2세는 오스만 국가에 선전 포고를 하고 베오그라드와 보스니아 방면으로 움직였다. 오스만군은 갑자기 북쪽의 러시아와 서쪽의 오스트리아를 상대로 두 전선에서 동시에 싸워야 했다. 라자레타네, 메하디아, 셰베시에서 오스트리아군에게 거둔 승리에도 불구하고, 1789년 베오그라드를 잃으면서 서부 전선도 무너지게 된다.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["오스만·프로이센 동맹", "03b88e51"], "d": ["즉위하자마자 유럽에서 동맹국을 찾던 셀림 3세는 프로이센과 상호 원조를 규정한 동맹 조약을 체결했다. 프로이센은 러시아와 오스트리아에 선전 포고를 하기로, 오스만 국가는 크림을 되찾기 전에는 강화하지 않기로 약속했다. 이는 오스만 역사에서 유럽 국가와 체결한 최초의 진정한 상호 동맹 문서였으며, '이교도와는 동맹하지 않는다'는 고전적 관념이 버려졌음을 보여 주었다. 프로이센은 참전하지 않았지만, 오스트리아를 강화로 몰아붙임으로써 시스토바 조약의 길을 열었다.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["이즈마일 요새의 함락과 학살", "6a296b0c"], "d": ["도나우 삼각주에서 가장 강력한 요새로 여겨지던 이즈마일 요새는 수보로프 장군이 벌인 피비린내 나는 총공격으로 하루 만에 점령되었고, 수비대와 주민은 대부분 도륙당했다. 유럽에 큰 반향을 일으킨 이 학살은 오스만 여론에 깊은 충격을 주었고, 도나우 방어선의 중추를 부러뜨렸다. 요새는 1년 뒤 이아시 조약으로 되찾게 되지만, 그때는 이미 전쟁의 운명이 결정된 뒤였다.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["시스토바 조약 — 오스트리아 전선의 종결", "58741f1d"], "d": ["프로이센의 압력과 프랑스 혁명으로 오스트리아가 서쪽에 매이게 된 덕분에, 두 나라는 전쟁 전의 국경을 기준으로 강화에 이르렀다. 오스트리아는 베오그라드를 포함하여 점령한 모든 곳을 돌려주었고, 오스만 국가는 크로아티아 국경의 작은 조정만 받아들였다. 서부 전선이 이러한 조건으로 닫히면서 오스만 국가는 모든 힘을 러시아에 집중할 수 있었고, 이아시 조약에서의 손실도 제한되었다. 이 크로아티아 국경 조정으로 체틴(체틴그라드)과 드레지니크 그라드는 오스만에서 합스부르크로 넘어간다(TDV zistovi-antlasmasi; Korić 2016, n. 118, 제4조). 한편 오르소바(구 오르소바)는 반환되지 않은 유일한 곳이다(Bánlaky 0019/1796). 본 아틀라스는 법적 이양을 이 날짜로 기록한다(실제 점령은 1790년 4월 16일).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["이아시 조약 — 크림의 결정적 상실과 투를라(드네스트르) 국경", "a56fd194"], "d": ["5년 전쟁의 끝에 체결된 조약으로 투를라(드네스트르)강이 국경으로 정해졌다. 강의 좌안은 러시아에, 우안은 오스만에 남았고, 외지와 그 일대는 결정적으로 상실되었다. 오스만 국가는 크림을 되찾겠다는 희망을 완전히 버리고 1783년의 병합을 법적으로 인정했으며, 왈라키아와 몰다비아는 2년간의 세금 면제를 조건으로 반환되었다. 1,200만 쿠루시의 전쟁 배상금 의무까지 받아들임으로써 흑해 북쪽은 영구히 러시아에 넘겨졌다. 같은 날짜에 합류한 다른 곳: 이즈마일.", "277ee99d"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["파즈반도을루 오스만의 비딘 실질 지배", "0ce70361"], "d": ["니자므 제디드(신질서) 조치에 반발해 봉기한 파즈반도을루 오스만은 비딘 총독을 달아나게 하고 도시를 장악한 뒤, 도나우강을 따라 깊은 참호를 파서 요새화했다. 1797년 세력의 절정기에 그는 8만에 가까운 병력을 모아 니코폴리스, 시스토바, 루세, 소피아, 니시를 지배하에 두었으며, 자신을 반란자가 아니라 개혁가로 내세웠다. 바브알리(오스만 정부)가 1798~1799년에 몇 달에 걸쳐 벌인 포위는 성과가 없었고, 그는 1807년 죽을 때까지 북부 불가리아에서 반독립적으로 통치했다.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["제국 육군 공병학교(뮈헨디스하네이 베리이 휘마윤)의 개교", "e9a3a34b"], "d": ["니자므 제디드 군대에 포병·공병·측량(지도) 장교를 길러 내기 위해 하스쾨이에 육군 공병학교가 문을 열었다. 이는 1773년에 설립된 해군 공병학교에 대응하는 육군의 기관이었다. 교과에서는 대수학, 기하학, 역학, 축성술, 탄도학을 가르쳤고, 유럽 언어의 수학·포술 서적이 번역되었다. 튀르키예 근대 공학 교육의 뿌리로 여겨지는 이 학교는 오늘날 이스탄불 공과대학교의 시초로 인정된다.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["프랑스에 대한 선전 포고와 러시아·영국과의 동맹", "80e95bd7"], "d": ["나폴레옹의 이집트 점령에 대해 오스만 국가는 두 세기 반에 걸친 전통적인 프랑스와의 우호를 깨고 프랑스에 선전 포고를 했다. 같은 과정에서 역사상 처음으로 러시아와 동맹을 맺고 러시아 함대가 해협을 통과해 지중해로 나가는 것을 허용했으며, 이어 영국과도 동맹을 체결했다. 이 동맹 덕분에 이오니아 제도를 프랑스에게서 빼앗았으나, 해협을 외국 함대에 열어 준 일은 훗날 무거운 대가를 치르게 되는 선례가 되었다.", "7d8a9e45"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["아크레 방어전 — 나폴레옹의 격퇴", "56b5c45b"], "d": ["이집트에서 시리아로 진격한 나폴레옹은 아크레를 포위하고 두 달 동안 잇따라 공격을 가했다. 도시는 제자르 아흐메드 파샤가 영국 함대의 지원과 이스탄불에서 보낸 니자므 제디드 부대의 도움으로 지켜 냈다. 포위를 풀고 이집트로 철수할 수밖에 없었던 나폴레옹은 동방으로 뻗어 나가려는 꿈을 이 성벽 앞에 묻었다. 이 소식은 이스탄불에서 큰 기쁨으로 받아들여졌고, 새로 창설된 훈련 군대가 첫 중대한 시험을 통과한 증거로 여겨졌다.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["와하브파의 카르발라 습격", "522341ed"], "d": ["나지드에서 출발한 와하브파 병력은 카르발라에 들어가 도시를 약탈하고 이맘 후세인의 영묘를 파괴했으며 3,000명이 넘는 사람을 죽였다. 이라크에 있던 오스만의 쾰레멘(맘루크 출신) 총독들은 이 습격을 막지 못했고, 사건은 이란과 이스탄불 양쪽에서 큰 반발을 일으켰다. 이 공격은 사우드 운동이 더 이상 오아시스 토후국이 아니라 오스만의 성지를 위협하는 지역 세력으로 변모했음을 알리는 선언이었다.", "f571ab30"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["프랑스군의 이집트 철수", "00cfdc8c"], "d": ["오스만과 영국 군대가 육지와 바다에서 벌인 합동 작전의 결과, 먼저 카이로가, 이어 알렉산드리아가 인수되었고 프랑스군은 배에 실려 본국으로 보내졌다. 3년간의 점령이 끝나면서 이집트는 서류상으로는 오스만의 통치로 돌아갔으나, 쾰레멘 베이들과 알바니아 부대 사이의 패권 다툼이 나라를 혼란에 빠뜨렸다. 이 공백은 몇 해 안에 카발라 출신 메흐메드 알리가 부상하는 토대가 된다.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["파리 조약 — 프랑스와의 평화 회복", "1b76991f"], "d": ["이집트 철수 뒤 체결된 조약으로 오스만 국가와 프랑스 사이의 전쟁 상태가 공식적으로 끝나고 옛 카피툴라시옹(특혜 조약)이 갱신되었다. 프랑스 상선의 흑해 진입이 허용되었고, 그 대신 프랑스는 오스만의 영토 보전을 인정했다. 평화가 회복되면서 러시아와 영국 사이에 끼여 있던 셀림 3세의 대외 정책은 다시 운신의 여지를 얻었다.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["와하브파의 타이프 점령", "7b791359"], "d": ["사우드 이븐 압둘아지즈가 이끄는 와하브파 병력은 히자즈를 향한 첫 움직임으로 타이프를 포위하고 약탈했다. 이 도시는 성지로 들어가는 첫 관문으로서 함락되었다. 두 성지(하라마인)의 수호자라는 칭호를 지닌 오스만 술탄에게 이는 술탄 권위의 정당성을 직접 뒤흔드는 타격이었다. 두 달 반 뒤 같은 군대는 메카로 진격하게 된다.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["와하브파의 첫 메카 점령", "21157c05"], "d": ["타이프가 함락되고 두 달 반 뒤, 와하브파 병력은 메카에 들어가 영묘들을 허물고 자신들의 이해에 따른 질서를 세웠으며, 샤리프 갈리브는 제다로 물러날 수밖에 없었다. 순례길이 막힌 일은 이슬람 세계 전체에 반향을 일으켰고, 이스탄불은 이집트 총독 메흐메드 알리에게 군사 원조를 요청하지 않을 수 없었다. 이 첫 지배는 석 달밖에 지속되지 않는다.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["샤리프 갈리브의 메카 탈환", "83d08dff"], "d": ["제다로 물러나 있던 샤리프 갈리브는 모은 병력으로 메카를 포위했고, 25일간의 포위 끝에 와하브파에게서 도시를 되찾았다. 후트바는 다시 오스만의 이름으로 낭독되었다. 이 두 번째 지배도 오래가지 못해, 사우드 병력이 1806년에 도시를 다시 점령하게 된다.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["제1차 세르비아 봉기의 시작", "0f6e8767"], "d": ["베오그라드의 행정을 장악한 반란 예니체리 다히(우두머리)들이 세르비아 유력자들을 집단 학살하자, 카라조르제(카라 요르기)의 지도 아래 무장 저항이 시작되었다. 처음에는 술탄에게 충성을 지키며 다히들만을 상대로 벌였던 이 운동은 곧 자치와 독립을 요구하는 민족 봉기로 바뀌었다. 세르비아군은 1806년 베오그라드를 점령했으며, 이 봉기는 발칸의 민족주의 독립 운동에서 첫 번째 고리가 되었다.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["와하브파의 메디나 점령", "84e310d7"], "d": ["메카에 이어 메디나도 와하브파 병력의 손에 들어갔다. 라우다 무타하라(예언자 영묘)의 보물은 흩어졌고 도시의 돔 영묘들은 허물어졌다. 이로써 두 성지가 한꺼번에 오스만의 통제에서 벗어났고, 다마스쿠스와 이집트에서 오는 순례 대상은 여러 해 동안 길을 나서지 못했다. 메디나는 7년이 지난 1812년에야 메흐메드 알리 파샤의 아들 토순 파샤가 지휘하는 이집트군이 되찾을 수 있었다.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["러시아와의 전쟁 개시(1806~1812년 오스만·러시아 전쟁)와 해협 봉쇄", "ea170804"], "d": ["나폴레옹의 아우스터리츠 승리 뒤 프랑스에 가까워진 셀림 3세가 러시아의 압력에도 왈라키아와 몰다비아의 공(보이보드)들을 파면하자, 러시아군이 두 공국을 점령하여 전쟁이 시작되었다. 오스만 국가는 해협을 러시아 함대에 닫았고, 이에 영국도 러시아 편에 서서 이스탄불에 함대를 보냈다. 6년간 이어질 이 전쟁은 카바크츠 반란과 셀림 3세의 폐위와 뒤얽히며, 1812년 부쿠레슈티 조약에서 베사라비아를 잃는 것으로 끝나게 된다.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["영국 함대의 이스탄불 앞바다 진입(덕워스 작전)", "195bb58f"], "d": ["오스만 국가가 프랑스와의 관계를 끊도록 강요하려던 영국은 덕워스 제독이 지휘하는 함대를 다르다넬스 해협으로 통과시켜 이스탄불 앞에 정박시켰다. 프랑스 대사 세바스티아니의 지휘까지 더해져 이스탄불 주민이 총동원되었고, 해안 포대는 며칠 만에 보강되었다. 함대는 도시에 포격을 가하기도 전에 철수할 수밖에 없었으며, 돌아가는 길에 다르다넬스에서 큰 손실을 입었다. 수도가 처음으로 외국 함대의 위협을 이토록 가까이에서 받은 일은 해협 문제를 유럽 외교의 중심에 올려놓았다.", "bf71116c"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["칼레이 술타니예 조약 — 영국과의 강화와 해협 원칙", "fe282117"], "d": ["덕워스 작전이 실패한 뒤 영국과 체결한 조약으로 두 나라 사이의 전쟁이 끝났고, 영국 상인의 옛 특권이 회복되었다. 문서에 실린 이른바 '오랜 원칙' 조항은 평시에 어떠한 외국 군함도 해협을 통과할 수 없다는 것을 명문화했다. 이 원칙은 19세기 내내 해협 체제를 규정하게 되는 모든 국제적 합의의 법적 근거가 되었다.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["슬로보지아 패전 — 도나우 방면군의 포위", "54b60fd1"], "d": ["루세 앞에서 도나우강을 건넌 오스만군의 대부분은 쿠투조프가 강 건너편에서 펼친 포위 기동으로 슬로보지아에서 갇혀 굶주림에 내몰렸다. 수천 명의 병사가 항복할 수밖에 없었고, 대재상 휘하의 병력은 사실상 녹아 없어졌으며, 바브알리는 한 달 뒤 휴전을 요청해야 했다. 이 패배는 1812년 부쿠레슈티 조약에서 베사라비아를 내주는 데 동의한 직접적인 원인이다.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["베오그라드 탈환과 제1차 세르비아 봉기의 진압", "06f56f52"], "d": ["부쿠레슈티 조약으로 러시아의 지원을 잃은 세르비아 반란군은 보스니아와 루멜리아에서 온 병력의 합동 작전을 버텨 내지 못했다. 후르시드 아흐메드 파샤가 베오그라드에 입성했고, 9년간의 봉기는 완전히 진압되었다. 카라조르제는 오스트리아로 달아났고, 스메데레보 산자크는 다시 오스만의 직접 통치에 편입되었다. 그러나 가혹한 조치는 2년 뒤 밀로시 오브레노비치가 이끄는 두 번째이자 항구적인 봉기를 촉발하게 된다.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["제2차 세르비아 봉기와 밀로시 오브레노비치의 대공(바슈크네즈) 지위", "e6e82ad2"], "d": ["첫 번째 봉기가 진압된 뒤 시행된 가혹한 조치에 맞서 밀로시 오브레노비치의 지도 아래 새로운 봉기가 터졌고, 이번에 바브알리는 무력 대신 타협을 택했다. 체결된 협정으로 밀로시는 '바슈크네즈'(수석 크네즈) 칭호를 인정받았고, 세금 징수와 내정 운영의 권한은 세르비아 크네즈들에게 맡겨졌다. 이 실질적 자치의 첫 맹아는 1830년의 칙령과 1878년의 독립으로 이어지는 과정의 출발점이 되었다.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["왈라키아 봉기 — 입실란티스의 프루트강 도하와 블라디미레스쿠의 봉기", "67d46a98"], "d": ["러시아군 장군이던 알렉산드로스 입실란티스는 필리키 에테리아의 이름으로 프루트강을 건너 왈라키아와 몰다비아에서 그리스인의 전면 봉기를 일으키려 했고, 같은 무렵 투도르 블라디미레스쿠도 현지 농민을 동원했다. 두 운동은 합쳐지지 못했다. 블라디미레스쿠는 튀르크에 함께 맞서 싸우자는 입실란티스의 호소에 '나는 튀르크가 아니라 그리스인에 맞서 봉기했다'고 답했고, 얼마 지나지 않아 입실란티스의 부하들에게 살해되었다. 반란은 5월에 오스만군에 진압되었으나, 파나리오트 공(보이보드) 체제는 끝났고 반란의 불길은 모레아로 번졌다.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["리야드에서 제2차 사우드 국가의 수립", "34dad3bd"], "d": ["1818년 디리야가 함락되고 제1차 사우드 국가가 무너진 지 6년 뒤, 투르키 이븐 압둘라는 나지드에서 이집트 수비대를 몰아내고 리야드를 중심으로 새로운 사우드 토후국을 세웠다. 새 정권은 히자즈로 뻗어 나가는 것을 피하고 나지드에 머무는 쪽을 택했으며, 오스만·이집트 병력과의 직접 충돌을 멀리했다. 이 두 번째 국가는 세기말까지 존속하며 오늘날 사우디아라비아 건국으로 이어지는 사슬의 두 번째 고리가 된다. 같은 날짜에 상실한 다른 정착지: 디리야(나지드).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["아케르만 협정 — 세르비아와 두 공국에 대한 양보", "c75f15d0"], "d": ["예니체리 군단을 폐지한 직후 군대 없이 남게 된 오스만 국가는 러시아의 최후통첩 앞에서 가혹한 조건의 협정을 받아들일 수밖에 없었다. 세르비아에 약속한 자치가 확인되었고, 왈라키아와 몰다비아의 공들은 러시아의 승인 없이 파면할 수 없다는 점이 인정되었으며, 러시아 상선에는 해협에서의 완전한 자유가 부여되었다. 2년 뒤 바브알리가 그리스 문제를 이유로 협정을 인정하지 않겠다고 선언하자, 러시아는 이를 전쟁의 명분으로 삼게 된다.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["티마르 제도의 청산", "84d5d1d6"], "d": ["예니체리 군단 폐지 1년 뒤, 루멜리아와 아나톨리아의 53개 산자크에 있던 약 5,200명의 티마르 보유 시파히가 티마르 수입과 함께 아사키리 만수레 군의 기병으로 전환되었다. 이로써 오스만의 토지·조세·군대 질서를 4세기 동안 떠받쳐 온 티마르 체제가 사실상 끝났다. 비게 된 티마르는 국고로 넘어갔고, 중앙에서 봉급을 주는 군대와 현금 조세 제도로 이행하는 길이 열렸다.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["제국 의학교(트프하네이 아미레)의 설립 — 근대 의학 교육의 시작", "ac3e57c0"], "d": ["새로 창설된 아사키리 만수레 군에 의사와 외과의를 길러 내기 위해, 수석 어의(헤킴바시) 무스타파 베흐제트 에펜디의 제안으로 셰흐자데바시에 제국 의학교가 문을 열었다. 수업은 유럽의 교과 과정에 따라 편성되었고 처음에는 프랑스어로 가르쳤다. 몇 해 뒤 제국 외과학교(제라흐하네이 아미레)도 설립되어 두 기관이 합쳐졌다. 튀르키예 근대 의학 교육의 시초로 여겨지는 이 학교는 오늘날 이스탄불 의과대학의 기원으로 인정된다.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["1828~1829년 오스만·러시아 전쟁의 발발", "9dff4e05"], "d": ["나바리노에서 함대가 불타고 바브알리가 아케르만 협정을 인정하지 않겠다고 선언하자, 러시아는 두 전선에서 동시에 전쟁을 선포했다. 예니체리 군단은 막 폐지되었고 새 군대는 아직 창설 단계에 있었으므로 오스만의 방어는 처음부터 취약했다. 러시아군은 도나우강을 건너는 한편 동쪽에서는 카르스와 아할치헤를 점령했다. 1년 안에 에디르네까지 진격한 러시아군은 1829년 에디르네 조약의 가혹한 조건과 그리스의 독립을 강요하게 된다.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["아메리카 합중국과의 첫 조약", "d737516f"], "d": ["여러 해에 걸친 접촉 끝에 체결된 통상·항해 조약으로 미국은 오스만 영토에서 최혜국 지위와 해협의 상업 통항권을 얻었다. 별도의 비밀 조항은 오스만이 원할 때 미국 조선소에서 배를 건조하게 하고 완성된 배와 목재를 살 수 있도록 규정했다. 미국 상원은 조약은 비준했으나 이 비밀 조항은 18 대 27의 표결로 부결했다. 그래도 선박의 길은 막히지 않았다. 헨리 에크포드는 1831년에 가져온 배를 오스만에 팔았고, 아이날르카바크에서 일한 미국인 장인들은 함대에 새로운 형식의 배를 마련해 주었다. 이 조약은 오스만 국가가 유럽 밖의 나라와 맺은 최초의 포괄적 관계를 보여 주는 문서가 되었다.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["바그다드에서 쾰레멘(맘루크 출신) 통치의 종식", "7e1d38a3"], "d": ["중앙 집권 정책을 추진하던 마흐무드 2세는 요구한 돈을 보내지 않고 중앙에서 온 관리를 살해하게 한 바그다드 총독 다우드 파샤를 반란자로 선포했다. 알리 르자 파샤가 지휘하는 병력은 90일간의 포위 끝에 도시를 점령했고, 쾰레멘은 거의 전원이 숙청되었다. 이로써 1704년 이래 이어진 반독립적인 쾰레멘 통치가 끝났고, 이라크는 다시 중앙에 직접 편입되었다.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["마치카 병영에 육군사관학교(메크테비 하르비예) 설립", "bf31c7d9"], "d": ["아사키리 만수레이 무함마디예 군에 유럽식으로 교육받은 장교를 공급하기 위해 마치카 병영에 육군 사관 학교가 문을 열었다. 생도들은 수학, 지도 제작, 축성술, 외국어를 배웠고, 얼마 뒤에는 빈과 파리에 유학생을 보내 인력을 보강했다. 이 학교는 오스만군에서 사관학교 출신 장교의 전통, 나아가 19세기 말에 나타날 새로운 군인 지식인 세대가 태어난 곳이 되었다.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["트리폴리타니아의 중앙 직할화 — 카라만리 왕조의 종말", "faabcb96"], "d": ["카라만리 가문 내부의 왕위 다툼과, 1830년 프랑스의 알제 점령 이후 커진 유럽의 압력에 대응하여 바브알리는 트리폴리타니아에 직접 개입했다. 이스탄불에서 보낸 함대가 도시에 들어갔고, 마지막 카라만리 베이는 파면되어 이스탄불로 압송되었으며, 이 주는 중앙에서 임명한 총독에게 넘겨졌다. 124년의 왕조 시대가 끝나면서 북아프리카에서 오스만 국가가 직접 통치하는 마지막 영토가 공고해졌다.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["데프테르다르직의 폐지와 재무부(말리예 네자레티) 설립", "89f8125e"], "d": ["고전적 오스만 재정 질서의 우두머리인 데프테르다르(재무장관) 직이 폐지되고, 유럽식 부처인 재무부가 설립되어 흩어져 있던 국고들이 한 손에 모였다. 같은 해 바브알리의 다른 부서들도 네자레트(부)라는 이름으로 재편되어 근대적인 내각 구조로 이행했다. 이 조치는 1년 뒤 선포될 탄지마트 칙령의 행정적 기반을 마련한 가장 중요한 걸음 가운데 하나였다.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["영국의 아덴 정착", "ddbd556b"], "d": ["영국은 1802년 라헤지의 술탄 아흐메드 이븐 압둘카림과 맺은 통상·우호 협정을 근거로 아덴항에 군대를 상륙시키고 도시를 장악했다. 홍해 입구를 쥔 이 항구는 인도 항로의 석탄 보급 기지로서 영국 제국 전략의 요충이 되었다. 예멘에 대한 오스만 국가의 주장은 서류상으로는 계속되었으나, 남부 해안에 대한 실질적 지배는 이 이후 다시 돌아오지 않았다.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["티하마 해안으로의 복귀: 호데이다, 자비드, 모카 점령", "353982d2"], "d": ["1840년 이집트군의 철수로 주인 없이 남은 예멘 해안에, 메카 샤리프의 감독 아래 테브피크 파샤가 지휘하는 병력이 상륙하여 호데이다, 자비드, 모카 항구를 오스만의 통치에 편입했다. 사나까지 진격하려 했으나 주민의 저항 때문에 호데이다로 되돌아왔다. 이로써 고원 지대는 자이드파 이맘들에게 남았고, 오스만의 지배는 23년 동안 티하마 띠 지역에서만 이어졌다. 예멘 내륙은 1872년 아흐메드 무흐타르 파샤의 원정으로야 되찾게 된다.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["발타리만 협약: 왈라키아와 몰다비아에 대한 오스만·러시아 공동 보호", "d3bb22e9"], "d": ["1848년의 혁명이 왈라키아와 몰다비아로 번지자 오스만과 러시아의 병력이 두 공국을 함께 점령했었다. 발타리만에서 체결된 협약에 따라 공(보이보드)은 선거가 아니라 술탄이 7년 임기로 임명하며, 두 나라가 이 지역을 공동으로 감독하기로 결정되었다. 이 협정은 서류상 오스만의 주권을 유지하면서도 러시아에 실질적인 공동 권리를 인정했고, 도나우 공국들이 오스만에서 떨어져 나가는 것을 앞당겼다.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["헝가리 망명자 문제: 코슈트와 동료들의 오스만 망명", "1c7d7ef4"], "d": ["1848~1849년 헝가리 혁명이 러시아·오스트리아의 개입으로 진압되자, 러요시 코슈트와 수천 명의 헝가리인·폴란드인 난민이 오스만 영토로 피신했다. 오스트리아와 러시아는 난민의 인도를 강경하게 요구했으나, 바브알리는 영국과 프랑스의 지원을 받아 인도를 거부하고 이들을 퀴타히아에 정착시켰다. 코슈트의 일행은 그곳에 약 18개월 머물렀고, 수백 명의 난민이 이슬람으로 개종하여 오스만에 출사했다. 이 사건은 탄지마트 시대 오스만의 유럽 여론상의 위신을 높인 드문 외교적 승리 가운데 하나로 여겨졌다.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["엔쥐메니 다니시(학술원)의 설립: 이스탄불 최초의 오스만 아카데미", "6fda1365"], "d": ["공교육 최고 평의회의 결정으로 설립된 엔쥐메니 다니시는 튀르키예어 학술 서적과 교과서를 편찬하기 위해 조직한 최초의 오스만 학술원이다. 1851년 7월 18일 다륄마아리프 건물에서 의식을 치르고 문을 열었으며, 국내외 회원 가운데에는 아흐메드 제브데트 파샤도 있었다. 비록 단명했으나 제브데트 파샤의 『역사』와 『카바이디 오스마니예』(오스만어 문법) 같은 저작이 이 기관의 산물이었고, 튀르키예어가 학문의 언어가 되는 데 초석으로 여겨진다.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["올테니차 승리: 도나우 전선에서 오스만의 첫 성공", "a660ad2f"], "d": ["크림 전쟁의 개막 국면에서 총사령관(세르다르 에크렘) 외메르 뤼트피 파샤는 도나우강을 건너 올테니차에서 러시아군을 큰 손실을 입히며 격퇴했다. 이 승리는 전쟁 초두에 러시아의 진격을 저지함으로써, 오스만군이 탄지마트 이후의 훈련으로 얻은 힘을 유럽에 보여 주었다. 이 성공은 영국과 프랑스가 오스만 편에 서서 참전하기로 결정하는 것을 수월하게 한 심리적 기반을 마련했다.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["이스탄불에서 영국·프랑스와 맺은 동맹 조약", "04809278"], "d": ["크림 전쟁에서 러시아에 맞서 오스만 국가와 영국, 프랑스 사이에 체결된 동맹 조약은 세 나라가 합동 작전을 수행하며 동맹국이 전쟁이 끝나기 전에 단독 강화를 하지 않는다고 규정했다. 이로써 오스만 국가는 역사상 처음으로 유럽 강대국들과 대등한 당사자로서 군사 동맹에 들어갔다. 이 조약은 2년 뒤 파리에서 오스만이 유럽 국가 체제에 공식적으로 받아들여지는 법적 토대도 마련했다.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["이스탄불 시청(셰흐레마네티) 설립: 최초의 근대적 지방 자치 조직", "be4af27f"], "d": ["크림 전쟁 동안 이스탄불에 몰려든 연합군 병사와 늘어난 인구가 낳은 기반 시설 위기는 카디(재판관) 중심의 고전적 도시 행정의 한계를 드러냈다. 유럽의 선례를 따라 설립한 셰흐레마네티(시청)에 청소, 가격 통제(나르흐), 시장 감독, 건설 업무가 한 손에 모였고, 이듬해 베이올루·갈라타에 제6 시구(알튼즈 다이레이 벨레디예)가 시범 구역으로 조직되었다. 이 조치는 오스만 근대 지방 행정의 시작으로 인정된다.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["파리 조약: 크림 전쟁의 종결과 오스만의 유럽 국가 체제 편입", "4aee0e2a"], "d": ["크림 전쟁을 끝낸 파리 조약으로 오스만 국가는 유럽 국제법의 대등한 구성원으로 선언되었고, 영토 보전은 강대국의 공동 보장 아래 놓였다. 흑해는 중립화되었고, 러시아가 퀴취크 카이나르자 이래 내세우던 정교회 신민 보호권 주장은 무효가 되었으며, 베사라비아 남부(킬리야, 카훌, 이즈마일, 볼흐라드 군)는 몰다비아에 넘겨졌다. 그러나 이 조약은 개혁 칙령(이슬라하트 페르마느)을 국제적 약속으로 만듦으로써 내정 간섭의 문도 열어 놓았다.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["돌마바흐체 궁전의 개관: 통치 중심의 톱카프에서의 이전", "71ad26d0"], "d": ["압뒬메지드가 1842년 발리안 가문에 의뢰한 궁전이 14년의 공사 끝에 문을 열었고, 국가의 통치 중심은 4세기의 역사를 지닌 톱카프에서 보스포루스 해안으로 옮겨졌다. 유럽풍 양식, 크리스털 계단, 무아예데 홀(의전 연회장)을 갖춘 이 궁전은 탄지마트의 서구화 주장을 돌로 표현한 것이 되었다. 한편 그 막대한 비용은 오스만 재정이 외채의 악순환에 빠져든 시기에 가장 많이 비판받은 항목 가운데 하나가 되었다.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["쿠자 아래에서 왈라키아와 몰다비아의 통합: 루마니아의 탄생", "baef4da5"], "d": ["파리 조약 이후 치러진 선거에서 두 공국은 모두 알렉산드루 이오안 쿠자 대령을 공(보이보드)으로 선출하여 사실상의 통합을 이루었다. 바브알리와 오스트리아가 반대했으나, 프랑스가 지지한 기정사실은 받아들일 수밖에 없었다. 서류상으로는 오스만에 예속된 이 연합은 1862년에 루마니아라는 이름을 쓰게 되고, 1877년에는 일방적으로 독립을 선언한다. 이는 도나우강 일대에서 오스만 지배가 해체되는 과정의 전환점이다.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["쿨렐리 사건: 이스탄불에서 압뒬메지드에 대한 최초의 쿠데타 시도", "e3653b21"], "d": ["탄지마트 정책과 개혁 칙령이 비무슬림에게 부여한 평등에 반발한 군인과 민간인이 섞인 비밀 결사는, 술탄의 폐위를 계획하던 중 클르치 알리 파샤 모스크에서 모임을 갖다가 급습당했다. 피고들이 쿨렐리 병영에서 재판을 받았기 때문에 사건은 이 이름으로 불리게 되었고, 사형은 유배로 감형되었다. 이는 오스만 역사에서 이념적 동기로 결성된 조직이 시도한 최초의 궁정 쿠데타 시도로 인정된다.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["레바논산의 드루즈·마론파 내전과 다마스쿠스 사건", "5595fdd6"], "d": ["1860년 5월 시돈 근처에서 드루즈인 두 명이 살해되면서 터진 충돌은 산악 지대 사상 가장 피비린내 나는 드루즈·마론파 내전으로 번졌고, 7월에는 다마스쿠스로 옮겨붙어 수천 명의 기독교도가 목숨을 잃었다. 프랑스가 군대를 상륙시키자 바브알리는 푸아드 파샤를 비상 권한과 함께 이 지역에 파견했고, 강경한 진압 작전이 벌어졌다. 이 사건들은 유럽 개입의 구실이 되었으며, 레바논이 특별 지위를 얻은 직접적인 원인이 되었다.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["『테르쥐마느 아흐발』의 창간: 이스탄불 최초의 튀르키예어 민간 신문", "24792957"], "d": ["아가흐 에펜디가 발행하고 시나시가 편집을 맡은 『테르쥐마느 아흐발』은 국가의 지원 없이 발행된 최초의 튀르키예어 신문이다. 창간호의 서문은 백성이 자신의 일에 대해 말할 권리를 옹호했으며, 신문은 시나시의 『시인의 결혼』을 연재함으로써 근대 튀르키예 문학의 문도 열었다. 오스만에서 여론이라는 개념과 반정부 언론의 탄생은 이 날짜로 거슬러 올라간다.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["레바논산 조직 규정: 레바논의 특권 무타사리프령 지위", "bf375603"], "d": ["1860년의 학살 뒤 강대국의 압력으로 마련된 이 규정은 레바논산을 바브알리에 직속되고 종파 간 균형에 따라 구성된 행정 평의회가 다스리는 특권 무타사리프령으로 만들었다. 무타사리프는 오스만 신민인 가톨릭 기독교도여야 하고 그 임명은 강대국의 승인에 부쳐야 한다고 규정했으며, 초대 무타사리프는 다우드 파샤였다. 이 체제는 1915년까지 이어지며 근대 레바논 국가의 핵을 이루게 된다.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["압뒬메지드의 서거와 술탄 압뒬아지즈의 즉위", "27204d7c"], "d": ["22년의 치세 동안 탄지마트 칙령과 개혁 칙령에 서명한 압뒬메지드가 결핵으로 쓰러지자 동생 압뒬아지즈가 즉위했다. 새 술탄은 초기 몇 해 동안 절약 조치와 검소한 생활로 희망을 주었고, 해군을 세계의 손꼽히는 해군력 가운데 하나로 만들었다. 그러나 치세 말년에는 막대한 외채, 1875년의 파산, 발칸의 반란이 쌓여 1876년 폐위 운동의 토대를 마련하게 된다.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["통합 공국이 루마니아라는 이름을 채택", "d960e3fc"], "d": ["1859년 쿠자의 이중 선출로 사실상 통합된 왈라키아와 몰다비아는 1862년 의회와 정부를 부쿠레슈티의 한 지붕 아래로 모으고 공식적으로 루마니아라는 이름을 채택했다. 오스만 국가는 법적으로는 종주국의 지위와 연간 공납을 유지했으나, 공국에 대한 통제권은 사실상 잃었다. 도나우강 북쪽에서 4세기에 걸친 오스만 영향력의 종말은 이 날짜로 상징된다.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["수아킨, 마사와, 다흘라크의 이집트 편입", "a0924860"], "d": ["1846년 술탄 압뒬메지드가 수아킨과 함께 이집트 헤디브 메흐메드 알리 파샤에게 살야네(수입 할당)로 주었던 마사와는, 헤디브 이스마일 파샤 시대에 다흘라크, 수아킨과 함께 이집트 영토에 편입되어 카이마캄(군수)령의 지위로 조직되었다. 이로써 홍해의 아프리카 연안에 있는 이 세 항구는 법적으로는 오스만 영토로 남았으나, 행정적으로는 바브알리에서 직접 카이로로 넘어가, 이웃한 이집트·수단과 같은 속국 층에 들어갔다.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["크레타 반란의 시작(1866~1869)", "3679b861"], "d": ["그리스의 공공연한 지원으로 섬에서 터진 대규모 봉기는 크레타 그리스인의 에노시스(그리스와의 합병) 요구를 처음으로 국제 문제로 만들었다. 3년간 이어진 격렬한 산악전은 오스만군에 큰 손실을 안겼고 유럽 여론에 큰 반향을 일으켰다. 반란은 1868년 알리 파샤가 섬에 건너가 폭넓은 특권을 인정하는 조직 규정을 시행하고서야 겨우 가라앉았다.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["베오그라드와 세르비아 요새에서 마지막 오스만 수비대의 철수", "b34217db"], "d": ["강대국의 압력과 미하일로 공의 끈질긴 요구에 따라, 바브알리는 세르비아에 남아 있던 마지막 군사 거점을 비우는 데 동의했다. 1867년 4월 18일 베오그라드 요새의 오스만 군기가 내려졌고 열쇠는 공에게 넘겨졌다. 이로써 1521년 이래 이어진 오스만의 실질적인 군사 주둔이 끝났고, 세르비아의 독립으로 가는 길에서 마지막 큰 장애물이 사라졌다. 술탄의 종주권은 상징적인 깃발과 공납의 문제로만 축소되었다.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["이집트 총독에게 헤디브 칭호 수여", "09e10c12"], "d": ["카발라 왕조의 3대째인 이스마일 파샤의 집요한 로비와 이스탄불에 쏟아부은 돈의 결과, 이집트 총독에게 다른 총독들보다 우위에 있음을 강조하는 헤디브 칭호가 주어졌다. 같은 시기에 계승 방식도 아버지에서 아들로 넘어가도록 바뀌었으며, 이집트에는 외채 차입, 훈장 수여, 영사관 설치 같은 주권적 성격의 권한이 인정되었다. 이 조치들은 이집트의 오스만으로부터의 법적 이탈을 앞당긴 사슬의 첫 고리이다.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["크레타 조직 규정: 섬에 대한 폭넓은 행정 특권", "12052262"], "d": ["3년간의 반란을 끝내기 위해 대재상 알리 파샤가 직접 섬으로 건너갔고, 술탄의 재가를 받아 반포한 규정으로 크레타인에게는 혼합 행정 평의회, 지방 법원, 공무에서의 그리스어 사용, 세금 경감이 인정되었다. 이 조치는 섬에서 오스만의 지배를 30년 더 지탱했다. 그러나 기독교 주민에게 부여한 특권은 무슬림 크레타인의 입지를 약화시켰고 1896~1898년 위기의 씨앗을 뿌렸다.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["국가평의회(슈라이 데블레트)의 개원: 오스만 최고 행정 법원의 설립", "70b16497"], "d": ["1868년 3월 5일자 칙령에 따라 사법 최고 평의회가 둘로 나뉘어, 행정·입법 업무는 국가평의회에, 재판 업무는 최고 사법원(디바느 아흐캄 아들리예)에 맡겨졌다. 이 기관은 바브알리에서 의식을 치르고 문을 열었으며, 초대 의장에는 미드하트 파샤가 임명되었다. 법률안의 작성, 행정 분쟁의 해결, 관리에 대한 재판을 담당했다. 무슬림과 비무슬림이 섞인 구성원 구조를 지녀, 오스만에서 권력 분립 사상이 제도로 처음 적용된 것으로 여겨진다.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["수에즈 운하의 개통: 이집트를 거치는 인도 항로의 단축", "377ccd04"], "d": ["1859년에 시작된 공사는 10년이 걸렸고, 지중해와 홍해를 잇는 163km의 운하가 성대한 의식과 함께 개통되었다. 유럽과 인도를 잇는 길이 수천 마일 짧아지면서 이집트는 하루아침에 세계 무역의 요충이 되었다. 이 지정학적·전략적 가치는 운하 개통 13년 뒤 영국이 이집트를 점령하게 되는 가장 큰 원인이 되었고, 운하가 이집트에 지운 빚은 헤디브 정부를 파산으로 몰고 가게 된다.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["불가리아 총주교대리좌(엑사르흐청)의 설립: 불가리아 교회의 페네르로부터의 분리", "33a8272c"], "d": ["술탄의 칙령으로 그리스 총대주교청에서 분리된 독립 불가리아 교회(총주교대리좌)가 설립되었고, 어느 군이 여기에 속할지는 주민 투표에 맡겨졌다. 바브알리는 그리스의 영향력을 꺾으려고 이 조치를 취했으나 결과는 정반대였다. 이 교회는 불가리아 민족 정체성과 마케도니아에 대한 불가리아의 권리 주장을 조직하는 중심이 되었다. 이로써 발칸의 불가리아·그리스·세르비아 경쟁과 1876년 봉기의 제도적 토대가 놓였다.", "ce8f108b"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["미드하트 파샤의 나지드 원정: 알하사에서 오스만 지배의 재확립", "7db51461"], "d": ["바그다드 총독 미드하트 파샤는 사우드 가문 내부의 왕위 다툼을 이용하여 페르시아만 서안에 병력을 보내고, 알하사 지역을 나지드 산자크라는 이름으로 바스라 빌라예트에 편입했다. 압둘라 이븐 파이살을 무타사리프로 임명하여 서류상 오스만의 지배를 확립했다. 이 원정은 페르시아만에서 영국 세력의 확산을 저지하려는 것이었으며, 같은 해 카타르도 오스만의 통제에 들어오는 계기가 되었다.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["대재상 알리 파샤의 서거: 탄지마트 진용의 종말", "1cf0141c"], "d": ["1869년 푸아드 파샤가 죽은 뒤 탄지마트 정책을 홀로 떠받치던 알리 파샤가 세상을 떠남으로써, 30년 동안 국가의 대외 정책을 이끈 노련한 외교관 세대가 사라졌다. 그 뒤를 이은 마흐무드 네딤 파샤의 친러적이고 자의적인 통치는 압뒬아지즈의 개인 통치를 강화했다. 알리 파샤가 죽은 뒤 5년 안에 재정은 파산하고 발칸은 봉기했으며, 군주의 교체는 피할 수 없게 되었다.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["카타르에서 오스만 통제의 확립", "3b453165"], "d": ["영국의 압력을 받던 셰이크 카심 이븐 사니의 초청으로 오스만 병력이 카타르반도에 상륙했고, 1871년 가을 이 지역에 오스만의 통제가 확립되었다. 카타르는 나지드 산자크에 속한 카자(군)로 편성되었고 셰이크는 카이마캄(군수)에 임명되었다. 이 조치는 미드하트 파샤가 페르시아만에서 영국에 맞서 추진한 적극 정책의 가장 구체적인 성과였으며, 오스만 깃발은 1913년까지 반도에 휘날렸다.", "823711c3"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["사나 점령: 예멘에서 오스만 권위의 재확립", "978e20a0"], "d": ["수에즈 운하 개통으로 홍해의 전략적 가치가 커지자, 바브알리는 아흐메드 무흐타르 파샤의 지휘 아래 예비 사단 군대를 예멘에 보냈다. 사나를 점령함으로써 두 세기 동안 사실상 잃었던 예멘 내륙에 국가의 권위가 다시 세워졌고, 이 지역은 빌라예트(주)가 되었다. 그러나 자이드파 이맘과의 싸움은 끝내 그치지 않았고, 1891년, 1898년, 1904년의 반란은 오스만에 가장 비싸고 가장 오래 끈 국내 전선이 되었다. 같은 날짜에 합류한 다른 곳: 사나, 타이즈.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["헤르체고비나 봉기의 시작: 동방 문제의 재점화", "571b18ec"], "d": ["무거운 세금과 아얀(지방 유력자)의 압박 때문에 네베시네 일대에서 일어난 기독교 농민의 봉기는 곧 헤르체고비나 전역으로 번졌고, 세르비아와 몬테네그로에서 온 의용병으로 힘을 얻었다. 오스트리아와 러시아의 개혁 강요를 불러온 이 반란은 이듬해 불가리아 봉기와 세르비아·몬테네그로의 선전 포고를 촉발했다. 이로써 93년 전쟁(1877~78년 러시아·튀르크 전쟁)과 베를린 조약에 의한 발칸 상실로 이어지는 거대한 사슬의 첫 고리가 끊어졌다.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["오스만 재정의 파산: 외채 상환액의 절반 삭감", "2cac2fa5"], "d": ["1854년 이래 거듭 끌어 온 차관, 크림 전쟁 비용, 궁전 건축, 1873~74년의 아나톨리아 기근은 재정 적자를 500만 리라를 넘는 깊은 구렁으로 만들었다. 마흐무드 네딤 파샤 정부는 부채의 이자와 원금 상환을 5년 동안 절반으로 줄이겠다고 발표하여 사실상 모라토리엄을 선언했다. 유럽 증권 거래소에 큰 반발을 일으킨 이 결정은, 6년 뒤 무하렘 칙령과 오스만 공채 관리청(듀유느 우무미예)의 설립으로 귀결되는 과정의 시작이었다.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["무라드 5세의 폐위와 압뒬하미드 2세의 즉위", "cffb2271"], "d": ["압뒬아지즈가 폐위된 뒤 즉위한 무라드 5세는 숙부의 죽음과 체르케스 하산 사건으로 정신 건강이 크게 흔들려 직무를 수행할 수 없게 되었다. 93일의 재위 중 판단력이 온전했던 날은 7일뿐이었다. 그는 셰이휠이슬람의 파트와로 폐위되었고 동생 압뒬하미드 2세가 그 자리에 올랐다. 새 술탄은 미드하트 파샤에게 입헌제를 선포하겠다고 약속하고 즉위했다. 33년에 걸친 한 시대가 시작되고 있었다.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["테르사네(조선소) 회의: 강대국의 발칸 개혁 강요", "b5006a2c"], "d": ["발칸 위기를 해결하기 위해 강대국이 이스탄불에서 소집한 회의는 불가리아를 두 개의 자치 빌라예트로 나누고, 보스니아 헤르체고비나에 국제 감독 아래의 개혁을 시행할 것을 요구했다. 바브알리는 회의가 열린 날 대포를 쏘아 카눈 에사시(헌법)의 선포를 알림으로써, 강요에 헌정 개혁으로 맞서려 했다. 대표들은 이를 시간 끌기로 여기고 1877년 1월 20일 해산했으며, 넉 달 뒤 러시아가 선전 포고를 했다.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["돌마바흐체에서 제1차 하원(메즐리시 메부산)의 개원", "429bb279"], "d": ["카눈 에사시에 따라 선출된 115명의 의원은 1877년 3월 19일 돌마바흐체 궁전의 무아예데 홀에서 열린 의식과 함께 처음으로 모였다. 이로써 오스만 역사에 대의 의회 시대가 시작되었다. 무슬림과 비무슬림 의원들은 정부를 날카롭게 추궁했고, 전쟁의 지휘와 장관들의 책임을 토론했다. 이 대담한 반대는 의회의 수명을 단축시킨 가장 큰 원인이 되었다.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["플레브나 방어전의 시작: 가지 오스만 파샤의 저항", "0e04a878"], "d": ["93년 전쟁에서 도나우강을 건넌 러시아군의 이스탄불 진격로를 차단하기 위해 비딘에서 플레브나로 진군한 오스만 파샤는 읍을 보루와 참호로 요새화하고 다섯 달에 걸친 전설적인 방어전을 시작했다. 러시아·루마니아군의 세 차례 연속된 대공세는 큰 손실을 입고 격퇴되었으며, 차르 알렉산드르 2세가 직접 지휘하던 군대는 포위전으로 전환할 수밖에 없었다. 플레브나는 19세기 오스만군의 가장 빛나는 방어 성공으로 역사에 남았다.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["플레브나 함락: 도나우 전선의 붕괴", "185e7602"], "d": ["다섯 달의 포위 끝에 식량이 바닥난 오스만 파샤는 비트강을 건너는 돌파 작전에 나섰으나, 부상을 입고 포로가 되자 도시는 항복했다. 러시아 지휘관들은 포로가 된 파샤에게 칼을 돌려주며 경의를 표했고, 오스만 파샤에게는 '가지' 칭호가 주어졌다. 플레브나가 함락되면서 러시아군의 앞길이 열렸다. 두 달 안에 소피아, 필리베(플로브디프), 에디르네가 함락되었고 러시아 선봉대는 예실쾨이에 이르렀다.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["러시아군의 소피아 점령", "ef369d22"], "d": ["플레브나 함락 뒤 발칸산맥을 넘은 러시아군은 무방비 상태의 소피아에 들어왔다. 이 도시는 다시는 오스만의 통치로 돌아가지 않았으며, 1878년 말 자치 불가리아 공국의 수도가 되고 1879년에는 실질적인 수도가 된다. 지도에서 소피아는 이 날짜부터 오스만의 직접 통치에서 벗어나 러시아의 임시 점령에, 이어 불가리아의 자치 통치에 넘어간다.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["에디르네 휴전: 93년 전쟁에서 총성이 멎다", "1f899180"], "d": ["소피아, 필리베, 에디르네가 잇따라 함락되고 러시아군이 마르마라해 연안까지 육박하자 바브알리는 휴전을 요청할 수밖에 없었다. 에디르네에서 체결된 정전 협정은 불가리아의 자치, 몬테네그로·세르비아·루마니아의 독립, 무거운 전쟁 배상금 같은 예비 강화 조건을 오스만이 받아들이게 했다. 이 조건들은 한 달 뒤 산스테파노에서 조약문으로 바뀌게 된다.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["압뒬하미드 2세의 하원(메즐리시 메부산) 무기 휴회", "e770b540"], "d": ["전쟁이 참혹한 결과로 끝난 데 대해 정부와 궁정에 책임을 묻는 의원들의 거센 비판이 일자, 압뒬하미드 2세는 카눈 에사시(헌법)가 자신에게 부여한 권한을 근거로 의회를 무기한 휴회시켰다. 약 11개월 동안 활동한 최초의 오스만 의회는 이렇게 문을 닫았고, 30년에 걸친 전제 정치(이스티브다드) 시대가 시작되었다. 의회는 1908년 혁명 뒤에야 다시 소집될 수 있었다.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["산스테파노 조약: 대불가리아 구상", "2c7cc611"], "d": ["93년 전쟁을 끝낸 산스테파노 조약은 에게해까지 뻗고 마케도니아를 포함하는 거대한 자치 불가리아를 세우고, 세르비아, 몬테네그로, 루마니아의 독립을 인정했으며, 카르스, 아르다한, 바투미, 도우베야즈트를 러시아에 넘기는 데다 갚을 수 없는 전쟁 배상금까지 부과했다. 러시아를 지중해까지 내려오게 하는 이 문서는 영국과 오스트리아의 격렬한 반발을 샀다. 조약은 시행되기도 전에 넉 달 안에 베를린 회의에서 다시 조정되었지만, 그래도 오스만령 루멜리아의 종말을 선언한 문서로 남았다.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["오스트리아·헝가리의 보스니아 헤르체고비나와 예니파자르 점령", "e5f901df"], "d": ["베를린 조약이 부여한 권한을 근거로 오스트리아·헝가리군이 보스니아에 진입했다. 오스만 정부는 저항하지 않기로 했으나, 사라예보와 모스타르의 현지 무슬림과 정교도 주민은 무기를 들고 석 달 동안 완강하게 저항했다. 점령은 1878년 10월 20일에야 완료되었다. 술탄의 법적 주권은 1908년까지 서류상 존속했지만, 4세기에 걸친 오스만의 보스니아는 사실상 상실되었고 대규모 무슬림 이주의 물결이 시작되었다. 같은 날짜에 상실한 다른 정착지: 바냐루카.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["무하렘 칙령과 오스만 공채 관리청의 설립", "02b7cc03"], "d": ["1875년의 파산 뒤 채권국 대표들과 진행한 협상은 1299년 무하렘월 28일(1881년 12월 20일)자 칙령으로 결말을 맺었다. 부채 원금은 절반 넘게 삭감되었고, 그 대신 소금, 담배, 비단, 인지, 어업세 같은 가장 수익성 높은 세입 항목이 채권자들이 직접 운영하는 오스만 공채 관리청(듀유느 우무미예)에 넘어갔다. 수천 명의 직원을 거느린 이 관청은 국가 안의 별도 재정 조직으로 변모했다. 이 날은 오스만의 재정적 독립이 사실상 끝난 날로 인정된다.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["수아킨 — 마흐디에게 함락되지 않은 유일한 항구", "5a37b198"], "d": ["1884년 2월부터 수아킨을 제외한 동수단의 모든 지역이 무함마드 아흐마드 알마흐디의 지배에 들어갔으나, 이 항구는 그레이엄 장군이 지휘하는 3개 대대 규모의 영국군의 군사적 보호로 버텨 냈다. 이는 실효 상태와 법적 상태가 갈라진 시기의 시작이었다. 해안은 사실상 영국의 군사 통제 아래 있었지만, 행정적 연결은 1885년 이집트에서 거두어 예멘 빌라예트, 곧 바브알리에 직접 연결되었다. 이 체제는 1888년 프랑스의 제일라 점령으로 끝날 때까지 지속되었다.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["타이프 감옥에서 미드하트 파샤 살해", "f4562261"], "d": ["카눈 에사시의 설계자이자 제1차 입헌제의 상징적 인물인 미드하트 파샤는 압뒬아지즈의 죽음과 관련한 이을드즈 법정에서 유죄 판결을 받고, 사형이 유배로 감형되어 타이프로 보내졌다. TDV 기록에 따르면 그는 1884년 5월 7~8일 밤 감방에서 목이 졸려 살해되었고, 공식 사인은 '시르펜체'(악성 종기)로 발표되었다. 그의 죽음은 압뒬하미드 2세 시대 헌정 반대 세력 청산의 상징이 되었다.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["하이다르파샤·앙카라 철도 이권을 독일에 부여", "5705b163"], "d": ["술탄의 칙령으로 하이다르파샤·앙카라 노선의 건설·운영 이권이 도이체방크를 대표하는 은행가 알프레트 폰 카울라에게 주어졌고, 아나톨리아 철도 회사가 설립되었다. 이 이권은 오스만의 교통과 대외 정책에서 영국·프랑스의 독점을 깨뜨리고 독일의 영향력을 뿌리내리게 한 전환점이 되었다. 11년 뒤 같은 회사에 주어질 바그다드 노선 이권과 더불어 '베를린·바그다드'라는 꿈이 태어나고, 이는 제1차 세계 대전 이전 강대국 경쟁의 주요 축 가운데 하나가 된다.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["이스탄불에서 오스만 통일 협회(이티하디 오스마니)의 결성", "b7187939"], "d": ["군 의과 학교의 학생 네 명이 전제 통치에 맞서는 비밀 조직으로 오스만 통일 협회를 결성했다. 이 조직은 곧 청년 튀르크 운동의 모든 반대 세력을 한 지붕 아래 모으게 되는 통일진보위원회로 발전했다. 세포 방식의 조직은 유럽의 망명자들, 테살로니키의 장교들과 합류했다. 1908년에 제2차 입헌제를 선포하게 하고 1913년 이후 국가를 단독으로 통치한 핵심 인물들은 이 작은 학생 세포에서 나왔다.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["오스만 은행 습격: 다슈나크 활동가들의 갈라타 행동", "08b3095f"], "d": ["아르메니아의 다슈나크수툔 조직의 무장 단체는 아르메니아 문제에 유럽의 관심을 끌기 위해 갈라타에 있는 오스만 은행 본점을 습격해 인질을 잡고, 건물을 폭파하겠다고 위협했다. 위기는 대사들의 중재로 활동가들이 배를 타고 국외로 나가는 것을 대가로 끝났다. 습격에 뒤이은 며칠 동안 이스탄불에서 벌어진 유혈 사태는 아르메니아 문제가 국제 개입의 지렛대로 변모하는 데 결정적이었다.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["1897년 오스만·그리스 전쟁의 발발: 테살리아 전선", "33e490ab"], "d": ["그리스가 크레타에 함대와 병력을 상륙시키고 루멜리아 국경에서 비정규대의 공격이 이어지자, 오스만 국가는 선전 포고를 했다. 독일 군사 개혁 사절단이 훈련시킨 오스만군은 테살리아에서 신속히 진격하여 한 달 안에 라리사(예니셰히르), 파르살로스(차탈자), 도모코스(되메케)를 점령했고, 그리스군은 와해되었다. 강대국의 개입으로 획득한 영토는 반환되었으나, 이 전쟁은 압뒬하미드 2세 시대의 유일한 결정적 군사 승리로 남았고, 크레타의 실질적 상실은 막지 못했다.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["코니아·바그다드 노선 이권을 독일에 부여", "fd8b6cbd"], "d": ["카이저 빌헬름 2세의 1898년 이스탄불·다마스쿠스 방문에 이어, 아나톨리아 철도 회사에 코니아에서 바그다드와 바스라까지 뻗을 노선의 예비 이권이 주어졌다. 바그다드 철도 계획은 오스만에는 아랍 빌라예트에 대한 중앙의 통제를 강화하는 것을, 독일에는 페르시아만에 도달하는 것을 뜻했다. 영국과 러시아가 격렬히 반대한 이 계획은 제1차 세계 대전으로 이어지는 제국주의 경쟁에서 가장 논란이 컸던 사안 가운데 하나가 되었다.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["다마스쿠스에서 히자즈 철도 공사 착공", "62f58f68"], "d": ["압뒬하미드 2세가 1900년 5월 2일자 칙령으로 지시한 이 노선은 1900년 9월 1일 다마스쿠스에서 거행된 공식 의식과 함께 공사에 들어갔다. 전적으로 이슬람 세계에서 모은 성금과 오스만의 공병 장교·병사들의 노동으로 건설된 이 사업은 순례자의 다마스쿠스·메디나 여정을 40일에서 5일로 줄였다. 이는 칼리프의 정신적 권위를 공고히 하는 위신의 사업이자 히자즈에 대한 군사적 통제를 강화하는 전략적 투자였다.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["뮈르츠슈테크 프로그램: 마케도니아에서의 국제 개혁 감독", "4c7464da"], "d": ["일린덴 봉기 뒤 러시아와 오스트리아의 황제는 뮈르츠슈테크에서 만나 마케도니아를 위한 새로운 개혁안을 마련했다. 이 프로그램은 오스만 총감찰관 곁에 외국인 민정 대리인 두 명을 배치하고, 헌병대를 유럽인 장교들이 재편하며, 행정 경계를 민족 원칙에 따라 바꾸도록 규정했다. 바브알리는 주권이 침해된다는 이유로 버텼으나 공동의 압력 앞에서 받아들일 수밖에 없었다. 이 프로그램은 청년 장교들 사이에서 통일파의 조직화를 가속한 근본 요인 가운데 하나가 되었다.", "b56ab15c"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["사나를 이맘 야흐야에게 상실", "e7f876cb"], "d": ["자이드파 이맘 야흐야 하미드앗딘이 1904년에 일으킨 봉기는 1905년 4월 포위 끝에 사나가 함락되는 것으로 이어졌다. 도시는 오스만의 통치에서 벗어났고, 포위 기간 동안 기근과 전염병이 돌았다. 예멘의 산악 지형, 긴 보급선, 자이드파 이맘 정권의 현지 정통성은 이곳의 오스만 지배를 수립 이래 늘 취약하게 만들었다. 도시는 다섯 달 뒤 큰 손실을 치르고 되찾게 되지만, 예멘 문제는 1918년까지 끝나지 않는다.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["이을드즈 암살 미수: 압뒬하미드 2세에 대한 폭탄 공격", "1ee2e1a6"], "d": ["다슈나크수툔 조직은 금요 예배 행차를 마치고 나오는 술탄의 마차를 겨냥해, 시한폭탄을 실은 란도 마차를 폭발시키는 암살을 시도했다. 압뒬하미드는 셰이휠이슬람과 대화하느라 몇 분 늦은 덕분에 목숨을 건졌다. 폭발로 26명이 죽고 50명이 넘는 사람이 다쳤다. 이 사건은 술탄의 안전 강박과 밀정 조직에 의존한 전제 통치를 더욱 강경하게 만들었으며, 테브피크 피크레트의 시 『한순간의 지체』의 소재가 되기도 했다.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["사나 탈환: 이맘 야흐야 반란의 진압", "dec3b8f9"], "d": ["1904년 자이드파 이맘 야흐야의 지도 아래 시작된 봉기는 1905년 4월 사나의 함락으로 이어졌고, 도시에는 기근과 전염병이 돌았다. 알리 르자 파샤와 아흐메드 페이지 파샤가 지휘하는 증원군은 1905년 7월 15일에서 9월 1일 사이에 타이즈에 있던 병력의 지원도 받아 벌인 작전으로 큰 손실을 치르고 도시를 되찾았으며, 반란은 진압되었다. 예멘 작전은 오스만군에 수만 명의 손실과 막대한 재정 부담을 안겼다. 루멜리아의 장교들 사이에서 '예멘 유배'에 대한 두려움은 통일파의 조직화를 키운 불만 가운데 으뜸이었다.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["제2차 입헌제의 첫 하원(메즐리시 메부산) 소집", "e7fd2716"], "d": ["30년의 공백 뒤 치른 2단계 선거로 구성된 의회는 1908년 12월 17일 술탄의 연설과 함께 개원했고, 청년 튀르크 운동의 지도자 아흐메드 르자 베이가 의장으로 선출되었다. 튀르크인, 아랍인, 알바니아인, 그리스인, 아르메니아인, 유대인 의원으로 구성된 이 의회는 오스만주의 이상의 마지막 큰 시험이었다. 그러나 불가리아의 독립, 보스니아의 병합, 크레타의 그리스 합병 선언은 의회가 열리기도 전에 이 낙관론에 그늘을 드리웠다.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["행동군과 압뒬하미드 2세의 폐위: 메흐메드 5세 레샤드의 즉위", "6a65a704"], "d": ["3월 31일 사건에 대응해 테살로니키에서 출발한 행동군은 4월 22~23일 밤 네 갈래로 이스탄불에 입성했고, 4월 24일 이을드즈 궁전이 항복했다. 국민 총회(메즐리시 우무미이 밀리)는 4월 27일 압뒬하미드 2세의 폐위를 결정했다. 술탄은 테살로니키로 보내졌고, 동생 메흐메드 5세 레샤드가 왕위에 올랐다. 이로써 33년의 개인 통치가 끝났으나, 그 자리는 술탄이 상징에 머물고 통일진보위원회가 군의 지원으로 통치하는 새 시대가 차지했다.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["알바니아 반란: 코소보와 슈코더르의 무장 저항", "93ed30c6"], "d": ["통일파 정부의 중앙 집권적 조세 정책, 무기 회수 운동, 라틴 문자 논쟁은 그때까지 국가에 가장 충성스러운 집단 가운데 하나로 여겨지던 알바니아 부족들을 봉기하게 만들었다. 마흐무드 셰브케트 파샤가 지휘하는 군대가 반란을 강경하게 진압했으나, 불안은 1911년과 1912년에 다시 타올랐다. 이 반란들은 발칸 전쟁 전야의 오스만군을 소모시켰고, 알바니아 민족 운동의 탄생도 앞당겼다.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["우시 조약: 트리폴리와 벵가지를 이탈리아에 할양", "4ffa1fd2"], "d": ["발칸 국가들의 전쟁 준비 앞에서 두 전선의 충돌을 감당할 수 없었던 바브알리는 스위스의 우시 마을에서 이탈리아와 비밀 강화를 체결하고 트리폴리타니아와 벵가지를 포기했다. 오스만 국가는 이로써 아프리카의 마지막 영토를 잃었다. 그 대가로 이탈리아가 점령한 로도스와 도데카네스 제도를 돌려주겠다는 약속을 받았으나, 이 약속은 끝내 지켜지지 않았다. 조약이 체결될 때에는 발칸 전쟁이 이미 시작된 뒤였다. 이 사건으로 무르주크(페잔), 가트, 세바, 우바리, 트라간, 자윌라, 알카트룬(페잔(트리폴리타니아 빌라예트의 산자크))이 이탈리아의 통치에 넘어갔다.", "5896634d"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["대재상 마흐무드 셰브케트 파샤의 이스탄불 암살", "68e60e63"], "d": ["바브알리 습격 뒤 대재상에 임명된 마흐무드 셰브케트 파샤는 육군부로 가던 중 차르시카프 근처에서 마차에 가해진 총격으로 살해되었다. 통일진보위원회는 암살의 책임을 반대 세력에 돌려 대대적인 체포와 처형의 물결을 일으켰고, 자유 연합당(휘리예트 베 이틸라프)은 사실상 청산되었다. 이 사건과 함께 엔베르·탈라트·제말 삼두를 기반으로 한 통일파의 일당 독재가 확고히 수립되었다.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["제2차 발칸 전쟁의 발발: 동맹국들의 분배 다툼", "48d088a2"], "d": ["런던 조약으로 오스만에게서 빼앗은 땅을 나누지 못한 발칸 동맹국들은 서로 다투게 되었고, 불가리아가 세르비아와 그리스의 진지를 공격하면서 두 번째 전쟁이 시작되었다. 루마니아와 몬테네그로까지 불가리아에 맞서 참전하자 불가리아군은 무너졌다. 오스만 국가는 이 기회를 이용해 런던 조약이 그은 미디예·에네즈선을 넘어, 에디르네를 비롯한 동트라키아를 되찾았다.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["이스탄불 조약: 불가리아와의 강화와 에디르네의 확정", "c8c18b2d"], "d": ["제2차 발칸 전쟁 뒤 오스만 국가와 불가리아 사이에 체결된 조약은 마리차강을 국경으로 삼아, 에디르네, 크르클라렐리, 디디모티호와 동트라키아가 오스만에 남는 것을 법적으로 확정했다. 데데아아치(알렉산드루폴리)는 불가리아에 남았고(한편 카발라는 1912년 가을 불가리아가 점령한 뒤 1913년 7월에 그리스로 넘어갔으며, 1913년 8월 10일 부쿠레슈티 조약으로 그리스령으로 확정되었다), 두 나라 사이의 상호 주민 교환과 불가리아 내 무슬림의 권리가 규정되었다. 발칸의 참화에서 되찾을 수 있었던 유일한 영토를 보장한 것이 이 문서이다. 같은 날짜에 합류한 다른 곳: 코모티니(귀뮐지네).", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["아테네 조약: 그리스와의 강화와 테살로니키·요안니나의 양도", "8e94def7"], "d": ["오스만 국가와 그리스 사이에 체결된 조약은 발칸 전쟁에서 잃은 테살로니키, 요안니나, 남마케도니아가 그리스에 넘어가는 것을 공식적으로 인정했고, 크레타에 대한 오스만의 권리를 포기했다. 그리스에 남은 무슬림의 종교와 재산권, 바크프(종교 재단)의 지위, 무프티 임명이 상세히 규정되었다. 그러나 에게해 섬들의 지위는 해결되지 않은 채 남아 두 나라 사이의 끊임없는 긴장의 원천이 되었다.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["이스탄불에서 오스만·독일 비밀 동맹 조약 체결", "0472efb3"], "d": ["유럽에서 전쟁이 터지자마자, 대재상 사이드 할림 파샤의 저택에서 오스만 국가와 독일 사이의 비밀 동맹 조약이 체결되었다. 문서는 러시아가 독일을 상대로 참전할 경우 오스만도 독일 편에 서도록 규정했다. 이 조약은 내각에조차 숨겨져 네 사람만이 알고 있었다. 석 달 뒤 흑해 기습으로 오스만 국가는 사실상 전쟁에 휘말려 들었고, 제국의 운명은 이 문서에 묶이게 된다.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["카피툴라시옹의 일방적 폐지", "ec773d18"], "d": ["유럽이 전쟁에 몰두하던 때, 오스만 정부는 외국인에게 사법·재정·관세상의 특권을 인정한 카피툴라시옹을 1914년 10월 1일부터 일방적으로 폐지한다고 선언했다. 4세기에 걸친 이 특권 질서의 종식은 국내에서 큰 독립의 환호 속에 받아들여졌고 이스탄불에서는 축하 행사가 열렸다. 동맹국 독일을 포함한 모든 나라가 이 결정에 항의했으며, 카피툴라시옹은 1923년 로잔에서야 최종적으로 역사 속으로 사라지게 된다.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["흑해 기습: 오스만 함대의 러시아 항구 포격", "8ad4ef61"], "d": ["독일에서 탈출하여 '구매한' 것처럼 오스만 해군에 편입된 괴벤과 브레슬라우(야부즈와 미딜리)는 수숑 제독의 지휘 아래 흑해로 나가 러시아 항구들을 포격하고 선박을 격침했다. 엔베르 파샤가 내각 몰래 내린 이 명령은 중립을 사실상 끝냈다. 일주일 안에 러시아, 영국, 프랑스가 선전 포고를 했고, 오스만 국가는 돌이킬 수 없이 제1차 세계 대전에 참전하게 되었다.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["영국·인도군의 파우 점령 — 이라크 전선의 개막", "08663813"], "d": ["협상국이 오스만 국가에 선전 포고를 한 다음 날 아침, 바레인에서 대기하던 영국·인도 여단은 샤트알아랍 하구의 파우에 상륙했다. 황폐한 파우 요새에 있던 소규모 오스만 부대는 군함의 포화 아래 철수했고, 인도 전신선의 중계소는 영국의 손에 넘어갔다. 이라크 전선은 이렇게 열렸다.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["대성전(지하드이 에크베르) 선포: 파티흐 모스크에서 성전 파트와 낭독", "2a6174e8"], "d": ["셰이휠이슬람 위르귀플뤼 하이리 에펜디가 내린 다섯 건의 파트와가 칼리프 겸 술탄의 이름으로 파티흐 모스크에서 낭독되어, 모든 무슬림에게 협상국에 맞선 성전이 촉구되었다. 독일이 큰 기대를 건 이 조치는 영국과 프랑스 식민지의 무슬림을 봉기시키려는 것이었다. 기대했던 전면 봉기는 일어나지 않았으며, 오히려 2년 뒤 메카의 아미르 샤리프 후세인이 영국의 지원으로 반란을 일으킨 일은 칼리프제의 정치적 영향력의 한계를 뼈아프게 보여 주었다.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["쿠르나의 영국군에 대한 항복", "621d36b0"], "d": ["바스라 함락 뒤 티그리스강과 유프라테스강이 합류하는 쿠르나로 물러난 바스라 총독 수브히 베이의 병력은 12월 4~8일의 교전 끝에 1914년 12월 9일 아침 항복했다.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["사르카므쉬 작전: 캅카스 전선의 참사", "5cbde7f0"], "d": ["엔베르 파샤는 1878년에 잃은 카르스·아르다한·바투미를 되찾고 캅카스의 튀르크인을 봉기시키기 위해, 한겨울에 제3군을 알라후에크베르 산맥 너머로 보내 러시아군을 포위하는 기동에 투입했다. 부족한 동계 장비, 바닥난 보급, 영하 30도에 이르는 눈보라 때문에 군대는 전투에 들어가기도 전에 녹아 없어졌고, 수만 명의 병사가 얼어 죽었다. 이 작전은 전쟁에서 오스만이 겪은 가장 참혹한 재앙 가운데 하나가 되었으며, 동부 전선을 2년 동안 무방비 상태로 만들었다.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["제1차 운하 작전: 시나이 사막을 넘은 수에즈 공격", "02dd72f5"], "d": ["제4군 사령관 제말 파샤는 영국의 점령에서 이집트를 해방하고 수에즈 운하의 통행을 막기 위해 시나이 사막을 가로지르는 공격을 감행했다. 오스만 부대는 운하 동안에 이르렀고 일부는 건너가는 데 성공했으나, 영국의 우세와 기대했던 이집트 민중 봉기의 불발로 철수했다. 작전은 목표를 이루지 못했지만, 영국이 이집트에 대규모 병력을 주둔시키지 않을 수 없게 함으로써 간접적인 전략적 효과를 낳았다.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["이송·정착(강제 이주, 테흐지르)법의 제정", "2f2bc22c"], "d": ["반(Van) 반란과 러시아의 진격 뒤, 정부는 전선 후방의 치안을 해친다고 판단된 주민을 군 사령관이 다른 지역으로 옮길 수 있도록 허용하는 임시법을 공포했고, 술탄은 1915년 5월 27일에 이를 재가했다. 시행 결과 아나톨리아 동부와 남부 빌라예트의 아르메니아인 대부분이 시리아와 모술 방면으로 이송되었으며, 이송 과정에서 질병, 기아, 습격으로 막대한 인명 손실이 발생했다. 이 결정은 오스만 말년의 가장 무거운 문제이자 오늘날까지도 가장 논쟁적인 문제로 남아 있다.", "e8af8dee"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["압뒬하미드 2세의 베일레르베이 궁전에서의 서거", "c9662582"], "d": ["1909년 폐위되어 먼저 테살로니키로 보내졌다가 발칸 전쟁에서 이 도시를 잃자 이스탄불로 옮겨져 베일레르베이 궁전에서 감시를 받으며 지내던 압뒬하미드 2세가 세상을 떠났다. 그는 33년의 치세 동안 국가를 전쟁에서 멀리 두어 시간을 벌려 했으나, 전제 통치로도 기억되었다. 그의 장례는 큰 인파 속에 치러졌고 디반욜루에 있는 마흐무드 1세 영묘에 안장되었다. 그의 죽음은 자신이 세운 질서가 이미 오래전에 청산된 전쟁 중의 한 해에 찾아왔다.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["브레스트·리토프스크 조약: 카르스, 아르다한, 바투미의 회복", "da82636f"], "d": ["볼셰비키 혁명 뒤 전쟁에서 이탈한 러시아와 동맹국 사이에 체결된 조약은 동부 전선을 닫았고, 오스만 국가에 1878년 베를린 조약으로 잃은 카르스, 아르다한, 바투미(엘비예이 셀라세, '세 개의 주')를 되찾아 주었다. 이는 오스만 역사에서 40년 만에 얻은 유일한 영토 획득이었다. 그러나 무드로스 휴전 뒤 이 지역은 다시 상실되었고, 최종 해결은 1921년 카르스 조약으로 이루어졌다.", "f6f15123"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["메흐메드 5세 레샤드의 서거와 메흐메드 6세 바흐데딘의 즉위", "d302ba07"], "d": ["트리폴리타니아 전쟁, 발칸 전쟁, 세계 대전으로 점철된 9년의 치세를 보낸 메흐메드 5세 레샤드가 전쟁의 가장 위태로운 시기에 세상을 떠났고, 동생 바흐데딘이 메흐메드 6세라는 이름으로 즉위했다. 새 술탄은 통일파 세력의 후견에서 벗어나려 했으며, 넉 달 뒤 휴전이 체결되자 제국의 해체를 관리해야 하는 처지가 되었다. 그는 오스만 왕조의 36대이자 마지막 술탄이었다.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["협상국 함대의 이스탄불 입항과 도시의 실질적 점령", "d10cb14d"], "d": ["무드로스 휴전 뒤 영국, 프랑스, 이탈리아, 그리스 함선으로 이루어진 60척이 넘는 연합 함대가 돌마바흐체 앞바다에 닻을 내렸고, 이스탄불은 사실상 점령되었다. 465년 만에 처음으로 수도가 외국 군대의 통제 아래 들어간 것이었다. 같은 날 하이다르파샤에 내린 무스타파 케말 파샤가 그 광경을 보고 했다고 전해지는 '온 것처럼 돌아갈 것이다'라는 말은 민족 투쟁의 상징적 문장 가운데 하나가 된다.", "30db4974"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["에르주룸 회의: 동부 빌라예트의 민족 저항 결의", "41ef0457"], "d": ["동아나톨리아 권리 수호 협회가 소집한 회의는 영국의 압력으로 연기된 뒤 56명의 대표로 개막했고, 군에서 사임한 무스타파 케말 파샤가 의장으로 선출되었다. 회의는 민족의 국경 안에서 조국은 하나의 전체이며, 위임 통치와 보호령은 받아들일 수 없고, 정부가 해체되면 민족이 스스로 자신의 운명을 장악할 것이라고 선언했다. 이 결정들은 여섯 달 뒤 국민 서약(미사크 밀리) 문서의 핵심을 이루게 된다.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["시바스 회의: 민족 저항의 단일 조직으로의 통합", "0e9ad36b"], "d": ["1919년 9월 4일 시바스 술타니 학교에서 활동을 시작한 회의는 전국 각지의 권리 수호 협회를 아나톨리아·루멜리아 권리 수호 협회라는 이름 아래 통합하고 대표 위원회를 선출했다. 미국의 위임 통치안은 긴 토론 끝에 부결되었다. 9월 11일에 발표된 선언으로 민족 투쟁은 하나의 중심을 지닌 정당한 정치 운동이 되었고, 이스탄불 정부와의 공공연한 권력 투쟁이 시작되었다.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["아마시아 의정서: 이스탄불 정부와 대표 위원회의 회담", "40e6a6ab"], "d": ["다마트 페리드가 실각하고 알리 르자 파샤 정부가 수립된 뒤, 해군 장관 살리흐 파샤가 대표 위원회와 회담하기 위해 아마시아에 파견되었다. 합의된 의정서로 이스탄불 정부는 아나톨리아 운동의 존재를 사실상 인정했고, 하원(메즐리시 메부산)의 소집, 자유로운 선거 실시, 민족 국경의 보전이 받아들여졌다. 이는 민족 투쟁이 이스탄불을 상대로 거둔 최초의 공식적인 정치적 성과이다.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["마지막 오스만 의회의 국민 서약(미사크 밀리) 채택", "6322865e"], "d": ["마지막 오스만 하원(메즐리시 메부산)에서 121명의 의원이 서명한 국민 서약 문서는 무드로스선 안에 남아 있으며 무슬림 튀르크인이 다수인 영토의 불가분한 일체성, 아랍 빌라예트와 서트라키아에서의 주민 투표, 카피툴라시옹의 폐지, 완전한 정치·재정 독립을 조건으로 내걸었다. 이 문서는 1920년 2월 17일 만장일치로 채택되어 세계에 공표되었다. 이 선언은 민족 투쟁의 정치 강령인 동시에 로잔에서 지켜 낼 국경의 지도이기도 했으며, 협상국이 3월 16일 이스탄불을 공식 점령한 직접적인 원인이 되었다.", "576d2af5"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["귐뤼 조약: 튀르키예 대국민의회 정부의 첫 국제 조약", "9232c690"], "d": ["캬즘 카라베키르가 지휘하는 동부 전선군이 사르카므쉬와 카르스를 되찾자 아르메니아는 강화를 요청했고, 귐뤼에서 체결된 조약으로 세브르 조약을 인정하지 않으며 동방의 영토 요구를 포기한다는 데 동의했다. 앙카라 정부가 서명한 이 첫 조약은 세브르를 사실상 거부한 최초의 국제 문서가 되었고, 튀르키예 대국민의회에 법적 승인의 길을 열어 주었다. 이로써 동부 국경이 확보되어 병력을 서부 전선으로 옮길 수 있게 되었다.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["제1차 이뇌뉘 전투: 정규군의 첫 승리", "4add3719"], "d": ["새로 창설된 정규군은 부르사 방면에서 진격해 오던 그리스군을 이뇌뉘 진지에서 저지하여 후퇴하게 만들었다. 군사적으로는 제한된 규모의 성공이었으나 정치적 결과는 매우 컸다. 앙카라 정부는 런던 회의에 초청되었고, 소비에트 러시아와의 모스크바 조약으로 가는 길이 열렸으며, 기본 조직법(테슈킬라트 에사시예)이 채택되었다. 국내 여론에서 정규군에 대한 신뢰도 이 승리로 공고해졌다.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["제2차 이뇌뉘 전투: 그리스 공세의 두 번째 좌절", "a974521c"], "d": ["런던 회의에서 성과를 얻지 못한 그리스군은 부르사와 우샤크 방면에서 새로운 공세에 나섰으나, 다시 이뇌뉘 능선에서 저지되어 후퇴할 수밖에 없었다. 무스타파 케말 파샤가 이스메트 파샤에게 보낸 '귀관은 그곳에서 적뿐만 아니라 민족의 불운한 운명까지 이겨 냈다'는 전보는 이 승리 뒤에 쓰였다. 이 전투는 민족 투쟁의 국제적 위신을 높였고, 이탈리아의 아나톨리아 철수 과정을 가속했다.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["앙카라 협정: 프랑스와의 강화와 남부 전선의 종결", "35fc32db"], "d": ["사카리아 승리 뒤 앙카라에서 프랑스와 체결한 협정으로 남부 전선의 전쟁이 끝났다. 프랑스군은 아다나, 안테프, 마라슈, 우르파를 포함한 추쿠로바와 남동부를 비우고 시리아 국경으로 철수했다. 이로써 협상국의 한 나라가 앙카라 정부를 사실상 인정하게 되었고, 세브르 체제에 첫 균열이 생겼다. 비워진 지역에서 인수한 무기와 여유가 생긴 부대는 대공세 준비에서 결정적인 역할을 했다.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["무다니아 휴전: 이스탄불과 해협의 전쟁 없는 인도", "ac0d9baf"], "d": ["대공세 뒤 튀르키예군이 차나칼레와 이즈미트에서 영국군과 대치하게 되자 무다니아에서 회의가 소집되었고, 11일간의 치열한 협상 끝에 휴전으로 마무리되었다. 마리차강까지의 동트라키아를 15일 안에 그리스가 비워 튀르키예 행정에 넘기고, 이스탄불과 해협도 강화 조약과 함께 인도하기로 합의했다. 이로써 민족 투쟁의 무력 단계는 총알 한 발 쏘지 않고 얻은 외교적 승리로 막을 내렸고, 로잔으로 가는 문이 열렸다.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["메흐메드 6세 바흐데딘의 이스탄불 이탈과 압뒬메지드 에펜디의 칼리프 선출", "8ab0e847"], "d": ["술탄제 폐지 뒤 지위가 논란이 된 마지막 술탄 메흐메드 6세 바흐데딘은 1922년 11월 17일 금요일 아침 영국 전함 말라야호를 타고 이스탄불을 떠나 몰타로 갔다. 튀르키예 대국민의회는 이틀 뒤인 11월 19일 압뒬메지드 에펜디를 정치적 권한이 없는 칼리프로 선출했다. 623년에 걸친 오스만 왕조의 군주 통치는 이로써 사실상 끝났고, 칼리프제는 15개월 더 상징적으로 이어지게 된다. 몰타를 거쳐 이탈리아로 간 바흐데딘은 산레모의 빌라 노벨에 정착했다. 그는 이슬람 국가에 받아들여지기 위해 여러 차례 청원했으나 성과를 얻지 못했고, 1926년 5월 16일 그곳에서 술탄권과 칼리프권을 결코 포기한 적이 없다고 되풀이하며 숨을 거두었다.", "86831a04"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["코린토스가 모레아 전제공국에 넘어가다", "392495eb"], "d": ["1358년부터 피렌체의 아차이우올리 가문이 아카이아 공국에 속한 봉토로 지니고 있던 코린토스는 1395년 비잔티움의 모레아 전제공 테오도로스의 손에 넘어갔다. 이후 도시는 오스만에 정복될 때까지 전제공국의 통치 아래 있었다.", "1803a03a"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["코린토스 정복", "87a2bc59"], "d": ["파티흐의 모레아 원정에서 아크로코린토스 요새는 석 달 동안 포위되었다가 결국 평화적으로 항복을 받아냈다. 이로써 모레아의 관문으로 여겨지던 코린토스 지협이 오스만에 넘어갔다.", "b2be3a05"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["코린토스의 베네치아 이양", "9a25b6b9"], "d": ["파트라스가 함락된 뒤 코린토스는 평화적으로 베네치아인들에게 넘겨졌고 무슬림 주민들은 도시를 떠났다. 1687년 8월 모로시니의 군대는 아테네 원정을 위해 코린토스에 집결하고 있었다.", "d92bcf7d"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["코린토스 수복", "26f53e3a"], "d": ["다마드 알리 파샤의 모레아 원정에서 첫 번째 주요 목표는 코린토스였다. 오스만군은 1715년 6월 베네치아인들로부터 도시를 되찾고, 여기서 반도의 나머지 지역으로 진격했다.", "82e2e719"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["쿠웨이트 사바 토후국의 오스만 보호령 편입", "3584dba0"], "d": ["TDV의 쿠웨이트 항목에 따르면, 이 항구는 나즈드에서 온 우투브 부족이 18세기 초에 세웠고, 사바 가문은 그 세기 말 무렵에 통치권을 넘겨받았다. 알아흐사가 사우드 가문의 손에 넘어가던 바로 그 시기에, 와하비의 압박 앞에서 바스라에 의지하는 것 외에 다른 길이 없었던 이 토후국은 오스만의 보호 아래 들어갔다. 이 관계는 1871년 미드하트 파샤의 바스라 개편으로 공식화되어 쿠웨이트는 바스라 산자크의 세 카자(군) 가운데 하나로 간주되게 된다. 훗날 이라크의 영유권 주장도 이 기록에 근거한다.", "c084f05f"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["두브로브니크 공화국의 종말 — 프랑스의 점령", "f8e27bf1"], "d": ["캄포포르미오 조약(1797)으로 달마티아 해안에 자리 잡은 프랑스군은 1806년 5월 27일 두브로브니크를 점령하여 이 작은 상인 공화국을 종식시켰다. 이로써 1458년부터 오스만에 공납을 바치며 자치와 통상 특권을 지켜 온 두브로브니크의 3세기 반에 걸친 속국 지위가 끝났다. 지도에서 도시와 공화국의 믈레트(Mljet) 섬은 프랑스의 직접 통치로 넘어간다.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["수후미의 러시아 상실 — 흑해 동부 해안의 개방", "adc96bd4"], "d": ["1806-1812년 오스만-러시아 전쟁에서 러시아 함대는 흑해 동부 해안으로 향하여, 압하지아에서 오스만 지배의 거점이던 수후미 요새(수후미칼레)를 점령했다. 이 요새는 캅카스 부족들과의 연결과 연안 교역의 중심지였다. 이를 잃으면서 러시아는 처음으로 흑해 동해안에 영구적으로 자리를 잡았고, 캅카스에서 오스만의 영향력은 아나파와 포티 주변으로 좁아졌다.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["파르가의 오스만 통치 이양", "66e0cc5d"], "d": ["파르가는 1401년부터 베네치아의 손에 있었고 오스만의 통치를 받은 적이 한 번도 없었으며, 베네치아가 멸망한 뒤에는 차례로 프랑스와 영국에 넘어갔다. TDV의 테펠레나의 알리 파샤 항목은 상황을 이렇게 요약한다. 도시는 영국에 항복했고, 1819년에야 알리 파샤의 통치에 넘겨졌다. 이 이양은 주민 대다수가 이오니아 제도로 이주하는 결과를 낳았다. 이로써 파사로비츠에서 베네치아에 남겨졌던 프레베자-파르가-보니차 삼각 거점 가운데 마지막 곳도 제국에 편입되었으며, 파르가는 94년 동안 오스만령으로 남게 된다.", "555a1119"]},
"OLAYLAR_EK6:1821-01-01:0":{"b": ["아르고스가 그리스 반란군의 손에 넘어가다", "be66a696"], "d": ["모레아 반란의 처음 몇 달 동안 아르고스와 그 일대는 오스만의 통치에서 벗어나 그리스 반란군의 손에 넘어갔다. 이 도시는 1821년 5월 오스만군의 반격 작전의 무대가 된다.", "c3ea2041"]},
"OLAYLAR_EK6:1821-05-05:0":{"b": ["아흐메드 케흐야가 아르고스를 점령, 도시가 약탈되고 불타다", "d6d3ac7b"], "d": ["아흐메드 케흐야의 군대는 아르고스에서 그리스인들을 격파하고 도시를 약탈하고 불태웠으며, 도시는 잠시 오스만의 통제로 돌아갔다.", "316a51a8"]},
"OLAYLAR_EK6:1821-05-15:0":{"b": ["아흐메드 케흐야가 아르고스에서 트리폴리차의 무슬림들과 합류해 트리폴리차로 진군하다", "9d679fd5"], "d": ["아흐메드 케흐야는 아르고스에서 트리폴리차의 무슬림들과 합류하여 트리폴리차를 향해 진군했으며, 아르고스는 다시 그리스 반란군의 통제 아래 들어갔다.", "596502da"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["코린토스가 그리스 반란군에게 넘어가다", "892dcdc6"], "d": ["그리스 독립 전쟁 중에 아크로코린토스는 반란군의 손에 넘어갔고, 요새 사령관 캬밀 베이는 포로가 되었다.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-07-24:0":{"b": ["드라말르 마흐무드 파샤가 아르고스에 본영을 설치하다", "c79abbfb"], "d": ["드라말르 마흐무드 파샤의 군대가 아르고스 평야에 진입했고, 파샤는 아르고스 읍에 본영을 설치했으며, 도시는 다시 오스만의 통제 아래 들어갔다.", "d931b635"]},
"OLAYLAR_EK6:1822-08-06:0":{"b": ["드라말르 마흐무드 파샤가 아르고스에서 철수하기 시작하다", "5e5afb74"], "d": ["아르고스를 점령한 지 2주도 되지 않아 철수할 수밖에 없게 된 드라말르 마흐무드 파샤는 휘하 군대의 첫 사단을 코린토스 방면으로 빼기 시작했으며, 아르고스는 다시 그리스 반란군의 손에 넘어갔다.", "9c49ab0c"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["아나볼루(나프플리오)의 반란군 상실", "1a67fa50"], "d": ["모레아에서 가장 견고한 요새를 갖춘 항구인 아나볼루는 1년이 넘는 봉쇄 끝에 굶주림으로 항복했다. 이 요새는 반란 초기부터 반도에 남아 있던 오스만 지배의 마지막 큰 거점이었으며, 이를 잃으면서 모레아 전역이 반란군의 손에 넘어갔다. 이 도시는 얼마 지나지 않아 새 그리스 국가의 첫 수도가 된다.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-30:0":{"b": ["레판토(이네바흐트)의 그리스 통치 이관", "c9d19d4b"], "d": ["그리스 반란 때까지 오스만의 수중에 남아 있던 코린토스만 북안의 레판토는 1829년 4월 상실되어 그리스의 통치 아래 들어갔으며, 읍의 이름은 고대의 이름인 나프팍토스로 바뀌었다. 도시의 무슬림과 유대인 주민은 완전히 사라졌고, 이곳은 작은 읍으로 변했다.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["프랑스의 알제 점령 — 300년 오자크의 종말", "0be8f568"], "d": ["채권 분쟁에서 비롯된 부채 사건을 구실로 프랑스는 알제 해안을 3년간 봉쇄한 뒤 시디 페루슈에 병력을 상륙시켰다. 3주간의 작전 끝에 후세인 데이가 항복했고, 1516년부터 이어진 오스만의 알제 오자크가 끝났다. 점령은 수도에 그치지 않았다. 내륙의 틀렘센, 셰르셸, 메데아도 같은 해 여름에 상실되었다. 해안 전체가 프랑스의 통제 아래 들어가기까지는 24년이 더 걸리게 된다.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["에우보이아의 그리스 할양 — 섬(카리스토스, 오레오이)과 함께", "7b524aa4"], "d": ["그리스 독립 전쟁 내내 격렬한 전투의 무대였으나 오스만의 수중에 남아 있던 에우보이아는 평화 조약이 발효된 뒤인 1831년 그리스에 넘겨졌다. 1470년 이래 중요한 해군 기지였던 이 도시의 무슬림 주민들은 모든 재산을 헐값에 팔고 집단으로 오스만 영토로 이주했다. 도시는 오랫동안 비어 있었으며, 독일 여행가 팔메라이어는 1842년 이곳을 유령 도시라고 묘사했다.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["프랑스의 오랑 점령", "a8415d66"], "d": ["스페인이 1792년 전쟁 없이 넘겨준 오랑은 알제 서부에서 가장 큰 항구였다. 수도가 함락된 지 6개월 뒤 프랑스군이 이 도시에 들어왔다. 여기서 시작된 서부 작전은 머지않아 15년 동안 이어질 아미르 압드 알카디르의 저항에 부딪히게 된다.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["안나바(본) 점령", "21f37fb1"], "d": ["알제리 동부의 튀니지 국경에 가까운 항구 안나바는 프랑스군에게 점령되어 콩스탕틴을 향한 진군의 기지가 되었다. 이 도시는 또한 사르데냐 섬 맞은편의 가장 가까운 아프리카 항구였다.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["아테네의 새 그리스 국가 이양 (바이에른 부대가 아크로폴리스를 인수한 날)", "deee4d37"], "d": ["1456년부터 오스만령이던 아테네는 그리스 독립 전쟁 동안 여러 차례 주인이 바뀌었고, 아크로폴리스의 수비대는 1827년에 다시 오스만의 통제 아래 들어갔다. 런던 의정서로 그어진 국경선 북쪽에 남게 되었기 때문에 도시는 새 왕국에 이양되었고 수비대는 아크로폴리스에서 철수했다. 지도의 날짜는 바이에른 부대가 아크로폴리스를 인수한 날이며, 오스만 수비대의 실제 철수는 며칠 뒤에 이루어졌다(St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, 13장; Finlay, Journals and Letters, 제1권, 67쪽). 이듬해 아테네는 아나볼루를 대신해 그리스의 수도로 선포되었다.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["베자이아(부지) 점령", "a8927e00"], "d": ["카빌리 산맥이 바다로 열리는 곳에 있는 베자이아 항구는 알제와 안나바 사이 해안선의 마지막 독립 고리였다. 함포 사격의 지원을 받아 점령되었으나, 그 뒤편의 산악 내륙은 30년이 더 지나도록 프랑스의 통제 아래 들어가지 않았다. 이러한 연안 점령들은 오스만령 알제리가 지도에서 해마다 녹아 없어지는 과정을 이룬다.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["세티프 점령", "2073731a"], "d": ["콩스탕틴이 1년 전에 함락된 뒤 프랑스군은 고원으로 올라가 옛 로마 도시 세티프를 점령하고 이곳에 상설 수비대를 두었다. 세티프는 해안과 사하라 사이의 대상로가 교차하는 지점이었으며, 이곳의 점령은 프랑스가 이제 항구뿐 아니라 내륙 교역망까지 장악하기 시작했음을 보여 주었다.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["비스크라 점령 — 사하라의 관문 상실", "d895cad0"], "d": ["비스크라는 아틀라스 산맥 남쪽 기슭에서 사하라로 열리는 관문이자 대추야자 오아시스의 중심지였다. 아미르 압드 알카디르의 저항이 꺾이기 시작하던 시기에 이곳이 점령되면서 프랑스의 통제는 처음으로 사막의 북쪽 가장자리에 닿았다. 이후의 작전은 이제 오아시스에서 오아시스로 나아가는 사막 원정이 되었다.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["투구르트 점령 — 알제리 전체의 상실", "33c056e2"], "d": ["사하라 북부의 오아시스 도시 투구르트가 점령되면서, 1830년에 시작된 점령은 오늘날 알제리의 북반부에서 완료되었다. 이 시기에 오스만 국가는 크림 전쟁에서 프랑스와 같은 편에서 싸우고 있었으며, 알제리에 대한 법적 권리를 공식적으로 포기한 적은 없었으나 실제로는 단 한 걸음도 내딛지 못했다. 북아프리카에 남은 유일한 영토는 트리폴리였다.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["엘오베이드 함락 — 코르도판이 마흐디군에게 넘어가다", "58299f62"], "d": ["스스로를 마흐디라 선언한 무함마드 아흐마드가 일으킨 운동은 수단에서 이집트의 통치에 맞서 빠르게 확산되었다. 코르도판의 중심지 엘오베이드는 4개월간의 포위 끝에 함락되어 반란의 수도가 되었으며, 도시의 국고와 무기고는 이 운동이 군대로 조직되는 것을 가능하게 했다. 수단은 법적으로 여전히 오스만에 속한 이집트 케디브국의 영토였으므로, 이 상실은 지도에서 제국의 본체로부터 빠진다.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["하르툼 함락 — 수단 전역의 상실", "d4b98464"], "d": ["10개월에 걸친 포위 끝에 마흐디군은 청나일과 백나일이 합류하는 지점의 하르툼에 진입했다. 도시의 총독 고든은 살해되었고, 구원을 위해 파견된 영국군 부대는 이틀 늦게 도착했다. 이날 이후 센나르, 동골라, 코르도판을 포함한 수단 전역은 14년 동안 마흐디국의 통치 아래 있었다. 이 지역은 1899년에야 오스만과의 연결이 완전히 끊긴 상태로 영국-이집트 공동 통치에 들어가게 된다.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["이탈리아의 마사와 점령 — 홍해 서해안의 상실", "c333b95b"], "d": ["하베시 주의 중심지였던 마사와 항구는 마흐디 반란이 수단을 뒤덮은 혼란을 틈탄 이탈리아에게 점령되었으며, 이것이 이탈리아령 에리트레아의 핵심이 되었다. 북쪽의 수아킨과 앞바다의 다흘락 제도도 같은 과정에서 상실되었다. 이로써 야부즈 술탄 셀림 시대부터 이어진 홍해 서해안의 오스만 지배는 끝났고, 홍해는 이제 양안이 모두 외국의 것인 바다가 되었다.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["이탈리아의 로도스 점령", "e08662c5"], "d": ["트리폴리 전쟁에서 오스만 국가를 협상 테이블에 앉히려 했던 이탈리아는 전쟁을 지중해로 확대하여 로도스에 병력을 상륙시켰다. 섬은 며칠 만에 항복했다. 1522년 카누니가 오랜 포위 끝에 점령해 390년 동안 지켜 온 로도스는 이로써 동지중해에서 제국의 가장 큰 섬 기지 지위를 잃었으며, 우시 조약에서는 임시 점령으로 간주되었으나 다시는 되찾지 못했다.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["이탈리아의 도데카네스 제도 점령", "200aacf2"], "d": ["로도스를 점령한 지 몇 주 만에 이탈리아 해군은 주변의 섬들도 점령했으며, 이 군도는 훗날 '도데카네스'라는 이름을 얻게 된다. 섬들 대부분은 아나톨리아 해안에서 몇 마일 떨어진 곳에 있었고 에게해 남동부의 통로를 장악하고 있었다. 이 점령은 우시 조약에서 트리폴리를 포기하는 대가로 임시적인 것으로 간주되었으나 이탈리아는 섬을 결코 비우지 않았으며, 섬들은 1947년에 그리스로 이양되게 된다.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["코스 점령", "ab246c62"], "d": ["도데카네스 작전의 마지막 고리인 코스는 보드룸 반도 바로 맞은편에 있는 비옥하고 인구가 많은 섬이었다. 이 섬이 점령됨으로써 에게해 남동쪽 모퉁이의 모든 섬이 이탈리아의 통제 아래 들어갔고, 아나톨리아 남서 해안 전체가 외국의 섬 사슬에 둘러싸이게 되었다.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["이카리아의 독립 선언", "c4452033"], "d": ["사모스와 키오스 사이의 작은 섬 이카리아에서는 이탈리아의 점령이 낳은 불확실한 상황 속에서 주민들이 봉기해 오스만 헌병을 섬에서 몰아내고, 자체 국기와 우표, 의회를 갖춘 '자유 국가'를 선포하여 다섯 달 동안 유지했다. 1912년 11월 섬은 그리스에 편입되었다. 작은 규모에도 불구하고 이 사건은 에게해에서 중앙 행정이 어떻게 해체되었는지를 분명히 보여 준다.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["사모스의 오스만 통치 이탈", "3a862f2b"], "d": ["사모스는 1832년부터 오스만에 세금을 바치고 이스탄불이 임명한 베이가 다스리던 자치 공국이었다. 트리폴리 전쟁이 만든 공백 속에서 섬의 통합파 운동이 통치권을 장악하면서 자치 공국 체제는 사실상 끝났고, 섬은 같은 해에 그리스에 편입한다고 선언했다. 아나톨리아 해안에서 2킬로미터 떨어진 이 섬은 에게해에서 가장 먼저 잃은 영토 가운데 하나가 되었다.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["이오안니나 함락 — 이피로스와 파르가의 상실", "d42fce18"], "d": ["발칸 전쟁에서 다섯 달 동안 포위된 이오안니나는 비자니 진지가 함락된 뒤 항복했으며, 도시와 함께 이피로스 전역이 그리스에 넘어갔다. 이오안니나 산자크에 속한 파르가도 이때 상실되어 94년간의 오스만 통치가 끝났다. 이오안니나의 상실은 제국이 아드리아해로 열어 둔 마지막 창이 닫히는 것을 뜻했다.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["에디르네가 불가리아에 함락되다", "459d2e56"], "d": ["다섯 달 반에 걸친 포위 끝에 탄약과 식량이 바닥난 에디르네는 항복했고, 쉬크뤼 파샤는 포로가 되었다. 1361년부터 오스만령이었고 92년 동안 수도였던 이 도시의 함락은 발칸 전쟁의 가장 큰 타격으로 여겨졌다. 에디르네는 넉 달 뒤 제2차 발칸 전쟁에서 불가리아가 다른 전선에서 무너진 틈을 타 되찾게 된다.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["얀부가 샤리프 후세인의 군대에 넘어가다", "e291c816"], "d": ["샤리프 후세인이 6월에 일으킨 봉기는 홍해 연안으로 확산되었으며, 메디나의 항구인 얀부는 영국 해군의 지원 아래 반란군의 손에 넘어갔다. 이 항구는 봉기에 외부에서 들어오는 무기와 자금의 주요 관문이 되었다. 이로써 메디나의 파흐레딘 파샤 휘하 병력은 바다와의 연결이 끊겼고, 도시는 헤자즈 철도의 끝에 홀로 남게 되었다.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["제3차 가자 전투 — 가자와 칸유니스의 상실", "c142a069"], "d": ["두 차례의 실패 끝에 앨런비는 세 번째 공세에서 베에르셰바를 우회해 전선을 돌파했고, 여섯 달 동안 지켜 온 가자 방어선은 무너졌다. 가자와 그 남쪽의 칸유니스는 같은 날 철수되었다. 이 돌파는 팔레스타인 전선 붕괴의 시작이었으며, 예루살렘은 5주 뒤 함락된다.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["코모티니 점령 — 서트라키아의 상실", "904d813c"], "d": ["무드로스 휴전 이후 먼저 연합국 부대의 통제를 받게 된 서트라키아는 산레모 회의의 결정으로 그리스에 넘겨졌고, 그리스군이 코모티니에 진입했다. 1913년 불가리아로부터 되찾았던 이 지역은 제국이 루멜리아에서 잃은 마지막 영토가 되었다. 이 지역 튀르크 주민의 지위는 3년 뒤 로잔에서 소수민족 제도로 규정되게 된다. 이 점령으로 서트라키아의 코모티니, 크산티, 알렉산드루폴리, 수플리 카자가 그리스에 넘어갔다.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["일 칸국의 해체: 아부 사이드 바하두르 칸의 죽음", "0f187469"], "d": ["TDV 이슬람 백과사전의 일 칸국 항목에 따르면, 아부 사이드가 후계자 없이 죽으면서 한 세기 동안 이란을 지배한 일 칸국은 분열되었다. 아미르들은 왕위 다툼을 틈타 잘라이르 왕조, 흑양 왕조, 무자파르 왕조, 호라산의 사르바다르, 에레트나 왕조 같은 지방 왕조를 세웠다. 이 해체는 이 지역을 한 세기 동안 이어질 소국들의 모자이크로 나누었으며, 결국 티무르의 원정으로 다시 통합되게 된다.", "ebf54b53"]},
"OLAYLAR_EK7:1387-01-01:0":{"b": ["티무르가 이란 대부분을 지배 아래에 두다", "1cee2b82"], "d": ["TDV 이슬람 백과사전의 티무르 항목에 따르면, 1380년대 초부터 사르바다르, 카르트, 무자파르 같은 일 칸국 이후의 지방 왕조들을 하나씩 제거한 티무르는 1386-1388년의 '3년 원정' 동안 이란의 대부분을 사실상 지배 아래에 두었다. 다만 무자파르 왕조에 대한 최종 결말은 1393년에 났다. 이로써 이 지역은 한 세기에 걸친 분열 뒤에 다시 하나의 중앙 권력에 속하게 되었다.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["아라스 승리: 카라 유수프가 티무르 왕조의 아부 바크르 미르자를 격파", "4b61a75a"], "d": ["1405년 티무르가 죽은 뒤 망명에서 돌아온 흑양 왕조의 베이 카라 유수프는 아브니크를 점령해 동아나톨리아의 영토를 다시 차지한 뒤, 아제르바이잔과 두 이라크의 주인으로 여겨지던 티무르의 손자 아부 바크르 미르자를 향해 진군해 아라스강 가에서 그를 격파했다. 이 승리로 타브리즈가 흑양 왕조에 넘어간 것은 아니다. TDV의 타브리즈 항목은 1408년에 도시가 아부 바크르 미르자의 수중에 있었다고 적고 있으며, 아제르바이잔을 얻게 한 전투는 1408년 4월 13일의 사르드루드 전투이다.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["사르드루드 승리: 타브리즈와 아제르바이잔이 흑양 왕조에 넘어가다", "1f0a429d"], "d": ["카라 유수프는 아라스 전투에 이어 두 번째로 타브리즈 근처 사르드루드에서 티무르 왕조의 아부 바크르 미르자를 격파했으며, 이 승리로 흑양 왕조는 아제르바이잔을 얻었다. 카라 유수프는 이어 비스탐 베이에게 이라크 아자미의 정복을 맡겼다;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["이스탄불의 흑사병 유행과 궁정의 에디르네 이전", "70c7a163"], "d": ["TDV 이슬람 백과사전의 이스탄불 항목에 따르면, 도시의 빠르고 조밀한 정착은 때때로 전염병이 확산되는 토대가 되었다. 1466년의 흑사병 유행 때에는 궁정과 국가 고위 관료들이 일시적으로 에디르네로 물러났다. 도시 인구는 이러한 전염병으로 심각한 손실을 입었다.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["우준 하산이 흑양 왕조를 멸망시키다", "ef68399e"], "d": ["TDV 이슬람 백과사전의 우준 하산 항목에 따르면, 백양 왕조의 군주 우준 하산은 872년 라비 알아키르월 12일 / 1467년 11월 10일 빙괼-산자크 지방에서 흑양 왕조의 군주 자한 샤를 격파해 살해했다. 자한 샤의 아들 하산 알리는 1468년 9월 메란드에서 패했고 1469년 4-5월 하마단 앞에서 살해되어 흑양 왕조는 완전히 멸망했다. 영토는 백양 왕조의 지배로 넘어갔으며, 이 국가는 다음 10년 동안 이란 내륙까지 확장하게 된다.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["사흔-으 세만 마드라사의 교육 개시", "021f2a83"], "d": ["TDV 이슬람 백과사전의 사흔-으 세만 항목에 따르면, 파티흐 복합 시설 안에 세워진 이 여덟 개의 마드라사는 당대 최고 수준의 교육 기관으로 설계되었으며 오스만 울라마 위계의 정점을 이루었다. 이곳의 교수직과 졸업은 이후 수 세기 동안 카디와 교수 경력에서 가장 명망 높은 단계로 여겨졌다.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["톱카프 궁전(사라이-으 제디드)의 완공", "d2db6323"], "d": ["TDV 이슬람 백과사전의 톱카프 궁전 항목에 따르면, 당대 사료들은 공사의 착공 시점과 완공 시점이 서로 다르다. 바브-으 휘마윤 비문의 883년(1478)이라는 연대에 따르면, 파티흐의 명으로 아마도 1465년에 착공된 공사는 이 해까지 대부분 완료되었고, 궁전은 옛 궁전에 있던 국가 중심의 자리를 대신했다. 이로써 파디샤는 3세기 동안 국가의 행정과 의례의 심장이 될 새 거처로 옮겨 갔다.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["바예지드 2세의 이스탄불 즉위", "9b686d04"], "d": ["TDV 이슬람 백과사전의 바예지드 2세 항목에 따르면, 아마시아 산자크 베이였던 바예지드 왕자는 부친의 사망 소식을 듣고 서둘러 이스탄불로 와서 즉위했으며, 예니체리의 지지로 코니아에서 출발한 동생 젬을 앞질렀다. 즉위 때에는 관례대로 예니체리에게 즉위 하사금이 분배되었다. 이 왕위 교체는 두 형제 사이의 싸움에도 불을 붙였다.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["젬 술탄이 부르사에서 스스로 술탄을 선포하다", "b355168a"], "d": ["TDV 이슬람 백과사전의 젬 술탄 항목에 따르면, 카라만을 거쳐 부르사에 도착한 젬은 도시를 장악하고 스스로 술탄을 선포했으며 자신의 이름으로 쿠트바를 읽게 했다. 이 짧은 술탄 통치는 형 바예지드 2세가 보낸 군대가 예니셰히르에서 젬을 격파하면서 끝났다. 패배한 젬은 이집트 방면으로 도망쳐야 했다.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["게디크 아흐메드 파샤의 처형", "6d75a58c"], "d": ["TDV 이슬람 백과사전의 게디크 아흐메드 파샤 항목에 따르면, 오트란토 원정과 대재상직으로 알려진 파샤는 젬 술탄 문제에서의 태도와 그의 영향력에 대한 우려 때문에 바예지드 2세의 명으로 에디르네에서 처형되었다. 파티흐 시대의 가장 경험 많은 지휘관 중 한 사람의 죽음은 궁정에 큰 파장을 일으켰다.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["이스탄불 최초의 인쇄소 설립", "04475930"], "d": ["TDV 이슬람 백과사전의 인쇄술 항목에 따르면, 스페인에서 온 유대인 이주민 다비드와 사무엘 이븐 나흐미아스 형제는 이스탄불에서 히브리 문자로 인쇄하는 최초의 인쇄소를 세웠다. 이는 오스만 영토에서 활동한 최초의 인쇄 사업으로 기록되었다. 아랍 문자를 사용한 튀르크어 인쇄는 훨씬 뒤인 18세기에야 가능하게 된다.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["샤 이스마일의 타브리즈 점령: 사파비 왕조의 건국", "014d81e6"], "d": ["TDV 이슬람 백과사전의 사파비 왕조와 백양 왕조 항목에 따르면, 아르다빌 수도장의 젊은 셰이흐 이스마일은 아나톨리아의 키질바시 추종자들로 조직한 군대로 나흐치반 지방에서 백양 왕조의 술탄 엘반드를 크게 격파했다. 엘반드는 디야르바크르로 도망쳤고, 이스마일은 타브리즈에 입성해 왕좌에 올라 열두 이맘 시아파를 국교로 선포했다. 이로써 백양 왕조의 지배와 이 지역의 일 칸국 이후 소국 시대가 모두 끝나고, 3세기 동안 이어질 사파비 왕조가 세워졌다.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["이스탄불의 '작은 심판의 날' 지진", "53e3b1d6"], "d": ["TDV 이슬람 백과사전의 이스탄불 항목에 따르면, 도시를 덮친 강력한 지진은 당시 사람들 사이에서 '작은 심판의 날'로 불렸다. 성벽과 모스크, 수많은 건물에 심각한 피해가 났고 인명 손실도 매우 컸다. 바예지드 2세의 명에 따라 도시에서 대규모 복구와 재건 사업이 시작되었다.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["샤쿨루 반란의 시작", "3d9a4a90"], "d": ["TDV 이슬람 백과사전의 샤쿨루 바바 테켈리 항목에 따르면, 사파비의 선전에서 힘을 얻은 샤쿨루는 테케 지방에서 광범위한 투르크멘 무리를 자기 주위에 모아 종교적·사회적 성격의 대규모 반란을 일으켰다. 이 반란은 당대의 가장 심각한 국내 치안 위기 중 하나로서 국가의 중앙 권위를 크게 뒤흔들었다.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["바예지드 2세의 디메토카 가는 길에서의 죽음", "c46e98c9"], "d": ["퇴위한 뒤 태어난 도시 디메토카로 가기 위해 이스탄불을 떠난 전 파디샤는 하루에 5-6km밖에 가지 못하는 가마를 타고 가던 중 초를루 근처의 아발라르 마을에서 병세가 악화되어 918년 라비 알아왈월 25일(1512년 6월 10일) 사망했다. TDV 이슬람 백과사전은 사망 원인을 매우 의심스럽게 보며, 일부 국내외 사료에 따라 독살되었을 가능성을 거론한다. 31년의 술탄 통치를 마친 뒤, 오스만 가지의 혈통에서 나온 여덟 번째 파디샤는 이렇게 생을 마쳤다.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["야부즈 셀림의 명에 의한 아흐메드 왕자의 처형", "65abb2f2"], "d": ["TDV 이슬람 백과사전의 셀림 1세 항목에 따르면, 부친 바예지드 2세의 총아이자 왕위의 주된 경쟁자였던 아흐메드 왕자는 동생 셀림이 즉위한 뒤 벌인 싸움에서 예니셰히르 평야에서 대패했고, 전장에서 도주하다 붙잡혀 살해되었다. 이 사건으로 셀림은 형제와 조카들 사이의 왕위 다툼을 대부분 종식시켰다.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["이브라힘 파샤의 대재상 임명", "9c94c1e3"], "d": ["TDV 이슬람 백과사전의 마크불 이브라힘 파샤 항목에 따르면, 하스 오다 장관에서 루멜리아 베일레르베이로, 그리고 같은 날 대재상으로 승진한 이브라힘 파샤는 929년 샤반월 13일(1523년 6월 27일) 대재상이 되었다. 이는 궁정 근무에서 곧바로 대재상에 오른 전례 없는 임명으로, 이브라힘 파샤가 카누니에게 얼마나 각별히 가까웠는지를 보여 주었다.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["바르바로스 하이레딘 파샤의 대제독 임명", "a0ff6bab"], "d": ["TDV 이슬람 백과사전의 바르바로스 하이레딘 파샤 항목에 따르면, 알제에서의 성공으로 알려진 하이레딘 파샤는 1534년 4월 6일 이스탄불로 소환되어 대제독과 지중해 제도(제자이르-이 바흐르-이 세피드) 베일레르베이에 임명되었다. 이 임명은 오스만 함대의 재편과 지중해 해군력의 제도화의 시작으로 여겨진다.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["뤼스템 파샤가 처음으로 대재상이 되다", "ddfcc014"], "d": ["TDV 이슬람 백과사전의 뤼스템 파샤 항목에 따르면, 하딤 쉴레이만 파샤가 한 재상과의 불화로 해임된 뒤, 951년 라마단월 17일(1544년 12월 2일) 뤼스템 파샤가 대재상에 임명되었다. 미흐리마 술탄과의 결혼으로 궁정과 더욱 가까워진 뤼스템 파샤는 이 직책으로 카누니 시대의 가장 영향력 있는 정치가 중 한 사람이 되었다.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["에뷔수우드 에펜디가 셰이훌이슬람이 되다", "11ed04f8"], "d": ["TDV 이슬람 백과사전의 에뷔수우드 에펜디 항목에 따르면, 8년 동안 루멜리아 군법관(카자스케르)을 지낸 에뷔수우드 에펜디는 952년 샤반월(1545년 10월)에 셰이훌이슬람에 임명되어 이 직책을 28년 11개월 동안 맡았다. 카누니의 법령집을 샤리아 법과 조화시킨 파트와로 알려진 그는 당대의 법률 및 교육 제도의 형성에서 결정적인 역할을 했다.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["바르바로스 하이레딘 파샤의 사망", "3378a0bf"], "d": ["TDV 이슬람 백과사전의 바르바로스 하이레딘 파샤 항목에 따르면, 그는 짧은 병을 앓은 뒤 953년 주마다 알아왈월 6일(1546년 7월 5일) 이스탄불에서 사망했다. 베식타시에 자신이 세운 마드라사에 인접한 영묘에 안장된 바르바로스의 죽음은 오스만 함대가 확립한 지중해 우위의 한 시대가 막을 내리는 것으로 여겨졌다.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["쉴레이마니예 모스크와 복합 시설의 착공", "101ec36f"], "d": ["TDV 이슬람 백과사전의 쉴레이마니예 모스크와 복합 시설 항목에 따르면, 수석 건축가 미마르 시난의 지휘 아래 1550년에 초석이 놓인 이 복합 시설은 모스크 외에도 마드라사, 병원, 빈민 급식소, 도서관으로 이루어진 대규모 사회 복합 시설로 설계되었다. 이 공사는 카누니 통치의 힘과 이스탄불의 도시 건설을 상징하는 가장 큰 건축 사업 중 하나였다.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["이스탄불과 그 일대에서 새로운 흑사병 유행 시작", "547d6bf6"], "d": ["TDV 이슬람 백과사전의 타운(흑사병) 항목에 따르면, 이슬람 세계에 영향을 끼친 16세기 전염병 중 하나는 1552-1566년에 일어났으며, 특히 이스탄불, 아나톨리아, 루멜리아, 이집트, 북아프리카에 큰 영향을 미쳤다. 확장되는 교역로와 늘어나는 인구 이동은 제국이 가장 강성하던 시기에 전염병의 확산을 쉽게 한 요인 중 하나로 꼽힌다.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["카라 아흐메드 파샤의 대재상 임명", "a7d7748e"], "d": ["TDV 이슬람 백과사전의 카라 아흐메드 파샤 항목에 따르면, 제2재상으로 일하던 카라 아흐메드 파샤는 현직 대재상이 갑자기 해임된 뒤 960년 샤왈월 27일(1553년 10월 5일) 대재상으로 승진했다. 이 교체는 무스타파 왕자의 처형과 같은 시기로, 궁정 내 세력 균형이 빠르게 뒤바뀌던 시대를 보여 준다.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["대제독 피리 레이스의 처형", "3b2ad7a0"], "d": ["TDV 이슬람 백과사전의 피리 레이스 항목에 따르면, 호르무즈 포위를 풀 때 뇌물을 받고 무슬림의 재산을 약탈했으며 자기 군대를 전장에 버렸다는 혐의가 이집트에 전해지자, 유명한 항해가이자 지도 제작자인 그는 960년 말(1553년 말) 카이로에서 처형되었다. 재산을 몰수당한 피리 레이스의 죽음은 당시 바스라와 인도양 해양 정책을 둘러싼 파샤들 간 경쟁의 결과로 평가된다.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["카라 아흐메드 파샤 처형, 뤼스템 파샤가 다시 대재상이 되다", "9a85076a"], "d": ["TDV 이슬람 백과사전의 뤼스템 파샤와 카라 아흐메드 파샤 항목에 따르면, 962년 둘 카다월 13일(1555년 9월 29일) 디완 회의 중에 갑자기 처형된 카라 아흐메드 파샤의 후임으로, 휘렘 술탄과 미흐리마 술탄의 지원을 받은 뤼스템 파샤가 같은 날 두 번째로 대재상에 임명되었다. 사건의 배후는 사료에서 분명하게 밝혀지지 않았으며, 궁정 내 음모의 결과로 평가되어 왔다.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["휘렘 술탄의 사망", "1ae998b5"], "d": ["TDV 이슬람 백과사전의 휘렘 술탄 항목에 따르면, 카누니의 하세키 술탄으로서 여러 해 동안 궁정에서 큰 영향력을 지녔던 휘렘 술탄은 965년 주마다 알아키라월 26일(1558년 4월 15일) 이스탄불에서 사망하여 쉴레이마니예 모스크 복합 시설의 영묘에 안장되었다. 1534년 모후 하프사의 죽음 이후 하렘에 대한 권위를 굳혔던 휘렘 술탄의 죽음은 아들 바예지드와 셀림 사이의 왕위 다툼을 억제하던 균형 요인마저 사라지게 했다.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["소콜루 메흐메드 파샤의 대재상 승진", "896391a2"], "d": ["TDV 이슬람 백과사전의 소콜루 메흐메드 파샤 항목에 따르면, 972년 둘 카다월 30일(1565년 6월 29일) 세미즈 알리 파샤가 사망하자 대재상에 오른 소콜루 메흐메드 파샤는 카누니의 마지막 대재상이 되었으며, 이후 셀림 2세와 무라드 3세 시대에도 이 직책을 유지하여 오스만 역사에서 가장 오래 재임한 대재상 중 한 사람이 되었다.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["셀림 2세가 이스탄불에 도착해 즉위하다", "0289ef97"], "d": ["카누니 술탄 쉴레이만이 시게트바르에서 사망한 뒤, 소콜루 메흐메드 파샤는 질서를 흐트러뜨리지 않기 위해 그 소식을 여러 주 동안 비밀에 부쳤다. TDV 이슬람 백과사전에 따르면, 셀라니키는 셀림의 이스탄불 도착일을 974년 라비 알아왈월 15일(1566년 9월 30일)로 전하지만, 당대 역사가 대부분은 라비 알아왈월 9일(9월 24일)을 옳다고 본다. 카누니의 죽음은 1566년 10월 24-25일에야 베오그라드에서 공식 발표되었다.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["클르치 알리 파샤가 재건한 함대의 진수", "d0fc9f48"], "d": ["레판토의 참패(1571년 10월 7일) 이후 겨울 내내 조선소에서 배가 건조되었다. TDV 이슬람 백과사전에 따르면, 980년 사파르월 1일(1572년 6월 13일), 갤리선 250척과 약 300척의 의용 선장들의 체크티리(노 젓는 배)로 이루어진 새 함대가 무력 과시와 함께 진수되었다.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["소콜루 메흐메드 파샤의 암살", "6ffa8dec"], "d": ["세 파디샤 시대에 걸쳐 14년 동안 대재상을 지낸 소콜루 메흐메드 파샤는 987년 샤반월 20일(1579년 10월 12일), 자택에서 열린 오후 디완에서 청원서를 올리는 척하며 접근한 데르비시의 단검에 찔려 살해되었다. TDV 이슬람 백과사전에 따르면, 이 암살이 처형된 함자비 교단의 셰이흐 함자 발리의 복수와 관련이 있었을 가능성이 논의된다.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["잉글랜드와의 첫 통상 아흐드나메 — 잉글랜드인에게 카피툴레이션 부여", "59c8e3ee"], "d": ["1578년 10월 이스탄불에 파견된 잉글랜드 대표 윌리엄 하번은 소콜루 메흐메드 파샤와 호자 사데딘 에펜디의 지원을 받아 무라드 3세로부터 1580년자 아흐드나메(특허 협약)를 얻었다. 이 협약으로 잉글랜드 상인들은 앞서 프랑스인과 베네치아인에게 인정되었던 통상 특권(카피툴레이션)을 동일하게 누릴 권리를 얻었다. 엘리자베스 1세 여왕과 무라드 3세 사이에 서한이 교환되었고 두 나라 사이에 공식 관계도 수립되었다. 이 특권이 주어진 직후인 1581년 런던에서 레반트 회사가 설립되었으며, 잉글랜드인들은 1825년까지 이 지역의 교역을 이 회사를 통해 운영했다.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["이스탄불 천문대가 하트-으 휘마윤(칙서)으로 철거되다", "3bc0c78c"], "d": ["천문대가 나라에 불길함을 가져온다는 파트와와 궁정 내 반대의 영향으로, 987년 둘 히자월 4일(1580년 1월 22일)자 칙서에 의해 이스탄불 천문대는 안에 있던 모든 기구와 함께 철거되었다. TDV 이슬람 백과사전에 따르면, 이것이 타키위딘 알라시드가 세운 기관의 짧은 생애의 끝이었다.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["메흐메드 왕자의 아트메이다느 할례 축전 시작", "c2926d5d"], "d": ["무라드 3세의 아들 메흐메드 왕자는 990년 주마다 알아왈월 6일(1582년 5월 29일)에 시작되어 56-57일 동안 이어진 장대한 의식 속에서 할례를 받았다. TDV 이슬람 백과사전에 따르면, 아트메이다느에서 열린 축제는 당대의 가장 화려한 궁정 축전 중 하나였다.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["누르바누 발리데 술탄의 사망", "77d0a577"], "d": ["무라드 3세의 어머니 누르바누 술탄은 991년 둘 카다월 22일(1583년 12월 7일) 사망했다. TDV 이슬람 백과사전에 따르면, 그녀는 발리데 술탄으로서 베네치아 및 프랑스 궁정과 서신을 주고받았으며, 베네치아 원로원은 같은 해에 그녀의 공헌에 대한 보답으로 2000 베네치아 금화 상당의 선물을 보내기로 승인했다.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["악화된 악체 때문에 베일레르베이 사건이 터지다", "db2f2e61"], "d": ["국가가 악체의 은 함량을 낮추어 급료를 지급하자 시파히와 예니체리가 궁전을 포위하여, 역사에 베일레르베이 사건이라는 이름으로 남은 유혈 반란을 일으켰다. TDV 이슬람 백과사전의 압뒬카디르 셰이히 에펜디 항목에 따르면, 이 사건으로 셰이훌이슬람이 해임되었다.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["메흐메드 3세 즉위, 19명의 왕자를 교살하다", "2cd9a8c5"], "d": ["메흐메드 3세는 부친 무라드 3세가 사망하자 1003년 주마다 알아왈월 16일(1595년 1월 27일) 금요일 이스탄불에 도착해 즉위했다. TDV 이슬람 백과사전에 따르면, 같은 날 밤 성인 4명(무스타파, 바예지드, 오스만, 압둘라)을 포함한 19명의 왕자가 교살되었다. 이는 오스만 역사상 가장 많은 인원이 희생된 형제 살해였다.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["사피예 술탄이 발리데 술탄으로서 영향력을 얻다", "000bec21"], "d": ["무라드 3세의 부인이자 메흐메드 3세의 어머니인 사피예 술탄은 아들의 즉위와 함께 발리데 술탄의 지위로 궁정 정치에서 결정적인 위치에 올랐다. TDV 이슬람 백과사전에 따르면, 이 시기에 하렘에서 비롯된 영향력은 국정에 직접 개입하는 수준에 이르렀다.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["메흐메드 3세가 예니체리의 압력으로 직접 원정에 나서다", "d3c50656"], "d": ["대재상 다마드 이브라힘 파샤의 반대에도 불구하고, 메흐메드 3세는 예니체리의 압력으로 카누니 술탄 쉴레이만 이후 처음으로 직접 군대를 이끈 파디샤가 되어 1596년 6월 20일 이스탄불에서 원정에 나섰다. TDV 이슬람 백과사전에 따르면, 이는 옛 가자(성전) 전통의 부활을 뜻했다.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["1570년대에 시작된 흑사병이 계속 이스탄불에 영향을 미치다", "eb4ca37a"], "d": ["TDV 이슬람 백과사전의 타운(흑사병) 항목에 따르면, 1570년대에 시작된 전염병은 17세기 초까지 영향을 이어 갔으며, 이스탄불을 비롯해 아나톨리아, 발칸, 이집트, 북아프리카를 덮쳤다. 전염병 시기는 궁정과 도시의 생활을 자주 중단시키는 만성적 위협이었다.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["카라야즈즈 압뒬할림의 사망과 반란 운동의 약화", "876ca7a6"], "d": ["1601년 8월 12일 엘비스탄 근처 세페틀리에서 대패한 뒤 부상을 입고 물러난 카라야즈즈 압뒬할림은 1010년(1602년)에 사망했다. TDV 이슬람 백과사전에 따르면, 사망 소식은 1010년 라마단월(1602년 2-3월)에 이스탄불에 전해졌으며, 사료들은 그의 죽음이 부상 때문인지 자기 부하들의 소행인지가 논쟁 대상이라고 밝힌다.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["형제 살해 관행의 사실상 종식", "9046c607"], "d": ["아흐메드 1세는 즉위할 때 이전의 파디샤들과 달리 동생 무스타파 왕자를 죽이지 않고 목숨을 살려 주었다. 이 결정은 오스만 계승 제도에서 최연장자 계승 원칙(에크베르-에르셰드)이 사실상 채택되기 시작한 것으로 여겨진다. TDV 이슬람 백과사전의 '무스타파 1세' 항목은 무스타파가 이후 궁정에서 유폐 생활을 했다고 전한다. 이 조치는 수 세기 동안 이어진 즉위 때의 살해를 사실상 끝냈다.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["술탄아흐메드 모스크의 착공", "1683262f"], "d": ["아흐메드 1세의 명에 따라 아트메이다느에서 건축가 세데프캬르 메흐메드 아가가 짓게 될 모스크의 초석이 의식과 함께 놓였다. TDV 이슬람 백과사전의 '술탄 아흐메드 모스크와 복합 시설' 항목에 따르면, 이 건물은 정복의 승리 없이 국고에서 직접 지은 첫 번째 대규모 술탄 모스크라는 점에서 당대의 비판 대상이 되기도 했다. 복합 시설은 모스크와 함께 마드라사, 빈민 급식소, 영묘를 포함하도록 설계되었다.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["젊은 오스만이 예니체리에게 살해되다 (하일레-이 오스마니예)", "324f6582"], "d": ["메카 순례를 구실로 이스탄불을 떠나 예니체리 군단을 해체하려 한다는 소문에 봉기한 예니체리와 시파히는 오스만 2세를 폐위하고 예디쿨레 감옥에서 교살했다. TDV 이슬람 백과사전의 '오스만 2세' 항목에 따르면, 이 사건은 오스만 역사에서 파디샤가 노골적인 군사 반란으로 살해된 첫 사례였으며 왕조와 군대의 관계에 깊은 균열을 낳았다. 그의 마지막 몇 시간은 이러했다. 예니체리 아가 알리 아가의 저택으로 피신하려던 시도가 실패하자, 파디샤는 TDV의 표현대로 '비참하게, 머리에 아무것도 쓰지 않고 옷차림이 흐트러진 채' 말에 태워져 심한 모욕을 받으며 먼저 무스타파 1세가 있던 오르타 모스크로, 같은 날 오후에는 예디쿨레로 끌려갔다. 일부 역사가에 따르면, 그의 죽음을 증명하기 위해 귀와 코를 잘라 무스타파 1세의 어머니에게 보여 주었다. 이 사건 뒤 무스타파 1세가 두 번째로 즉위했다. '하일레-이 오스마니예'(오스만의 비극)라고 불리는 이 사건은 궁정과 군단 사이의 균형을 영구히 무너뜨렸고, 한 세기 동안 이어질 정통성 논쟁을 불러일으켰다.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["무스타파 1세의 두 번째 즉위", "34a0b29a"], "d": ["젊은 오스만이 예니체리에게 살해된 뒤, 왕조에 다른 성인 남성 구성원이 없었으므로 무스타파 1세가 두 번째로 즉위했다. TDV 이슬람 백과사전의 '무스타파 1세' 항목에 따르면, 이 두 번째 술탄 통치도 이전과 다름없이 국정을 실제로 수행하지 못한 채 지나갔고, 국가 운영은 재상들과 발리데 술탄의 손에 맡겨졌다. 14개월 동안 이어진 이 시기는 1623년 무라드 4세의 즉위로 끝났다.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["지발리 대화재", "3e42fb08"], "d": ["지발리에서 일어나 바람을 타고 빠르게 번진 화재는 이스탄불의 상당 부분을 잿더미로 만들었다. TDV 이슬람 백과사전의 '이스탄불' 항목에 따르면, 당대 사료들은 수천 가구가 불탔다고 전한다. 화재가 목조 가옥 구조와 흡연에 연관지어진 것은 무라드 4세가 곧이어 선포할 엄격한 담배 및 커피하우스 금지령의 직접적인 명분이 되었다. 이 재앙은 당시 이스탄불에서 되풀이되던 대화재 중 하나에 불과했다.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["무라드 4세의 담배 및 커피하우스 금지", "5dd71297"], "d": ["지발리 화재 이후 화재와 치안에 대한 우려로 무라드 4세는 흡연과 커피하우스를 금지했으며, 금지를 어기는 자에게는 사형을 포함한 중형을 가했다. TDV 이슬람 백과사전의 '무라드 4세' 항목에 따르면, 파디샤는 금지를 감독하기 위해 직접 변장하고 도시의 거리를 돌아다닐 정도로 엄격한 내부 기강 정책을 폈다. 이러한 강경책은 무라드 4세가 중앙 권위를 재확립하려던 노력의 일환으로 평가된다.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["이스탄불의 흑사병 유행", "f33f58c5"], "d": ["무라드 4세 시대에 이스탄불은 인구의 상당 부분에 영향을 준 심각한 흑사병 유행에 흔들렸고, 시내의 상업과 일상생활은 여러 달 동안 차질을 빚었다. TDV 이슬람 백과사전의 '이스탄불' 항목은 17세기에 되풀이된 전염병이 도시의 인구 균형에 심각한 영향을 미쳤다고 기록한다. 유행 기간에 궁정과 상류층은 한동안 도시 밖의 정원과 별장으로 옮겨 갔다.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["헤자르펜 아흐메드 첼레비의 날개 비행 (전승)", "df474c04"], "d": ["에블리야 첼레비가 전하는 이야기에 따르면, 헤자르펜 아흐메드 첼레비는 직접 만든 날개로 갈라타 탑에서 뛰어내려 위스퀴다르까지 활공하는 데 성공했다. 역사적 확실성은 논란이 있지만 이는 기술적 상상력의 상징이 되었다. 파디샤는 처음에는 헤자르펜에게 상을 내렸으나, 사건의 파장이 커지자 나중에 알제로 유배했다.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["진지 호자 휘세인 에펜디가 궁정에서 영향력을 얻다", "41d21572"], "d": ["파디샤 이브라힘의 정신적 고통을 치료하기 위해 궁정에 불려 온 주술 치료사 휘세인 에펜디는 곧 파디샤의 신임을 얻어 아나톨리아 군법관(카자스케르)까지 올랐다. TDV 이슬람 백과사전의 '휘세인 에펜디, 진지 호자' 항목에 따르면, 그는 이 영향력을 재산 축적과 당대 정치 사건에 대한 개입에 사용했다. 이브라힘이 죽은 뒤 모든 직책에서 해임되어 1648년에 처형되었다.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["케만케시 무스타파 파샤의 처형", "0ecc8030"], "d": ["무라드 4세 시대부터 대재상을 지내며 재정 개혁으로 국고에 상당한 흑자를 안겨 준 케만케시 무스타파 파샤는, 궁정 내 경쟁자들이 이브라힘에게 영향을 미치고 그를 예니체리 반란을 일으키려 했다고 고발하면서 교살형에 처해졌다. TDV 이슬람 백과사전의 '케만케시 무스타파 파샤' 항목에 따르면, 처형은 1053년 둘 카다월 21일 / 1644년 1월 31일에 이루어졌다. 케만케시 카라 무스타파 파샤는 호자파샤 시장에서 사형 집행인 카라 알리에게 교살되어 차르시카프에 있는 자신의 영묘에 안장되었다. 그의 죽음은 당시 대재상직의 불안정을 보여 주는 두드러진 사례로 언급되며, 짧았던 엄격한 개혁기를 끝냈다.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["디완에서의 크레타 원정 결정과 함대의 출항", "9076827e"], "d": ["베네치아령 크레타 섬에 대한 대규모 원정이 디완-으 휘마윤에서 결정되었고, 대제독이 지휘하는 오스만 함대는 이스탄불에서 크레타를 향해 출항했다. TDV 이슬람 백과사전의 '크레타' 항목에 따르면, 이 결정은 약 25년 동안 이어질 긴 포위와 전쟁 시기의 정치적 출발점이 되었다. 원정 개시는 이브라힘 시대의 가장 큰 대외 정책 시도로서 국가 고위층 사이에 폭넓은 논쟁을 일으켰다.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["메흐메드 4세의 7세 즉위", "a197a3bc"], "d": ["이브라힘의 폐위 직후, 겨우 일곱 살이던 아들 메흐메드가 즉위하여 메흐메드 4세라는 칭호의 파디샤가 되었다. TDV 이슬람 백과사전의 '메흐메드 4세' 항목에 따르면, 이처럼 어린 나이의 즉위는 할머니 쾨셈 술탄과 어머니 투르한 술탄 사이의 궁정 내 영향력 다툼을 격화시켰다. 이 권력 투쟁은 1651년 쾨셈 술탄의 살해로 끝나게 된다.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["타르훈주 아흐메드 파샤의 균형 예산 개혁", "376fc7f2"], "d": ["대재상 타르훈주 아흐메드 파샤는 오랜 전쟁이 초래한 재정 위기를 극복하기 위해 궁정 지출까지 포함한 강력한 긴축 계획을 시행하여, 오스만 역사에서 알려진 최초의 균형 예산(타르훈주 건의서)을 작성했다. TDV 이슬람 백과사전의 '타르훈주 아흐메드 파샤' 항목에 따르면, 이 개혁은 국고에 상당한 흑자를 가져다주었으나 궁정 주변과 고위 관료들 사이에 광범위한 불만을 낳았다. 이 불만은 1년 뒤 그의 처형으로 이어지게 된다.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["플라타너스 사건 (바크바키예 사건)", "4c6ed90f"], "d": ["TDV 이슬람 백과사전의 플라타너스 사건 항목에 따르면, 크레타 원정에서 급료를 받지 못하고 돌아온 예니체리와 시파히는 이스탄불에서 봉기해 부정을 저질렀다고 비난하던 국가 관리들의 처형을 요구했다. 대재상 주르나젠 무스타파 파샤의 재산 몰수 및 유배 제안은 받아들여지지 않았다. 먼저 관리 3명이, 이어 30명에 가까운 국가 관리가 처형되었고 시신은 술탄아흐메드 광장의 플라타너스 나무에 매달렸다. 이 때문에 사건은 플라타너스(츠나르) 사건이라는 이름으로 불렸다.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["쾨프륄뤼 메흐메드 파샤가 조건부 수락으로 대재상에 임명되다", "3a6b7f8f"], "d": ["TDV 이슬람 백과사전의 쾨프륄뤼 메흐메드 파샤 항목에 따르면, 여든에 가까운 쾨프륄뤼 메흐메드 파샤는 임명에 간섭하지 말 것, 자신에 대한 비방을 믿지 말 것 등 발리데 투르한 술탄과 메흐메드 4세에게 제시한 까다로운 조건이 받아들여진 뒤에야 국새를 받았다. 그는 1066년 둘 카다월 26일 보이누에리 메흐메드 파샤의 후임으로 직무를 시작했고 국가 기강을 강력하게 다시 세우기 시작했다.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["쾨프륄뤼 메흐메드 파샤의 카드자데파 운동 진압", "5ec3ce84"], "d": ["TDV 이슬람 백과사전의 카드자데파 항목에 따르면, 쾨프륄뤼 메흐메드 파샤는 직무를 시작하자마자 카드자데 메흐메드 에펜디 추종자들과 수피 교단 사람들 사이의 종교적 갈등을 다루었다. 그는 울라마의 자문을 거친 뒤 운동의 지도자 위스튀바니 메흐메드 에펜디, 튀르크 아흐메드, 디바네 무스타파에 대해 사형 칙령을 내렸으나 이 형벌은 유배로 바뀌어 세 사람은 키프로스로 보내졌다. 이로써 운동의 두 번째 단계가 끝났다.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["이스탄불 대화재 — 아가카프스의 소실", "b9253b66"], "d": ["TDV 이슬람 백과사전의 아가카프스 항목에 따르면, 메흐메드 4세 시대인 1660년 7월에 일어난 대화재로 예니체리 아가의 공식 본부인 아가카프스가 완전히 불탔고 이후 다시 지어졌다. 이 화재는 당시 이스탄불을 거듭 덮친 대규모 도시 화재 중 하나였다.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["쾨프륄뤼자데 파즐 아흐메드 파샤의 대재상 임명", "c1999b5c"], "d": ["TDV 이슬람 백과사전의 쾨프륄뤼자데 파즐 아흐메드 파샤 항목에 따르면, 부친 쾨프륄뤼 메흐메드 파샤가 사망하자 그는 1072년 라비 알아왈월 8일(1661년 11월 1일) 대재상에 임명되었다. 부친과 달리 온화하고 신앙심이 깊으며 학자와 예술가의 후원자로 알려진 파즐 아흐메드 파샤는 15년이 넘는 재임 기간 동안 이스탄불과 정복지에 도서관과 자선 기관을 세우게 했다.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["바니 메흐메드 에펜디가 예니 모스크 설교사 겸 파디샤의 스승으로 임명되다", "7ea6aaae"], "d": ["TDV 이슬람 백과사전의 바니 메흐메드 에펜디 항목에 따르면, 쾨프륄뤼자데 파즐 아흐메드 파샤가 대재상이 되면서 이스탄불로 초빙되어 메흐메드 4세에게 소개된 바니 메흐메드 에펜디는 곧 파디샤의 각별한 관심을 얻었다. 1665년 예니 모스크 설교사 겸 파디샤의 스승에 임명된 그는 궁정에서 가장 영향력 있는 종교인 중 한 사람이 되었다.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["메르지폰루 카라 무스타파 파샤의 대재상 임명", "3d1e836c"], "d": ["TDV 이슬람 백과사전의 메르지폰루 카라 무스타파 파샤 항목에 따르면, 파즐 아흐메드 파샤가 사망하자 그는 1087년 샤반월 28일(1676년 11월 5일) 대재상에 임명되었다. 쾨프륄뤼 가문의 사위이자 그 가문에서 길러진 인물로 국정 경험이 풍부했던 메르지폰루는 메흐메드 4세의 가장 강력하고 영향력 있는 대재상 중 한 사람이 되었다.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["바니 메흐메드 에펜디의 유배지 사망", "cda714aa"], "d": ["TDV 이슬람 백과사전의 바니 메흐메드 에펜디 항목에 따르면, 빈 원정을 파디샤에게 받아들이게 한 주요 인물 중 하나로 꼽히던 바니 메흐메드 에펜디는 원정이 참패로 끝난 뒤 여론의 압력으로 총애를 잃고 부르사의 케스텔 읍으로 유배되었다. 1096년 둘 카다월 14일(1685년 10월 12일) 이곳에서 사망했으며 자신이 지은 모스크의 입구에 안장되었다.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["쾨프륄뤼자데 파즐 무스타파 파샤의 대재상 임명과 재정 개혁", "b048570e"], "d": ["TDV 이슬람 백과사전의 쾨프륄뤼자데 파즐 무스타파 파샤 항목에 따르면, 1101년 무하람월 11일(1689년 10월 25일) 대재상에 임명된 파즐 무스타파 파샤는 지즈야 징수 방식을 샤리아 원칙에 따라 재편했고, 망기르(동전) 인플레이션에 맞섰으며, 궁정 기관의 재원을 돌려 국고를 강화했다. 또한 지방 행정에 믿을 만한 관리를 보강하고 중앙의 디완과 비슷한 지방 협의회를 설치하게 했다.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["말리카네 제도의 시행", "316b8426"], "d": ["TDV 이슬람 백과사전의 말리카네 항목에 따르면, 17세기 마지막 4분기에 전쟁 비용의 증가와 영토 상실에 따른 세수 감소가 국고를 심각한 재정 위기에 빠뜨렸다. 1106년(1695년)에 시행된 말리카네 제도에서는 징세 청부업자에게 종신 고정 징세권을 인정하여, 단기적 착취 대신 생산을 보호하려는 유인을 마련했다.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["무스타파 2세의 즉위", "b53656c7"], "d": ["TDV 이슬람 백과사전의 무스타파 2세 항목에 따르면, 31세에 즉위한 무스타파 2세는 대재상과 셰이훌이슬람의 승인을 기다리지 않고 자신의 술탄 즉위를 선포했으며, 검을 차는 의식은 며칠 뒤 에스키 모스크에서 거행되었다. 빈 패전 이후 여러 전선의 전쟁이 이어지던 시기에 즉위한 이 파디샤는 오스만 역사에서 직접 원정에 나선 마지막 술탄이 되었다.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["페이줄라 에펜디의 두 번째 셰이훌이슬람 임명", "1cf14cff"], "d": ["TDV 이슬람 백과사전의 사이이드 페이줄라 에펜디 항목에 따르면, 그는 무스타파 2세의 즉위 뒤인 1106년 샤왈월 11일(1695년 5월 25일) 두 번째로 셰이훌이슬람에 임명되었다. 8년이 넘게 이어진 이 재임 기간 동안 파디샤에 대한 그의 영향력은 점점 커졌다.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["페이줄라 에펜디의 아들들 고위직 임용과 누적된 반발", "a6398280"], "d": ["TDV 이슬람 백과사전의 사이이드 페이줄라 에펜디 항목에 따르면, 셰이훌이슬람은 무스타파 2세로부터 자기 아들 페툴라 에펜디가 자신의 뒤를 이어 셰이훌이슬람이 된다는 전례 없는 칙령을 받아냈고, 친척들을 어린 나이에 고위직에 앉혔다. 이러한 행태는 울라마 계층, 군인, 이스탄불 주민 사이에 광범위한 불만을 낳았고, 수도가 에디르네로 옮겨진다는 소문과 겹치면서 1703년 에디르네 사건의 토대를 마련했다.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["에디르네 사건의 시작", "5a106458"], "d": ["TDV의 '에디르네 사건' 항목에 따르면, 급료를 받지 못한 병사들의 봉기로 시작된 움직임은 곧 예니체리, 마드라사 학생, 장인, 주민이 참여하는 광범위한 반란으로 바뀌었다. 반란의 주된 목표는 국정에 지나치게 간섭한다고 지목된 셰이훌이슬람 페이줄라 에펜디였다. 약 6만 명의 군중이 이스탄불에서 에디르네로 행진했다.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["네브셰히를리 다마드 이브라힘 파샤의 대재상 재임", "8d627a6f"], "d": ["TDV의 '네브셰히를리 다마드 이브라힘 파샤' 항목에 따르면, 그는 오스트리아와의 평화 협상이 진행 중이던 1130년 주마다 알아키라월 8일(1718년 5월 9일) 대재상에 임명되었고, 임명되자마자 전쟁을 끝낼 협상에 착수했으며, 두 달 뒤 파사로비츠 조약이 체결되었다(1718년 7월 21일). TDV의 표현에 따르면 그는 '사회·재정 문제에 힘쓰고자 했으며, 오랜 세월 패배로 끝난 전쟁들을 잊게 해 줄 평화의 시대를 갈망했다'. 그는 재정 개혁을 실시해 군인의 급료를 낮추고 국고에 상당한 흑자를 만들었다. 12년 동안 이어질 그의 대재상 재임은 그의 이름과 결부된 시대(튤립 시대)의 정치적 틀을 이루었다.", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["소방대(툴룸바즈 오자으) 창설", "f58b0d97"], "d": ["TDV의 '툴룸바즈' 항목에 따르면, 1715년 모레아 원정에서 돌아온 게르체크 다부드가 이스탄불 화재에서 펌프로 성과를 내자, 대재상 네브셰히를리 다마드 이브라힘 파샤는 그에게 공식 소방대 창설을 맡겼다. 아제미 오을란(예비 병사) 병영에서 장교 6명과 병사 50명으로 창설된 소방대는 1724년 150명, 1755년 461명으로 늘었다. 다부드는 1733년 사망할 때까지 소방대를 이끌었다.", "3b860f0f"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["사다바드 궁의 건설", "aec9c65e"], "d": ["TDV의 '사다바드' 항목에 따르면, 카으타네 강가에 프랑스 궁정 건축에서 영감을 받은 궁과 운하, 분수, 정자로 이루어진 광대한 유흥·휴양 단지가 건설되었다. 당대 가장 인기 있는 유흥지가 된 사다바드는 시인 네딤의 시에서 불멸이 되었다. 이 단지는 1730년 파트로나 할릴 반란 때 대부분 파괴되었다.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["러시아군의 데르벤트 점령: 표트르 1세의 카스피해 원정", "c2b269f9"], "d": ["사파비 왕조가 아프간의 침입으로 내부 혼란에 빠져 있을 때, 러시아 차르 표트르 1세는 카스피해 연안의 이란 영토를 차지하기 위해 원정에 나섰으며, 해안 도시 데르벤트는 이렇다 할 저항 없이 러시아군에 항복했다. TDV 이슬람 백과사전의 데르벤트 항목에 따르면, 이 점령은 13년 동안 이어질 일시적인 러시아 지배의 시작이었다. 오스만 국가도 같은 혼란을 틈타 캅카스 서부로 향했다. 군대는 아스트라한에서 해로로 아그라한 만에 상륙한 뒤, 거기서 해안을 따라 타르쿠를 거쳐 육로로 진군했다. 타르쿠의 샴할은 표트르를 환대하고 러시아의 신속(臣屬)을 받아들였다.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["타르쿠 샴할국의 폐지: 러시아의 직접 통치", "b0f029c6"], "d": ["1722년 표트르를 환대하고 러시아의 신속을 받아들인 타르쿠의 샴할 아딜 기레이는 1725년 반란을 일으켰다. 예롭킨은 1725년 가을 타르쿠를 파괴했고, 샴할은 1726년 5월 중순에 체포되어 유배되었으며 샴할국은 폐지되었다. 타르쿠와 그 주변은 1735년 간자 조약까지 러시아의 직접 통치를 받았다.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["이브라힘 뮈테페리카에게 인쇄소 설립 허가", "0659dd0a"], "d": ["TDV의 '이브라힘 뮈테페리카' 항목에 따르면, 아흐메드 3세의 칙령과 셰이훌이슬람 예니셰히르리 압둘라 에펜디의 파트와로 최초의 튀르크어 인쇄소 설립이 허가되었다. 인쇄소는 이스탄불의 야부즈셀림 지구에서 가동을 시작했다. 뮈테페리카는 1747년 사망할 때까지 23권에 달하는 17종의 저작을 인쇄했다.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["최초의 인쇄본 『반쿨루 사전』의 완성", "684700e8"], "d": ["TDV의 '이브라힘 뮈테페리카' 항목에 따르면, 인쇄소의 첫 작품인 『시하흐 알자우하리』의 튀르크어 번역본(『반쿨루 사전』)이 1729년 초에 완성되었다. 이는 오스만 영토에서 아랍 문자로 인쇄된 최초의 책이며 튀르크 인쇄 역사의 시작으로 여겨진다.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["네브셰히를리 다마드 이브라힘 파샤의 처형", "50c64341"], "d": ["TDV의 '네브셰히를리 다마드 이브라힘 파샤' 항목에 따르면, 파트로나 할릴 반란 중에 궁전에서 살해된 대재상의 시신은 이스탄불 거리에서 끌려다니다가 술탄아흐메드 광장의 아흐메드 3세 분수 근처에 버려졌다. 이로써 12년에 걸친 그의 대재상 재임과 튤립 시대는 유혈로 끝났다.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["아흐메드 3세의 퇴위와 마흐무드 1세의 즉위", "a43f5d40"], "d": ["TDV의 '마흐무드 1세' 항목에 따르면, 반란군의 압력에 직면한 아흐메드 3세는 자신과 자녀의 안전을 보장받고 퇴위했으며 조카 마흐무드 왕자를 직접 왕위에 앉혔다. '국정을 직접 장악하고 누구도 믿지 말라'는 숙부의 충고를 들으며 왕좌에 오른 마흐무드 1세는 가장 먼저 자신을 왕위에 올린 반란 집단의 영향력을 꺾는 일에 착수했다.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["훔바라즈 아흐메드 파샤의 포병 군단 개혁", "ea3a7c64"], "d": ["TDV의 '훔바라즈' 항목에 따르면, 이슬람으로 개종한 프랑스 출신 장교 아흐메드 파샤는 대재상 헤킴오을루 알리 파샤 시대에 급료를 받는 훔바라즈(박격포병) 조직을 유럽식으로 개혁하는 일에 착수했다. 그는 대재상에게 직속되는, 급료병 300명과 티마르 보유병 301명으로 이루어진 601명의 새 조직을 만들었다. 당대의 기술로 박격포 100문과 포탄 5만 발을 생산하게 했다.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["헨데세하네(공학 학교의 첫 사례) 설립", "a77ed1f3"], "d": ["TDV의 '마흐무드 1세' 항목에 따르면, 훔바라즈 아흐메드 파샤는 위스퀴다르에 훔바라하네라고도 불린 헨데세하네를 세우고, 궁정 시종과 보스탄즈(정원 경비대) 중에서 뽑은 학생들에게 수학과 기하학에 기초한 군사 교육을 했다. 이 기관은 훗날 발전하게 되는 공학 학교의 첫 사례로 인정된다.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["간자 조약: 데르벤트와 바쿠의 이란 반환", "ff19d531"], "d": ["오스만의 위협에 맞서 이란과의 동맹을 모색하던 러시아는 13년 동안 장악해 온 카스피해 연안 도시들을 간자 조약으로 나디르 칸(아직 샤의 칭호를 받기 전)이 지휘하는 이란에 반환했다. TDV 이슬람 백과사전의 데르벤트 항목에 따르면, 이 철수는 러시아가 남쪽에서 두 전선(오스만과 이란)에서 동시에 싸우고 싶지 않았던 결과였으며, 몇 년 뒤 나디르가 왕위에 오르는 길을 연 군사적 위신을 굳혀 주었다. 러시아의 통치를 받던 타르키(타르쿠)도 이 철수로 이란 쪽으로 돌아갔다(지도에서는 간자 조약의 날짜를 사용한다). 러시아의 통치를 받던 살랸과 샤바란도 이 철수로 이란 쪽으로 돌아간다(각 정착지의 고유한 날짜는 사료에 없어 지도에서는 간자 조약의 날짜를 사용한다 — 명시된 근사치).", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["나디르 샤의 무간 평원 즉위: 사파비 왕조의 사실상 종말", "4f640979"], "d": ["TDV 이슬람 백과사전의 나디르 샤 항목에 따르면, 무간 평원에 모인 약 2만 명의 쿠릴타이는 그가 이란의 수장이 되기를 거듭 요청했다. 나디르는 사파비와 오스만 사이의 전쟁의 원인이 되었던 극단적 시아파 사상을 버리고 온건한 자파리 학파를 받아들인다는 조건으로 이 제안을 수락하여, 1148년 샤왈월 24일(1736년 3월 8일) 나디르 샤라는 칭호로 즉위했다. 이는 2세기에 걸친 사파비 왕조가 사실상 끝나고 아프샤르 왕조가 세워졌음을 뜻했다.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["이스탄불의 흑사병 유행 시작", "9fa82b56"], "d": ["TDV의 '타운(흑사병)' 항목에 따르면, 1739-1743년 이슬람 세계에서 맹위를 떨친 흑사병은 이 시기에 이스탄불도 덮쳤다. 해당 항목은 18세기의 전염병이 이전 세기들보다 비교적 가볍게 지나갔다고 밝힌다. 유행 시기로는 1713년, 1719년, 1728-1729년, 1759-1765년도 꼽힌다.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["호자파샤 화재", "321c7d0d"], "d": ["TDV의 '파트마 술탄 모스크' 항목에 따르면, 밤에 일어난 호자파샤 화재는 바브알리와 그 주변을 폐허로 만들었으며, 이 지역의 파트마 술탄 모스크도 이 화재로 피해를 입은 것으로 추정된다. 오스만 3세 시대에 이스탄불을 덮친 대화재 중 하나인 이 재앙은 도시의 상업·행정 중심지에 막심한 피해를 입혔다.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["코자 라그프 메흐메드 파샤의 대재상 재임", "a1846910"], "d": ["시인이자 외교관으로 알려진 라그프 파샤는 오스만 3세에 의해 대재상에 임명되었다(1757년 10월 오스만 3세가 사망한 뒤에도 직책을 유지했으며 무스타파 3세로부터 새 국새를 받았다). 그는 7년 전쟁이 이어지는 동안 오스만 국가를 유럽의 분쟁 밖에 두는 균형 잡힌 대외 정책을 폈다. 6년 동안 이어질 재임 기간에 도서관 설립 같은 문화 활동도 중시했다.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["라그프 파샤의 사망", "6bc19323"], "d": ["라그프 파샤는 6년의 대재상 재임 끝에 사망했다. 그의 죽음으로 무스타파 3세 시대의 가장 오래 지속되고 균형 잡힌 대재상 재임이 끝났다.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["이스탄불 대지진과 파티흐 모스크의 붕괴", "2475b4dc"], "d": ["TDV의 '파티흐 모스크와 복합 시설' 항목에 따르면, 1766년의 대지진으로 모스크의 중앙 돔이 완전히 무너졌고 벽은 수리할 수 없을 정도로 손상되었다. 무스타파 3세의 명으로 건축가 사림 이브라힘 에펜디와 이제트 메흐메드 베이의 지휘 아래 1767년에 시작된 재건은 옛 설계와 다른 새 설계로 1771년에 완공되었다.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["드 토트 남작이 주도한 단명한 포술 학교의 시도", "4192260c"], "d": ["TDV의 '뮈헨디스하네-이 바흐리-이 휘마윤' 항목에 따르면, 1768년 오스만-러시아 전쟁에서의 실패는 기술 군사 교육의 필요성을 드러냈다. 프랑스 장교 드 토트 남작의 기여로 세워진 단명한 포술 학교는 1772년 10월에 문을 열었으나 효과를 거두지 못했다. 이 시도는 1775년에 설립될 제국 해군 공학교(뮈헨디스하네-이 바흐리-이 휘마윤)의 선구로 여겨진다.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["셀림 3세의 즉위", "00d046d9"], "d": ["압뒬하미드 1세가 사망하자 조카 셀림 3세가 왕위에 올랐다. TDV 이슬람 백과사전의 셀림 3세 항목에 따르면, 왕자 시절부터 유럽식 군대 개혁에 관심이 있었던 새 파디샤는 즉위한 지 얼마 되지 않아 근본적인 쇄신 계획을 마련하게 하기 시작했다. 이 계획은 몇 년 안에 니자므 제디드(새 질서)라는 이름으로 불리게 된다.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["니자므 제디드 개혁 계획의 준비 시작", "eff78a68"], "d": ["셀림 3세는 국가 고위 관리들과 외국 전문가들에게 요청한 건의서를 바탕으로 포괄적인 쇄신 계획을 마련하게 했다. TDV 이슬람 백과사전의 니자므 제디드 항목에 따르면, 이 계획은 새 군대를 창설하는 데 그치지 않고 재정, 지방 행정, 외교까지 아우르는 광범위한 개혁 운동으로 발전했다. 이 계획은 이후 15년 동안 지지자와 반대자를 모두 만나게 된다.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["유럽 수도들에 상주 대사관 설치", "2e9dc8a1"], "d": ["셀림 3세는 오스만 국가 역사상 처음으로 유럽의 주요 중심지에 상주할 상임 대사들을 파견했다. TDV 이슬람 백과사전의 대사 항목에 따르면, 이 조치는 그때까지 임시적이고 일회성인 사절단으로만 수행되던 오스만 외교에 상설 조직을 갖추게 했다. 새 대사관의 주요 임무는 유럽의 정치·군사 동향을 정기적으로 이스탄불에 보고하는 것이었다.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["이라드-으 제디드 국고의 설립", "ae5c8ce2"], "d": ["니자므 제디드 군대와 개혁 계획의 비용을 충당하기 위해 별도의 국고가 설립되었다. TDV 이슬람 백과사전의 에샴 항목에 따르면, 새 국고의 수입에는 일부 무카타아(징세 구역)를 국가가 직접 운영하는 것과 에샴(수익 지분) 판매를 통제 아래 두는 것이 포함되었다. 이 조치는 전통 재정 제도 밖에서 새 재원을 만들려는 시도였다.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["카바크츠 무스타파 반란의 시작", "b98eee17"], "d": ["니자므 제디드에 대해 쌓여 온 불만은 야마크(보조병)들이 카바크츠 무스타파의 지도 아래 봉기하면서 터져 나왔다. TDV 이슬람 백과사전의 카바크츠 반란 항목에 따르면, 반란군은 곧 이스탄불의 통제권을 장악하고 니자므 제디드를 지지하는 국가 관리들의 목을 요구했다. 봉기는 며칠 만에 셀림 3세의 폐위로 끝났다.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["셀림 3세의 폐위", "ff2c30ec"], "d": ["카바크츠 무스타파 반란의 압력 아래 셰이훌이슬람에게서 받아낸 파트와로 셀림 3세가 폐위되었다. TDV 이슬람 백과사전의 셀림 3세 항목에 따르면, 이 결정은 18년간의 개혁 시대가 사실상 끝난 순간이었으며, 니자므 제디드 군대도 곧 해체되었다. 셀림은 톱카프 궁전에 연금되기 시작했다.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["무스타파 4세의 즉위", "8f1ac86c"], "d": ["셀림 3세가 폐위된 직후 조카 무스타파 4세가 파디샤로 선포되었다. TDV 이슬람 백과사전의 무스타파 4세 항목에 따르면, 새 파디샤는 반란을 지지한 니자므 제디드 반대 세력의 영향 아래 통치를 시작했다. 이 짧은 시기는 중앙 권위가 크게 약화된 불안정한 국면이었다.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["알렘다르 무스타파 파샤가 군대를 이끌고 이스탄불에 입성", "0cad3dea"], "d": ["루세의 아얀(지방 유력자) 알렘다르 무스타파 파샤는 셀림 3세를 다시 왕위에 앉힐 목적으로 군대를 이끌고 이스탄불 앞에 도착했다. TDV 이슬람 백과사전의 알렘다르 무스타파 파샤 항목에 따르면, 그의 도시 입성은 무스타파 4세가 직접 맞이했으나, 며칠 만에 궁정 내의 세력 균형은 완전히 바뀌게 된다. 이 입성은 셀림의 죽음과 새로운 즉위로 이어지는 일련의 사건의 시작이었다.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["셀림 3세의 살해", "e452f5f6"], "d": ["알렘다르 무스타파 파샤가 바브알리를 장악한 날, 무스타파 4세의 명으로 셀림 3세가 궁전에서 살해되었다. TDV 이슬람 백과사전의 셀림 3세 항목에 따르면, 이는 폐위된 파디샤를 다시 왕위에 올리려는 시도를 막기 위해 내려진 결정이었다. 셀림의 죽음은 같은 날 마흐무드의 즉위로 이어졌다.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["마흐무드 2세의 즉위", "661c1974"], "d": ["셀림 3세가 살해된 뒤 왕조에 남은 유일한 남성인 마흐무드가 알렘다르 무스타파 파샤의 지원을 받아 즉위했다. TDV 이슬람 백과사전의 마흐무드 2세 항목에 따르면, 새 파디샤는 통치 첫 몇 달을 자신을 왕위에 올린 알렘다르의 후견 아래에서, 아얀과 중앙 사이의 균형을 다시 세우려는 노력으로 보냈다. 이 시기는 이후 20년에 걸친 근본적 개혁 과정의 출발점이 되었다.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["세크바느 제디드 군대의 창설", "6f9eb5e4"], "d": ["알렘다르 무스타파 파샤는 해체된 니자므 제디드를 대신해 유럽식 장비를 갖춘 새 군대를 창설하게 했다. TDV 이슬람 백과사전의 세크바느 제디드 항목에 따르면, 3개 연대로 이루어진 이 부대는 예니체리의 눈에 직접적인 위협으로 비쳤고, 창설된 지 불과 몇 달 만에 예니체리의 반란에서 제거되었다.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["브러일라 함락 — 다뉴브 방어선의 첫 번째 큰 돌파구", "ee519321"], "d": ["1806년에 시작된 러시아와의 전쟁에서 다뉴브강 북안의 브러일라 요새는 카멘스키 백작이 지휘하는 러시아군에게 포위되어 포격을 받았다. 요새 안에는 보병 4100명, 기병 1100명, 대포 260문이 있었다. 요새는 식량 부족 때문에 에센 장군에게 항복했다. 이로써 다뉴브 방어선의 북쪽 끝이 열렸다.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["루세의 항복 — 다뉴브강 남안도 상실되다", "084062e8"], "d": ["루세는 카멘스키 백작이 지휘하는 러시아군의 길고 피비린내 나는 포위에 저항했으며, 수비대와 민간인이 안전하게 도시를 떠나는 조건으로 항복했다. 다뉴브강 남안에서 가장 강력한 요새 도시의 함락은 전쟁의 흐름을 러시아에 유리하게 바꾸었다.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["에슈킨지 군단의 창설", "67c56759"], "d": ["마흐무드 2세는 예니체리 군단 안에서 선발한 병사들로 유럽식 훈련을 받을 새 부대를 창설하게 했다. TDV 이슬람 백과사전의 에슈킨지 군단 항목에 따르면, 이 부대는 1826년 6월 12일 훈련을 시작했으나 예니체리는 이를 자기 군단의 종말로 보았다. 사흘 뒤 터진 반란은 에슈킨지 군단의 짧은 생애에도 마침표를 찍었다.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["아사키리 만수레이 무함마디예(무함마드의 승리 군대) 창설", "14b84a7e"], "d": ["예니체리 군단이 폐지된 직후, 마흐무드 2세는 이를 대신해 유럽식으로 훈련받은 새 정규군을 창설하게 했다. TDV 이슬람 백과사전의 아사키리 만수레이 무함마디예 항목에 따르면, 이 군대는 계급 체계, 훈련 과정, 급료 제도에서 이전의 시도들과 달리 영속적인 제도가 되었다. 이 군대는 이후 탄지마트 시대의 니자미예 군대로 변하게 된다.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["벡타시 교단의 폐쇄", "f7d9a367"], "d": ["예니체리 군단의 폐지와 동시에, 군단과 종교적 유대가 있는 것으로 알려진 벡타시 교단도 금지되었다. TDV 이슬람 백과사전의 벡타시 교단 항목에 따르면, 일부 작은 수도장의 셰이흐는 처형되었고 하즈 벡타시 수도원의 셰이흐는 아마시아로 유배되었으며, 수도장들은 낙슈반디 교단의 관리로 넘어갔다. 교단은 이 혹독한 타격에도 불구하고 비밀리에 조직을 유지했다.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["부채 사건 — 점령의 구실", "e949001e"], "d": ["알제에 대한 프랑스의 오래된 곡물 대금이 지불되지 않아 긴장이 높아진 면담에서, 데이 후세인이 프랑스 영사 드발을 손에 든 부채로 쳤다. 채권 분쟁에서 비롯된 이 사건은 3년 뒤 시작될 점령의 공식 구실이 되었다.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["프랑스의 알제 해안 봉쇄 — 3년에 걸친 포위", "d0ba97a5"], "d": ["부채 사건 이후 프랑스는 알제 해안을 봉쇄했다. 봉쇄는 3년 동안 이어졌고, 오자크의 해상 교역과 수입원이 고갈되었으며, 점령이 시작되기도 전에 저항 능력이 잠식되었다.", "79d27be2"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["브러일라의 두 번째 함락 — 요새 앞에 선 차르 니콜라이", "eb6a8741"], "d": ["1812년 오스만에 반환되고 1817-1818년에 다시 요새화된 브러일라는 수비병 4000명과 대포 278문을 갖춘 상태에서 4월에 포위되었다. 수비대장 에부베키르 파샤는 새 방어선을 구축했고, 차르 니콜라이 1세는 5월 말 직접 요새 앞에 왔다. 도시는 러시아에 점령되었으나, 아드리아노폴리스(에디르네) 조약으로 반환되어 왈라키아 공국에 넘겨지게 된다.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["페즈를 공식 모자로 선포", "f55be4eb"], "d": ["마흐무드 2세는 관리와 군인의 복장을 근본적으로 바꾸어 터번 대신 페즈를 공식 머리쓰개로 선포했다. TDV 이슬람 백과사전의 페즈 항목에 따르면, 이 결정은 칙서(하트-으 휘마윤)로 공포되었고 아사키리 만수레이 무함마디예의 서구식 개혁과 함께 시행되었다. 이 변화는 전통적인 복장 위계의 폐지를 뜻하기도 했다.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["아할치헤의 러시아 할양 — 츨드르 주의 중심지 상실", "e2e00b2a"], "d": ["1578년 츨드르 전투 이래 오스만의 통치를 받으며 츨드르 주의 중심지였던 아할치헤는 1828-1829년 전쟁 끝에 체결된 아드리아노폴리스(에디르네) 조약으로 러시아에 할양되었다. 도시의 상실은 주민 사이에 깊은 슬픔을 자아냈으며 많은 애가의 소재가 되었다. 이 사건으로 아할칼라키, 자잘로, 츠칼트빌라(아할치헤-아할칼라키 지역)가 러시아에 넘어갔다.", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["시디 페루슈 상륙 — 알제 땅에 선 프랑스군", "33327553"], "d": ["3년간의 봉쇄 뒤, 부르몽 백작이 지휘하는 프랑스 상륙군이 알제 서쪽의 시디 페루슈 만에 병력을 상륙시켰다. 도시를 향해 진격한 병력은 3주 만에 방어선을 무너뜨렸고, 7월 4일 도시를 내려다보는 황제 요새가 함락되었으며, 이튿날 데이 후세인이 항복했다.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["데이 후세인의 추방 — 알제 오자크의 실질적 종말", "e122403b"], "d": ["항복 조건에 따라 마지막 알제 데이 후세인은 가족과 재산과 함께 도시에서 내보내져 나폴리로 보내졌다. 1519년 셀림 1세(야부즈)에게 귀속되어 300년 동안 지중해에서 가장 강력한 오스만 해군 기지였던 오자크의 통치는 이렇게 끝났다.", "bf7169cf"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["러시아군의 왈라키아·몰다비아 철수 — 6년 점령의 종말", "efdb0275"], "d": ["1828-1829년 오스만-러시아 전쟁에서 러시아는 왈라키아와 몰다비아를 점령했고, 아드리아노폴리스(에디르네) 조약 이후에도 전쟁 배상금이 지불될 때까지 철수하지 않았다. 1834년 1월 배상금이 500만으로 감액되자 러시아군은 두 공국을 비웠고, 두 공국에는 새 보이보드가 임명되었다. 오스만의 종주권은 서류상으로 돌아왔으나, 러시아는 조직 규정(Reglement Organique)으로 확립한 영향력을 유지했다.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["레디프 예비군 조직의 창설", "15947493"], "d": ["아사키리 만수레이 무함마디예를 지원할 예비 병력으로 레디프 조직이 1834년 7월 8일자 규정에 따라 창설되었다. TDV 이슬람 백과사전의 레디프 항목에 따르면, 세라스케르(총사령관) 코자 휘스레브 파샤의 지휘 아래 지방의 각 카자에 약 1400명 규모의 대대들이 편성되었다. 이 조직은 상시 복무에 투입하지 않으면서 지방 치안도 지원하도록 설계되었다.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["외무부의 창설", "750c6c7d"], "d": ["마흐무드 2세는 대외 업무를 맡던 레이쉴퀴타브(서기장) 직책을 폐지하고 대신 외무부를 창설했다. TDV 이슬람 백과사전의 외무부 항목에 따르면, 새 부서의 초대 장관에는 메흐메드 아키프 파샤가 임명되었고, 조직은 빈 주재 대사 르파트 베이의 저택에서 업무를 시작했다. 이 조치는 오스만의 대외 정책을 근대적 부처 원칙에 따라 운영하는 출발점이 되었다.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["최고 사법 평의회(메즐리시 발라) 창설", "69db056e"], "d": ["마흐무드 2세는 제정할 법률과 규정을 심의할 고위 평의회로서 메즐리시 발라이 아흐캄 아들리예를 창설하게 했다. TDV 이슬람 백과사전의 해당 항목에 따르면, 평의회는 1838년 3월 31일 실제로 업무를 시작했으며 이후 탄지마트 개혁의 거의 전부가 이 기구를 통해 준비되고 감독되었다. 이 기관은 근대 오스만 관료제의 가장 중요한 중심 중 하나가 되었다.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["시노프 기습", "5947e93f"], "d": ["나히모프 제독이 지휘하는 러시아 흑해 함대는 선전 포고 없이 시노프 항에 정박한 오스만 함대를 기습했다. 배 12척이 침몰하고 2000명이 넘는 병사가 전사했으며, 함대 사령관 오스만 파샤는 포로가 되었다. TDV 이슬람 백과사전의 시노프 항목에 따르면, 기습으로 도시에서도 소모스크 7곳, 학교 2곳, 가옥 247채, 상점 170곳이 불탔고, 무슬림 5명과 기독교인 16명의 민간인이 목숨을 잃었다. 유럽 여론에서 '시노프의 참극'으로 크게 반향을 일으킨 이 사건은 몇 달 안에 영국과 프랑스가 오스만 편에서 참전하게 된 직접적인 계기가 되었다.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["『타스비리 에프캬르』의 발행", "506c98e2"], "d": ["시나시가 발간한 『타스비리 에프캬르』는 『타크비미 베카이』, 『제리데이 하바디스』, 『테르주마느 아흐발』에 이어 네 번째 튀르크어 신문으로 발행을 시작했다. TDV의 '타스비리 에프캬르' 항목에 따르면, 이 신문은 훗날 주필을 맡은 나므크 케말의 시대에 청년 오스만인 운동의 대변지가 되었다.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["청년 오스만인 협회의 결성", "335fb02d"], "d": ["무스타파 파즐 파샤의 주도로 유럽으로 도피한 오스만 지식인들은 13개 조의 규약을 갖추고 '청년 튀르키예'라는 이름으로 조직을 결성했다. TDV의 '청년 오스만인 협회' 항목에 따르면, 이 단체는 파리, 런던, 제네바에서 『무흐비르』와 『휘리예트』 같은 신문을 발행하여 입헌 정치에 대한 요구를 퍼뜨렸다.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["국가평의회(슈라이 데블레트) 창설", "b863b306"], "d": ["최고 사법 평의회(메즐리시 아흐캄 아들리예)가 둘로 나뉘어, 행정 업무를 맡는 국가평의회(슈라이 데블레트)와 사법 업무를 담당하는 사법 최고 법원(디바느 아흐캄 아들리예)이 설치되었다. TDV의 '슈라이 데블레트' 항목에 따르면, 프랑스의 국참사원(Conseil d'État)을 모델로 한 이 기관의 초대 의장에는 미드하트 파샤가 임명되었으며, 목적은 입법, 행정, 사법의 분리였다.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["다륄퓌눈(대학) 설립 칙령의 공포", "513704bf"], "d": ["대재상 알리 파샤와 교육부 장관 사프베트 파샤가 마련한 칙령으로 다륄퓌눈이 공식 설립되었으며, 첫 강의는 이미 1863년에 시작되었다. TDV의 '다륄퓌눈' 항목에 따르면, 이 기관은 1870년 2월 호자 타흐신 에펜디의 학장 아래 철학·문학, 이학, 법학 학부로 실제 교육을 시작했다.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["메젤레(오스만 민법전) 작업의 시작", "8abdcbee"], "d": ["사법 최고 법원장 아흐메드 제브데트 파샤를 위원장으로 설치된 메젤레 위원회는 하나피 법학에 기초한 민법전 준비에 착수했다. TDV의 '메젤레-이 아흐캄 아들리예' 항목에 따르면, 16권 1851개 조로 이루어진 이 저작의 마지막 분책은 1876년 9월 15일에 완성되어 시행되었으며, 이슬람법을 최초로 성문 법전화한 것으로 인정된다.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["『조국 혹은 실리스트라』 상연, 나므크 케말의 유배", "3861284c"], "d": ["애국심을 주제로 한 나므크 케말의 희곡이 게디크파샤 극장에서 상연되자 관객들은 \"조국 만세, 케말 만세\"를 외치며 거리로 쏟아져 나왔다. TDV의 '나므크 케말' 항목에 따르면, 이 시위에 겁먹은 정부는 『이브레트』 신문을 폐간하고, 1873년 4월 6일 나므크 케말을 재판 없이 키프로스(파마구스타)로 유배 보냈다.", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["압뒬아지즈의 의문스러운 죽음", "85816692"], "d": ["폐위된 뒤 본인의 요청으로 페리예 궁전으로 옮겨진(1876년 6월 1일) 압뒬아지즈는 6월 4일 자기 방에서 손목의 혈관이 잘린 채 발견되었다. 공사관 의사들도 참여한 19명의 의사단은 모호한 표현의 보고서를 작성했으며, 6월 6일 신문들은 그의 죽음을 자살로 발표했다. 그러나 압뒬하미드 2세가 지시한 조사는 이 죽음이 자살이 아니라 살인이라는 결론에 이르렀고, 피고들은 1881년 이을드즈 법정에서 재판을 받았다. 이 문제는 역사 서술에서 오늘날까지도 논쟁 중이다.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["미드하트 파샤의 대재상 해임과 추방", "b5247b06"], "d": ["헌법(카누느 에사시)의 설계자인 대재상 미드하트 파샤는 헌법 선포 6주 만에 압뒬하미드 2세에게 해임되어 하룻밤 사이에 국외로 추방되었다. TDV 이슬람 백과사전의 미드하트 파샤 항목에 따르면, 이 해임은 헌법에서 파디샤 자신의 권한을 제한하는 조항에 대한 그의 불편함과 관련지어진다. 파샤는 먼저 나폴리로, 이어 유럽의 여러 도시로 갔다.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["압둘아지즈 이븐 사우드가 라시드 왕조로부터 리야드를 되찾다", "75eb8830"], "d": ["10년 전 쿠웨이트로 망명했던 사우드 왕조의 젊은 압둘아지즈는 소규모 분견대로 리야드를 기습하여 알 라시드(샴마르)의 대리 총독을 살해하고 도시를 장악했다. TDV 이슬람 백과사전의 리야드 항목에 따르면, 라시드 왕조가 점점 약해져 도시에 증원군을 보낼 수 없었던 것이 이 기습의 성공을 도왔다. 이 사건은 이후 30년 동안 오늘날 사우디아라비아의 핵심을 이루게 되는 제2차 사우드 국가의 건국 순간으로 여겨진다.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["행동군의 이스탄불 입성", "41c8304c"], "d": ["테살로니키에서 출발한, 대부분 통일진보위원회 소속 부대로 이루어진 행동군은 3월 31일 반란을 진압하기 위해 이스탄불에 입성했다. TDV 이슬람 백과사전의 행동군 항목에 따르면, 사령관은 마흐무드 셰브케트 파샤가 맡았고 참모장은 대위(콜아아스) 무스타파 케말이었다. 짧은 교전 뒤 도시의 치안은 다시 확립되었다.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["마지막 오스만 하원의 해산", "2b709269"], "d": ["연합국 군대가 이스탄불을 공식 점령하고 다수의 의원이 체포된 뒤 하원은 활동할 수 없게 되었으며, 메흐메드 6세의 칙령으로 공식 해산되었다. TDV 이슬람 백과사전의 하원 항목에 따르면, 이 해산은 오스만 입헌 의회 전통의 사실상의 종말을 상징했다. 의회의 폐쇄는 앙카라에서 새 국민 의회를 소집해야 할 필요성을 강화했다.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["튀르키예 대국민의회의 개원", "6eab539d"], "d": ["이스탄불의 하원이 해산된 뒤 의원들은 앙카라에 모여 튀르키예 대국민의회를 열었고, 무스타파 케말 파샤가 의장으로 선출되었다. TDV 이슬람 백과사전의 튀르키예 대국민의회 항목에 따르면, 의회는 입법권과 행정권을 모두 장악한 비상한 성격을 지녔다. 이 개원은 민족 투쟁의 정치적·제도적 중심이 앙카라로 옮겨 간 전환점이었다. 이 사건으로 코니아, 시바스, 카이세리, 에스키셰히르, 에르주룸, 트라브존, 삼순, 디야르바크르, 반, 말라티아, 데니즐리, 이스파르타를 포함한 124개 정착지(튀르키예에서 점령되지 않은 지역)가 튀르키예 대국민의회 정부의 통치 아래 들어갔다.", "47a80fa7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["즈보르니크(이즈보르니크) 요새 정복", "657c465a"], "d": ["드리나 강가의 즈보르니크 요새는 1460년 오스만에 정복되었다. TDV 이슬람 백과사전에 따르면, 행정·군사 면에서 유리한 위치 때문에 먼저 카자의 중심지가 되었고, 1480년에는 같은 이름의 산자크 중심지로 승격되었으며, 1491년 석조 성벽으로 요새화되어 모스크 6곳, 수도장 8곳, 목욕탕들을 갖춘 중요한 행정·상업 중심지로 성장했다.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["카심 칸의 사망, 다니얄 칸의 즉위 (카심 칸국)", "522fd0fd"], "d": ["칸국의 창건자 카심 칸이 873/1468년에 사망하자 아들 다니얄이 뒤를 이었으며, 다니얄은 1486년까지 통치했다.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["디우 해전 — 포르투갈의 인도양 우위", "1778d347"], "d": ["구자라트 술탄국을 대신해 이 지역을 다스리던 말리크 아야즈의 함대는 맘루크의 지원을 받았으나, 이 연안에 보급 기지를 세우려던 포르투갈 총독 프란시스쿠 드 알메이다의 함대에 디우 앞바다에서 크게 패했다. 이 패배는 포르투갈에 인도양의 영구적인 해상 우위를 안겨 주었고 맘루크-구자라트의 해군력을 꺾었다. 이는 1517년 이후 오스만이 이어받은 홍해-인도양 투쟁(제다 방어, 1538년 디우 포위)의 배경이 되는 힘의 불균형의 시작으로 여겨진다.", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["칼렌데르 샤 반란", "f60f6ca4"], "d": ["아나톨리아의 재정난, 새 행정 개편에 대한 불만, 사파비 선전의 영향으로 치체클리, 아크차 코윤루, 마사들르, 보조클루 같은 큰 투르크멘 부족들과 앞선 바바 쥔눈 반란의 잔여 집단이 칼렌데르 샤 주위에 모여 약 3만 명의 세력을 이루었다. 반란군은 먼저 룸 베일레르베이를 격파했다. 대재상 마크불 이브라힘 파샤가 병력을 모으고 그들의 권리를 약속하자 칼렌데르에 대한 지지는 녹아내렸고 반란은 엘비스탄 부근에서 진압되었으며, 칼렌데르 샤와 벨리 뒨다르는 1527년 6월에 살해되었다.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["샤흐리조르 정복 — 잘름 요새의 점령", "4320d9b8"], "d": ["카누니의 나흐치반 원정 중 바그다드 베일레르베이 오스만 파샤는 샤흐리조르 지방의 장악을 맡았다. 그가 죽은 뒤 바그다드 베일레르베이가 된 발타즈 메흐메드 파샤는 이 지역의 중심 요새 잘름을 포위해 1554년 8월 22일(961년 라마단월 23일) 점령했다. 이로써 자그로스 산맥 서쪽 기슭의 샤흐리조르 분지는 오스만의 통치에 들어갔고 바그다드와 쿠르디스탄 사이의 연결이 확보되었다. 이 지역은 먼저 산자크로 만들어져 무라드 베이에게 주어졌다. 1563년 베일레르베이 무자페르 파샤는 새 주의 중심지로 귈란베르 요새를 세웠다. 이 요새는 1623년 샤 압바스의 명으로 허물어지고, 1638년 휘스레브 파샤 때에 다시 세워지게 된다.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["카심 칸국 군주의 기독교 개종과 칸 지위 박탈", "a1a8eeb9"], "d": ["칸국의 군주가 '세묜(시메온)'이라는 이름을 취하고 기독교인이 되었다. 러시아는 무슬림 백성의 반발을 고려해 그를 칸 자리에서 해임했다. 이 인물은 얼마 뒤 이반 뇌제에 의해 '차르와 루스의 대공'이라는 칭호로 모스크바의 명목상 군주로 선포되었다(1575). 이는 카심 칸국과 모스크바 왕좌 사이의 가장 놀라운 교차점이다.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["페잔 산자크의 트리폴리 귀속 — 무르주크와 사하라 대상로의 교차점", "2e6554a4"], "d": ["트리폴리 베일레르베이령의 압력으로 사하라 대상로의 교차점인 페잔은 무르주크를 중심지로 하여 오스만의 신속(臣屬)을 받아들였다. TDV 이슬람 백과사전의 페잔 항목에 따르면, 이 지역을 다스리던 아울라드 무함마드 왕조는 정기적으로 세금을 낸다는 조건으로 내정의 자유를 인정받았으며, 페잔은 1551년에 점령한 트리폴리 주에 속한 산자크로 편성되었다. 이로써 트리폴리-무르주크-보르누 노선의 노예, 금, 낙타 교역이 오스만의 통제 아래 들어왔다. 이 간접 통치는 1711년에 카라만리 가문에게, 1842년에는 직접적인 카자 행정으로 넘어가게 된다.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["나흐치반과 오르두바드의 오스만 통치 편입", "24d939b3"], "d": ["1583년 예레반이 점령되어 베일레르베이령의 중심지가 된 뒤, 아라스강 계곡을 따라 남동쪽으로 내려간 병력은 나흐치반과 오르두바드를 오스만의 통치에 편입시켰으며, 두 도시는 새로 세워진 예레반 주의 산자크가 되었다. TDV 이슬람 백과사전의 나흐치반 항목에 따르면, 이 도시에서 영구적인 오스만 통치가 처음 세워진 것은 이 전쟁 중이었다. 1553년 나흐치반 원정 때에는 도시를 점령했으나 약탈한 뒤 버렸을 뿐이었다. 이로써 예레반과 타브리즈 사이의 군용로가 열렸고 같은 해 9월 타브리즈에 입성할 수 있었다. 샤 압바스는 1603년에 나흐치반을 되찾게 된다.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["델리 하산 파샤의 반란과 보스니아 베일레르베이직을 통한 회유", "144f3f2d"], "d": ["첼랄리 반란의 지도자 카라야즈즈 압뒬할림이 1602년에 죽은 뒤 운동을 이어받은 그의 동생 델리 하산은, 계속되는 오스트리아 전쟁이 첼랄리 무리에게 허용한 행동의 자유를 이용해 퀴타히야를 침범하고 아피온카라히사르를 향해 진군했다. 국가가 오스트리아와 이란 전선을 동시에 감당하던 이 시기에 문제는 '부드럽게' 해결되었다. 델리 하산에게 파샤의 지위와 보스니아 베일레르베이직이 주어져 반란 운동은 1603년에 공식적으로 종결되었다.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["러시아군의 카심 시 점령, 우라즈 무함마드 칸", "b3f0bd34"], "d": ["러시아의 동란 시대(스무타)의 영향으로 러시아군은 카심 시를 포위해 점령하고 주민 대부분을 살육했다. 칸국의 군주 우라즈 무함마드는 가짜 드미트리 2세를 지지했기 때문에 표적이 되었으며, 이듬해(1610)에는 그 자신도 음모로 살해되었다.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["아조프 요새를 돈 코사크에게 상실", "ba068b2f"], "d": ["돈 코사크는 1637년 4월 21일에 포위한 아조프 요새를 두 달 뒤 점령했다. 흑해 북동쪽의 관문이자 돈강 교역의 열쇠인 이 요새는 처음으로 오스만의 손을 벗어났다. TDV 이슬람 백과사전의 아조프 항목에 따르면, 코사크는 1637년에 요새를 점령했고, 1641년에는 델리 휘세인 파샤가 지휘하는 석 달간의 대포위를 견뎌 냈으며, 1642년 크림 칸 메흐메드 기라이가 도착한 뒤에야 요새를 비웠다. 당시 국가는 바그다드 전선에 매여 있었다. 요새를 5년 동안 되찾지 못한 것은 흑해가 '오스만의 호수'라는 성격에 생긴 첫 균열이었다.", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["림노스와 사모트라키의 수복", "c445553b"], "d": ["1657년 8월 31일 테네도스를 탈환한 뒤 쾨프륄뤼 메흐메드 파샤는 함대를 북쪽으로 돌려 베네치아가 16개월 동안 장악해 온 림노스와 사모트라키를 되찾았다. TDV 이슬람 백과사전의 림노스 항목에 따르면, 섬은 1656년 7월 베네치아의 손에 넘어갔다가 1657년 11월에 되찾았다. 이로써 다르다넬스 해협 입구의 베네치아 봉쇄가 완전히 깨졌고 이스탄불의 곡물 수송로가 다시 안전해졌다. 이는 비상 권한을 갖고 취임한 대재상의 첫해에 거둔 가장 구체적인 성과이다.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["크닌을 베네치아에 상실 — 166년 동안의 달마티아 국경 요새 함락", "252406b7"], "d": ["1683년 빈 패전 뒤 여러 전선에서 벌어진 전쟁에서 베네치아군은 달마티아 내륙으로 진격했다. 달마티아 총독 지롤라모 코르나로가 포위한 크닌은 12일간의 공성 끝에 베일레르베이 메흐메드 파샤에 의해 항복되었다. 크닌은 1522년 가지 휘스레브 베이가 정복해 166년 동안 오스만의 수중에 있던 달마티아 국경선의 핵심 요새였으며, 이를 잃으면서 이 지역은 대부분 베네치아에 열렸다.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["이란의 점령에서 바스라 수복", "5b10c5c1"], "d": ["카림 칸 잔드의 동생 사디크 칸이 1776년에 점령한 바스라는 1779년 3월 2일 카림 칸이 죽은 뒤 이란에서 왕위 다툼이 시작되자 비워졌고, 사디크 칸은 왕위를 주장하며 이란으로 돌아갔다. 도시는 잠시 문타피크 부족의 손에 있다가 다시 오스만의 통치에 들어왔다. 시라즈에서 돌아온 전직 총독 대리(뮈테셀림) 쉴레이만 아가는 바스라 총독직을 요청했고, 대(大)쉴레이만 파샤라는 이름으로 바스라, 바그다드, 샤흐리조르의 총독이 되었다. 걸프 교역은 오스만의 통제로 돌아왔다. 점령기 동안 교역의 일부는 쿠웨이트로 옮겨 갔으며, 1778년부터는 사막 우편도 쿠웨이트에서 출발했다.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["티무르 샤의 사망, 자만 샤의 즉위 (두라니 왕조)", "c3effdb2"], "d": ["20년 넘게 나라를 안에서부터 공고히 한 티무르 샤가 사망하자 칸다하르, 헤라트, 카불의 총독이던 세 형제가 왕위를 두고 다투었다. 수도를 장악한 카불 총독 자만 샤가 1793년 5월 20일 샤가 되었다. 이 계승 위기는 왕조 분열 과정의 실질적인 시작이었다.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["아이 노아 — 하와이의 전통 카푸 제도 폐지", "0b10e1d8"], "d": ["카메하메하 1세가 죽은 지 6개월 뒤, 새 왕 리홀리호는 어머니 카아후마누의 지지를 받아 남녀가 따로 식사해야 한다는 금기(아이카푸)를 의도적으로 어겼다. '아이 노아'(자유로운 식사)라 불리는 이 행위는 전통적인 카푸 종교·법 체계를 공식적으로 종식시켰으며, 섬들의 옛 신전(헤이아우)은 곧 허물어졌다. 이는 서양 선교사의 도착(1820) 이전에 일어난 가장 큰 종교·정치적 단절이다.", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["런던 의정서 — 그리스 독립의 승인", "4c7b4b72"], "d": ["영국, 프랑스, 러시아가 런던에서 서명한 의정서는 아드리아노폴리스(에디르네) 조약이 정한 자치를 넘어 그리스를 독립 국가로 인정했다. 조항은 다음과 같다. 모레아 반도, 아티카, 에우보이아와 키클라데스 제도는 새 국가에 넘겨졌고, 국경은 아르타-볼로스 선으로 그어졌으며, 오스만 국가에 배상금을 지불하기로 결정되었고, 국가의 정체는 '독립 군주국'으로 정해졌다. 이는 제국에서 떨어져 나간 최초의 독립 국가로, 이후 발칸 지역 독립들의 법적 선례를 세웠다. 런던 의정서로 독립이 승인된 그리스에는 키클라데스 제도(낙소스, 티노스, 산토리니, 파로스, 밀로스, 시로스, 미코노스 등)가 포함되었다.", "920bfab9"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["압둘라 이븐 라시드의 하일 토후국 장악 — 샴마르(라시드) 왕조의 창건", "fb513b8a"], "d": ["1818년 메흐메드 알리 파샤의 군대가 디리야를 함락시키면서 자발 샴마르 지역은 사우드의 지배에서 벗어났고, 토후국은 이븐 알리 가문의 손에 남았다. 오스만 지배의 회복을 지지한 압둘라 이븐 라시드는 동생 우바이드와 함께 이븐 알리 가문에 맞선 싸움에서 1835년 승리하여 하일 토후국을 장악하고 라시드 왕조의 지배를 세웠다.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["하와이 최초의 성문 헌법 선포", "401a8a1d"], "d": ["왕국 최초의 완전한 성문 헌법이 선포되었다. 왕의 권한을 제한하고 대의 의회를 설립한 이 문서는 하와이를 입헌 군주국으로 바꾸었다.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["총검 헌법 — 칼라카우아 왕의 권한 축소", "4953363b"], "d": ["무장 민병대 집단이 칼라카우아 왕을 위협하여 왕권을 크게 축소하는 새 헌법에 서명하도록 강요했다. 이 문서는 '총검 헌법'(Bayonet Constitution)으로 불리며, 왕좌를 사실상 백인 정착민 엘리트의 통제 아래에 두었다.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["조지 투포우 1세의 사망, 조지 투포우 2세의 즉위 (통가)", "b56e2b32"], "d": ["건국 군주 조지 투포우 1세가 사망하면서 그의 증손자 조지 투포우 2세가 즉위했다. 대관식은 1893년 3월 17일 누쿠알로파에서 거행되었다.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["뉴질랜드, 여성에게 선거권을 부여한 최초의 자치국이 되다", "0d277cde"], "d": ["총독 글래스고 경이 서명한 새 선거법으로 뉴질랜드는 여성에게 의회 선거 투표권을 인정한 세계 최초의 자치국이 되었다.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["하와이 공화국 선포", "4346bd5d"], "d": ["1893년 릴리우오칼라니 여왕을 폐위한 공모자들은 임시 정부를 정식 공화국으로 바꾸었으며, 샌퍼드 돌이 대통령으로 선포되었다. 이 과도 체제는 1898년 미국 병합 때까지 지속되었다.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["뉴질랜드의 경계가 쿡 제도와 니우에를 포함하도록 확장", "d0370a33"], "d": ["뉴질랜드의 경계는 쿡 제도(라로통가, 아이투타키와 남부 제도, 그리고 북부 쿡 제도)와 니우에를 포함하도록 확장되었으며, 이 섬들은 뉴질랜드에 속한 영토가 되었다.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["조지 투포우 2세의 사망, 살로테 투포우 3세의 즉위 (통가)", "a3084f3b"], "d": ["조지 투포우 2세는 결핵으로 사망했다. 18세인 딸 살로테가 이튿날 여왕으로 선포되었고 대관식은 1918년 10월 11일에 거행되었다.", "a63672b5"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["세브르 조약 — 제국 분할의 문서", "64980d7b"], "d": ["오스만 정부가 연합국과 서명한, 제국을 사실상 청산하는 문서이다. 조항은 다음과 같다. 동트라키아와 이즈미르 지역은 그리스에 넘기고, 동아나톨리아에는 독립 아르메니아와 자치 쿠르디스탄을 두며, 시리아는 프랑스에, 이라크와 팔레스타인은 영국에 위임통치령으로 맡기고, 해협은 국제 위원회에 넘기며, 군대는 5만 700명으로 줄이고, 카피툴레이션을 부활시키며, 재정은 연합국의 감독에 맡기기로 했다. 앙카라의 대국민의회는 이 조약을 전혀 인정하지 않았고 서명자들을 조국의 반역자로 선언했다. 이 문서는 발효되지 못했으며 1923년 로잔 조약이 이를 대체했다. 지도에 이에 해당하는 표시가 없는 이유는 이 때문이다. 세브르는 법적으로 한 번도 시행되지 않았다.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["붉은 군대의 부하라 시 입성 — 마지막 아미르 알림 칸의 축출", "f8f5bfcf"], "d": ["붉은 군대는 1920년 9월 2일 부하라 시에 입성했고, 마지막 망기트 왕조 아미르 알림 칸은 왕좌에서 축출되었다. 아미르는 나라 동부의 두샨베로 물러나 그곳에서 반년 동안 소비에트에 맞선 투쟁을 지휘했다. 붉은 군대가 1921년 2월 21일 두샨베를 점령하자 아미르는 더 동쪽으로, 거기서 아프가니스탄으로 건너갔다. 칸국은 1920년 10월 6일 공식 폐지되었다(부하라 인민 소비에트 공화국 참조).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["부하라 인민 소비에트 공화국 선포", "ef579627"], "d": ["붉은 군대가 1920년 8월 28-31일에 부하라 아미르국을 무너뜨리고 아미르 알림 칸을 동부 부하라로 몰아낸 뒤, 파이줄라 호자예프를 수반으로 하는 부하라 인민 소비에트 공화국이 선포되었다.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["탄누투바 인민공화국의 독립 선언", "8710ea3d"], "d": ["투바 인민혁명당의 주도로 독립이 선언되었다. 첫 헌법 제1조는 이 국가가 '국제 관계에서 소비에트 러시아의 보호 아래' 활동한다고 규정했다. 이 사건으로 키질(벨로차르스크, 탄누투바)이 탄누투바 인민공화국에 넘어갔다.", "dc0ac64a"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["부하라 인민 소비에트 공화국의 새 헌법 채택", "fb17bf39"], "d": ["1918년 러시아 헌법과 달리 토지·생산 수단의 사적 소유를 허용하고 비프롤레타리아에게도 선거권을 인정하는 새 헌법이 채택되었다(폐위된 아미르의 친족과 대지주는 제외).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["호라즘 소비에트 사회주의 공화국으로의 전환", "14a1d26f"], "d": ["이 나라는 국호와 지위를 바꾸어 호라즘 소비에트 사회주의 공화국이 되었으며, 행정·법 체계는 소비에트 제도에 따라 다시 편성되었다.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["탄누투바 정부의 실질적인 업무 개시", "22ea1516"], "d": ["1922년 2월의 첫 당 대회 뒤에 구성된 정부가 실제로 업무를 시작했다.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["탄누투바의 첫 대(大)쿠릴타이 소집", "80fe15f2"], "d": ["나라의 첫 대(大)쿠릴타이(인민 의회)가 소집되었다. 이는 국가의 제도화 과정에서 첫 번째 대규모 대의 회의이다.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["민족 경계 획정으로 호라즘 SSR과 부하라 인민 소비에트 공화국의 종식 — 우즈베크·투르크멘 SSR의 수립", "e8c8ab4f"], "d": ["소비에트의 '민족 경계 획정'(natsionalno-territorialnoe razmezhevanie) 결정으로 호라즘 소비에트 사회주의 공화국과 부하라 인민 소비에트 공화국이 폐지되었고, 그 영토는 새로 세워진 우즈베크와 투르크멘 소비에트 사회주의 공화국 사이에 분할되었다(히바의 동부는 우즈베키스탄으로, 서부는 투르크메니스탄으로). TDV의 호라즘 항목은 '1924년 히바 칸국의 동부 지역은 우즈베크 소비에트 사회주의 공화국에, 서쪽 지역은 투르크멘 소비에트 사회주의 공화국에 넘겨졌다.'라고 적고 있으며 연도만 제시한다.", "58053c38"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["타바르카를 제노바인들에게서 탈취 — 로멜리니 가문의 산호 특권 종식", "b1f33eb5"], "d": ["1544년 카를 5세가 튀니스의 베이와 맺은 조약 이후 제노바의 로멜리니 가문은 타바르카 섬에 정착해 200년 동안 산호 특권을 보유했다. 섬은 오스만령 튀니스 한가운데의 기독교 교역 거점으로 남아 있었다. 후세인 왕조의 알리 파샤는 이 가문이 섬을 처분하려 한다는 소식을 듣고 병력을 보내 1741년 6월 12일 섬을 점령했다. 약 1500명의 기독교인이 튀니스로 이송되었다. 타바르카는 이날 이후 튀니스 오자크의 통치에 들어갔다.", "93c8bd7b"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["아미르 압드 알카디르의 국가 수립 — 알제리 서부 저항의 중앙집권화", "9e482383"], "d": ["알제 함락 뒤 흩어진 저항은 카디리 교단의 셰이흐 무흐이딘의 아들인 젊은 압드 알카디르를 중심으로 모였다. 1832년 11월 22일 마스카라 근처에서 부족 수장들이 그에게 '신자들의 지휘자(아미르 알무으미닌)'라는 칭호로 충성을 맹세했다. 그가 세운 체제는 부족 동맹이 아니라 정규 국가였다. 조폐소, 화약 제조소, 조세 제도와 타그뎀트의 수도를 갖추었다. 프랑스는 1837년 타프나 조약으로 그의 지배를 공식 인정했다. 압드 알카디르는 오스만이 아니라 모로코 술탄 압두라흐만의 종주권에 의지했다. 따라서 이 영토는 1832년 이후 오스만의 신속령이 아니다. 그는 1847년 12월 23일 항복했으며, 오스만 국가도 같은 해에 알제리에 대한 자신의 권리가 끝났다고 선언했다.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["콩스탕틴 함락 — 알제리 동부 베이국의 종말", "159fed36"], "d": ["1830년 알제가 함락된 뒤에도 동부 베이국은 해체되지 않았다. 마지막 베이 아흐메드는 콩스탕틴에서 자신의 통치를 이어 가며 오스만의 이름으로 행동한다고 선언했다. 1836년 프랑스의 첫 원정은 참패로 끝났다. 두 번째 원정군은 1837년 10월 6일 도시를 포위했고, 사령관 당레몽은 10월 12일 포격에 전사했으며, 10월 13일 성벽을 넘어 도시를 거리마다 점령했다. 아흐메드 베이는 산지로 물러나 1848년에야 항복했다. 이날은 알제리 동부에서 300년에 걸친 오스만-튀르크 통치가 사실상 끝난 날이다.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["타카 지역 정복과 카살라 건설", "cc3e0631"], "d": ["수단 총독 아흐메드 파샤 아부 위단은 1840년 아트바라강과 가시강 사이의 타카 지역을 이집트의 통치에 편입하고 카살라 시를 군사 본부로 세웠다. 이 도시는 센나르와 수아킨 사이의 대상로와 아비시니아 국경 지대를 감독하는 주(무디리야) 중심지가 되었다.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["마스카라의 프랑스 점령 — 압드 알카디르의 수도 상실", "bd363c05"], "d": ["1841년 뷔조가 총독으로 부임하면서 프랑스의 전략은 바뀌었다. 해안에 머무는 대신 내륙 도시를 하나씩 점령하는 것이었다. 오랑, 모스타가넴, 메데아에서 출발한 기동 부대들이 압드 알카디르의 정규 국가의 중심지들을 점령했으며, 조폐소, 화약 제조소, 곡물 창고를 갖춘 진정한 수도였던 마스카라가 그중 가장 중요했다. 이후 아미르는 고정된 중심지를 세우기를 포기하고 군대를 '스말라'라고 불리는 유목 야영지로 바꾸었다.", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["셸리프 계곡과 테네스 점령 — 오를레앙빌 건설", "e1eeeb68"], "d": ["압드 알카디르를 추격하기 위해 프랑스인들은 1843년 4월 셸리프 계곡 한가운데에 오를레앙빌이라는 새 도시를 세웠으며, 같은 해 해안의 테네스 항도 점령했다. 이로써 알제와 오랑 사이의 내륙 회랑이 프랑스의 통제에 들어갔고 다흐라 산지의 저항은 포위되었다. 같은 해 5월 16일 압드 알카디르의 유목 야영지 '스말라'가 우연히 발견되어 해산되었다.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["시디 벨 아베스 요새화 야영지 설치", "fb33ec29"], "d": ["뷔조는 1843년 6월 12일 베도 장군에게 시디 벨 아베스에 해자와 성벽을 갖춘 요새화 야영지를 세우라고 명령했다. 공사는 6월 18일에 시작되었고 같은 해 11월 외인부대의 1개 대대가 이곳에 주둔했다. 이 야영지는 오랑과 틀렘센 사이의 내륙 평야를 통제하는 영구 기지가 되었다.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["네드로마와 모로코 국경 지대의 프랑스 통제 이관", "61d821f3"], "d": ["1843년 압드 알카디르가 모로코로 물러난 뒤, 틀렘센 북서쪽의 네드로마와 트라라 해안은 프랑스의 통제에 들어갔다. 1844년 8월 14일의 이슬리 전투에서 모로코군은 참패했고, 두 나라 사이의 국경은 1845년 3월 18일 랄라 마그니아 협정으로 그어졌다. 네드로마는 이 선의 알제리 쪽에 남았다.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["라구아트 함락 — 사하라의 관문 개방", "b161b32c"], "d": ["펠리시에 장군은 6000명의 병력으로 1852년 11월 21일 라구아트를 포위했고, 12월 4일 도시는 유혈의 돌격으로 함락되었다. 라구아트는 텔 지대와 사하라 사이의 통로를 장악한 오아시스 도시였다. 이곳의 함락은 프랑스의 진격로를 사막 대상로로 열었고, 1년 안에 므자브 연맹이 공납 의무를 지게 되는 길을 닦았다.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["보고스(케렌) 지역의 이집트 병합", "b2ab83ce"], "d": ["케디브 이스마일이 홍해 서해안에 세운 '동수단 및 홍해 연안' 주의 총독 베르너 문칭거 파샤는 1872년 빌렌족이 사는 보고스 지역과 그 중심지 케렌을 이집트에 편입했다. 이는 이집트가 아비시니아 고원의 가장자리까지 이룬 가장 지속적인 진출이었으며, 아비시니아와의 12년에 걸친 국경 분쟁을 시작시켰다.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["다르푸르 술탄국의 이집트 병합 — 주바이르 파샤의 알파시르 입성", "f41268ed"], "d": ["상아와 노예 교역으로 세력을 키운 주바이르 라흐마 파샤는 레밍턴 소총으로 무장한 병력으로 1874년 10월 25일 마나와시에서 푸르군을 궤멸시켰으며, 술탄 이브라힘은 전투에서 전사했다. 주바이르는 11월 2일 전투 없이 알파시르에 입성했고 1603년부터 이어진 케이라 왕조의 통치는 사실상 끝났다. 이로써 다르푸르는 카발랄르 가문의 이집트의 수단 주들에 편입되었으나, 케이라 가문의 산악 저항은 1891년까지 이어졌다.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["므자브 오아시스(가르다이아) 병합", "9372959f"], "d": ["므자브의 이바디파 도시들은 1852년 프랑스에 세금을 내기로 동의했으나 내부 행정은 유지했었다. 30년 뒤인 1882년 이 지역은 직접 프랑스 영토에 편입되었고 가르다이아는 군정에 속하게 되었다. 이로써 북부 사하라의 마지막 자치 지대도 법적으로 끝났다.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["알렉산드리아 포격과 영국군 상륙", "18d57bf8"], "d": ["우라비 파샤가 이끄는 장교 운동이 케디브를 통제 아래 두자, 영국은 수에즈 항로의 안전을 구실로 개입했다. 시모어 제독의 함대는 1882년 7월 11-12일 알렉산드리아의 해안 포대를 포격했으며, 도시에서 일어난 화재와 약탈 뒤인 7월 15일 영국군이 상륙했다. 오스만 국가는 법적으로 주권을 지닌 자신의 주에서 벌어진 이 작전을 막지 못했고 개입에 참여하라는 요청에도 답하지 않았다. 이로써 32년 동안 이어질 점령의 첫걸음이 내디뎌졌다.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["텔 알카비르 전투 — 우라비군의 와해", "8e38fecf"], "d": ["울슬리는 병력을 수에즈 운하를 통해 이스마일리아에 상륙시킨 뒤 사막을 행군시켜 1882년 9월 13일 새벽 텔 알카비르의 이집트 참호를 기습했으며, 전투는 한 시간 만에 끝났다. 우라비는 이튿날 항복했고 영국 기병대는 같은 날 카이로에 입성했다. 이날 이후 이집트의 재정·군사·대외 업무는 사실상 영국의 통제에 들어갔으며, 오스만의 종주권은 법적으로 1914년까지 이어졌다.", "a399d51c"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["다르푸르가 마흐디군에게 넘어가다 — 슬라틴 파샤의 항복", "6d8992d4"], "d": ["다르푸르 총독 슬라틴 파샤는 1882년부터 리제이카트 부족의 마흐디파 반란에 대처하고 있었다. 그는 병사들이 패배를 자신이 기독교인인 탓으로 돌린다고 생각하여 1883년 공개적으로 무슬림이 되어 압둘카디르라는 이름을 택했다. 1883년 11월 코르도판에서 힉스 파샤의 군대가 전멸한 뒤에는 저항이 무의미해졌고, 그는 1883년 12월 23일 아미르 마딥보에게 항복했다. 다르푸르의 작은 이집트 초소들도 곧 같은 길을 따랐으며, 10년간의 튀르크-이집트 통치는 끝났다. 이 사건으로 자발 마라(다르푸르)는 마흐디국의 통치에 들어갔다.", "bd700253"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["파시르 수비대의 마흐디파 항복", "68f0760d"], "d": ["1883년 12월 23일 슬라틴이 항복한 뒤에도 파시르 요새의 이집트 수비대는 저항했다. 7일간의 포위에서 우물을 잃은 수비대는 1884년 1월 15일 항복했으며, 무기를 내려놓았고 요새는 마흐디파에게 넘어갔다.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["휴잇(아두와) 조약 — 보고스를 아비시니아에 넘기다", "0de1b701"], "d": ["마흐디 반란으로 수단의 이집트 수비대들이 포위되자, 영국은 아비시니아의 도움을 얻기 위해 1884년 6월 3일 아두와에서 요한네스 4세와 조약을 체결했다. 조약 제2조는 보고스를 아비시니아에 돌려주었고, 그 대가로 아비시니아는 포위된 수비대들이 마사와를 거쳐 철수할 길을 열었다. 이로써 케렌은 12년간의 이집트 통치에서 벗어났으며, 이 지역은 5년 뒤 이탈리아령 에리트레아에 편입된다.", "b7e73617"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["쾨프뤼히사르 점령과 예니셰히르 건설의 준비", "39abff03"], "d": ["부르사와 이즈니크 사이의 길목 요새들을 함락함으로써 두 도시를 포위할 전진 사령부의 기초가 놓였다.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["예니셰히르 건설", "d3275837"], "d": ["부르사와 이즈니크 포위전을 지휘하기 위해 최초의 정규 오스만 수비대 정착지가 세워졌으며, 오르한 가지가 이곳에서 태어났다.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["이즈니크의 첫 포위와 마르마라즉 정복", "cdca2349"], "d": ["이즈니크는 처음으로 포위되었으나 함락되지 않았다(확정적인 정복은 1331년). 인근의 마르마라즉 요새는 이때 점령되었다.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["카탈루냐 부대의 아나톨리아 원정", "4fd940d5"], "d": ["튀르크의 진격을 막기 위해 비잔티움이 고용한 카탈루냐 부대는 일시적인 성공을 거두었으나 지속되지 못했다. 이들이 철수하면서 접경 베이국들의 진격은 빨라졌다.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["쾨세 미할의 이슬람 개종과 오스만 합류", "ca0d86e1"], "d": ["하르만카야의 테크푸르(비잔티움 영주) 쾨세 미할은 무슬림이 되어 자신의 요새와 부하들과 함께 오스만 가지에게 합류했으며, 비잔티움 출신의 첫 오스만 지휘관이 되었다.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["오르한 베이의 실질적인 통치권 인수", "6dadbefc"], "d": ["오스만 가지의 노쇠와 병환으로 부르사 포위와 원정의 실질적인 지휘와 운영은 아들 오르한 베이에게 넘어갔다(공식 즉위는 1326년이다).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["무다니아 점령", "0a623368"], "d": ["부르사의 항구인 무다니아가 점령되면서 도시의 해상 연결이 끊겼고, 부르사 포위는 숨통을 죄는 단계에 들어섰다.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["아크야즈와 임랄르섬의 오스만 편입 (사료에 날짜 없음)", "380c60ce"], "d": ["아크야즈는 오스만 베이 시대에(1305년 원정 이후의 해들에) 오스만 습격의 표적이 되었으나, 확정적으로 점령된 해는 알 수 없다. 임랄르섬이 언제 점령되었는지는 어떤 사료에도 없다. 지도의 1324년 경계는 자리 표시용 임시값이다.", "69782c1e"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["아크차 코자의 칸드라 일대 점령", "341bb97e"], "d": ["오르한 가지의 접경 영주 가운데 하나인 아크차 코자는 사판자 호수 서쪽의 본거지에서 이즈미트 지방을 습격하던 중 1326년 무렵 칸드라와 그 일대를 손에 넣었다. 이즈미트는 아직 비잔티움의 수중에 있었으며, 이 도시는 1337년에야 함락된다.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["얄로바와 카라뮈르셀의 편입", "133cb07a"], "d": ["이즈미트만 남안의 얄로바와 그 일대가 이해에 튀르크인의 손에 들어갔다. 해안 지대는 오르한 베이가 카라뮈르셀 가지에게 티마르로 주었다.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["아크차 코자의 아이도스와 사만드라 성채 점령", "ce4daa8a"], "d": ["칸드라를 점령한 뒤 아크차 코자는 코누랄프, 가지 압두라흐만과 함께 카르탈 부근의 아이도스 요새를, 이어 그 북쪽의 사만드라 성채를 점령했으며, 사만드라 지역은 그에게 사유지로 주어졌다. 아크차 코자는 1328년 칸드라 근처에서 죽었고, 이 지역의 접경 영주직은 무라드 왕자에게 주어졌다.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["오스만-아이든-사루한 동맹", "9df6bb74"], "d": ["세 베이국은 비잔티움에 맞서 공동으로 행동했다. 아이든 가문의 우무르 베이의 함대는 트라키아 해안을 습격하여 제2전선에서 비잔티움을 소모시켰다.", "32ca49ea"]},
"OLAYLAR_EK:1334-01-01:0":{"b": ["겜리크(키오스) 정복", "66fc4bcd"], "d": ["마르마라해로 트인 겜리크만의 해안 도시 겜리크(키오스)가 오스만의 손에 넘어갔다. 1326년 부르사가 항복할 때 도시의 테크푸르는 가족과 함께 겜리크로 보내졌다. 즉 겜리크는 1326년에도 여전히 비잔티움의 수중에 있었다. 아르무틀루에 대해서는 별도의 날짜를 찾지 못했으며, 겜리크의 연쇄에 묶인다.", "27ef02f4"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["오르한 가지와 테오도라의 혼인: 비잔티움 동맹", "9b67a590"], "d": ["비잔티움의 왕위 다툼에서 칸타쿠제노스를 지원한 오르한 가지는 그의 딸 테오도라와 혼인했다. 이 동맹을 통해 오스만 군대는 루멜리아를 가까이에서 알게 되었다.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["앙카라 점령", "49bf1f6d"], "d": ["아히가 통치하던 앙카라가 오스만의 행정 아래 들어가면서 중부 아나톨리아로 가는 길이 열렸다. 같은 날짜에 편입된 다른 지역: 시브리히사르, 찬크르.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["쉴레이만 파샤 시대의 트라키아 진격: 말카라, 입살라, 테키르다으", "fb31cf02"], "d": ["갈리폴리에 교두보를 세운 뒤 쉴레이만 파샤는 반도에서 북쪽으로 나아가 마르마라 해안과 마리차강 하구 사이의 평야를 차근차근 점령했다. 이렇게 말카라, 입살라, 로도스추크(테키르다으)는 갈리폴리와 마리차 계곡을 잇는 끊김 없는 회랑을 이루었다. 이 회랑 없이는 에디르네로 진군할 수 없었다. 1357년 왕자의 갑작스러운 죽음으로 멈춘 진격은 랄라 샤힌과 하즈 일베이가 이어 가게 된다.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["할릴 왕자의 납치", "b52ac3d7"], "d": ["오르한 가지의 작은아들 할릴이 포차의 해적에게 납치되었으며, 몸값을 둘러싼 위기는 여러 해 동안 오스만-비잔티움 관계의 현안이 되었다.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["에디르네 구원로 차단: 초를루, 륄레부르가즈, 바바에스키, 케샨 요새", "8e8ad485"], "d": ["할릴이 구출된 뒤 정복 작전을 재개한 무라드 왕자는 외부에서 올 수 있는 원군으로부터 에디르네를 고립시키기 위해 아큰즈(기습 기병)를 이스탄불 앞까지 보냈다. 이스탄불-에디르네 가도상의 초를루, 륄레부르가즈, 바바에스키 요새와 남트라키아 교통의 요지 케샨이 점령되었다. 에디르네의 항복은 이 포위망이 완성된 뒤에 이루어졌다.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["디메토카 점령 — 마리차 계곡의 개통", "b59aee83"], "d": ["마리차 계곡의 요충 요새인 디메토카(디디모티호)가 점령되면서 에디르네 정복의 길이 열렸다. 갈리폴리에서 북쪽으로 뻗는 회랑이 완성되기 전에는 에디르네로 진군할 수 없었기 때문에, 루멜리아 정복의 순서에서 이 요새는 에디르네보다 앞선다. 도시는 한동안 술탄들의 루멜리아 사령부가 되었다. 디메토카를 점령한 부대는 이어 쿨렐리 부르가즈(피티온) 같은 작은 요새들과 함께 중부 마리차 지역 전체를 장악했다.", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["갈리폴리 상실 (사보이아 십자군)", "00e7e415"], "d": ["비잔티움 황제의 사촌인 사보이아의 아마데오의 함대가 갈리폴리를 점령해 비잔티움에 넘겨주었으며, 루멜리아의 오스만 교두보는 10년 동안 해협 건너편에서 관리되었다. 같은 날짜에 상실한 다른 정착지: 침페.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["치르멘 전투 — 마리차 계곡의 장악", "cd738d8d"], "d": ["세르비아 영주들의 군대는 야간 기습으로 흩어졌고, 마케도니아와 로도피의 세르비아·불가리아 현지 영주들은 하나씩 오스만에 공납을 바치기 시작했다. 이는 직접 정복이 아니라 속국화 물결의 시작이었다. 오스만 전승에서 이 전투는 '스르프 슨드으(세르비아인의 패망)'라는 이름으로, 1364년에 하즈 일베이가 에디르네를 되찾으러 온 십자군에게 가한 야간 기습으로도 이야기된다. TDV는 이 연대가 틀렸으며 두 이야기는 같은 전투에 관한 것이라고 밝힌다.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["플로브디프와 스타라 자고라 정복", "e780c9ae"], "d": ["마리차 계곡 상류의 플로브디프와 그 북쪽의 스타라 자고라가 점령되었고, 불가리아 차르국은 공납국이 되었다. 플로브디프와 소피아 사이의 타타르파자르즈으와 이흐티만 경로는 치르멘 이후 속국이 된 현지 영주들의 손에 남았다. 같은 날짜에 상실한 다른 정착지: 하스코보, 클로코트니차.", "019bac28"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["속국 비잔티움: 무라드 1세의 군대에 선 요안니스 5세 (1371년 치르멘 승리의 결과)", "13ffe568"], "d": ["TDV에 따르면 1371년 9월 26일 치르멘(마리차) 전투의 승리 이후 비잔티움 제국은 오스만의 지배를 인정하고 공납과 오스만군에서의 복무를 받아들여 속국의 처지가 되었다. 황제 요안니스 5세는 이 의무에 따라 1373년 무라드 1세의 군대에 합류했으며, 그때 이스탄불에 남겨 둔 아들 안드로니코스 4세는 부르사의 사브즈 베이 왕자와 함께 아버지들에게 반란을 일으켰다.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["갈리폴리 탈환", "5f96c0a5"], "d": ["비잔티움의 왕위 다툼에서 오스만의 지원을 받은 안드로니코스 4세는 그 대가로 갈리폴리를 돌려주었으며, 루멜리아와 아나톨리아를 잇는 다리가 다시 놓였다. 같은 날짜에 편입된 다른 지역: 침페.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["게르미얀의 지참금: 퀴타히아 편입", "d6a6fe61"], "d": ["게르미얀 가문의 쉴레이만 샤의 딸 데블레트샤 하툰이 이을드름 바예지드와 혼인하면서 퀴타히아, 시마브, 타브샨르, 에으리괴즈가 지참금으로 오스만에 넘어갔다. 전쟁 없는 팽창의 전형적인 사례이다. 같은 날짜에 편입된 다른 지역: 아피온.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["하미드 지방 매입: 으스파르타 편입", "4a1b6047"], "d": ["하미드 가문의 휘세인 베이는 자기 베이국의 일부(악셰히르-베이셰히르-으스파르타)를 현금을 받고 무라드 1세에게 팔았다. 하미드 지방의 나머지는 1391년에 이을드름이 병합하게 된다. 같은 날짜에 상실한 다른 정착지: 이스하클르.", "3930685b"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["세레스 정복", "d4d28b60"], "d": ["동마케도니아의 열쇠인 세레스가 점령되었고, 테살로니키는 포위망 안에 들어갔다. 소피아와 세레스 사이의 큐스텐딜-페트리치-네브로코프-드라마 선은 이 시점에 아직 직접 편입되지 않았으며, 차례로 1370년대에서 1383년 사이에는 속국이 되고 1383년 이후 직접 통치로 넘어갔다. 같은 날짜에 상실한 다른 정착지: 게브겔리야, 킬키스(아브라트히사르).", "69be987a"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["소피아 정복", "96d5f01f"], "d": ["발칸산맥의 서쪽 고개들이 장악되었다. 이 시점에 세레스는 이미 1383년부터 확보되어 있었으므로 트라키아와 마케도니아의 영토는 끊김 없는 하나의 덩어리를 이루었다.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["니시 정복", "77f5d632"], "d": ["모라바 계곡의 자물쇠인 니시가 점령되면서 세르비아 전제공국은 직접적인 위협 아래 놓였다.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["테살로니키의 첫 항복", "96010ee9"], "d": ["긴 봉쇄 끝에 도시가 항복했다(1403년 비잔티움에 반환되며, 1430년에 확정적으로 정복된다). 같은 날짜에 편입된 다른 지역: 카발라. 같은 날짜에 상실한 다른 정착지: 랑가다스, 엘레프테루폴리(프라비슈테).", "834119a2"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["오스만-제노바 아흐드나메 — 1352년 조약의 갱신", "be11d17a"], "d": ["페라에서 온 제노바 사절들과 오르한 가지 시대부터 이어진 1352년의 통상 협정이 갱신되었으며, 두 나라 사이의 세금, 포로 대우, 자유 무역이 다시 정해졌다. 이는 오스만과 제노바 사이에 공식적으로 알려진 최초의 우호 통상 아흐드나메(특허 조약)로 여겨진다. 군사 동맹이 아니라 순수한 통상 협정이다.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["찬다를르 알리 파샤의 불가리아 원정: 슈멘과 루세 점령", "2781c3a9"], "d": ["불가리아 차르국의 도나우 연안 요새들이 한 번의 원정으로 접수되었다. 같은 해 보스니아의 빌레차에서 당한 패배와 혼동해서는 안 된다. 이는 별개의 전선에서 동시에 거둔 성공이었다. 터르노보와 비딘은 아직 불가리아가 지키고 있던 마지막 중심지였다.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["빌레차의 패배", "89ba0a64"], "d": ["보스니아를 향한 아큰즈(기습 기병) 부대가 빌레차에서 매복에 걸려 괴멸되었다. 발칸에서의 이 첫 대차질은 코소보로 이어지는 동맹을 고무했다.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["서아나톨리아 베이국들의 병합: 사루한, 아이든, 멘테셰", "dcc33b71"], "d": ["세 베이국이 한 번에 편입되었다. 사루한 베이국의 중심지 마니사, 아이든 베이국의 중심지 아이든(이즈미르의 위쪽 요새도 포함되나, 항구의 아래쪽 요새는 1402년까지 여전히 성 요한 기사단의 수중에 있었다), 멘테셰 베이국의 중심지 무을라-밀라스(다트차-보드룸-마르마리스-페티예 해안 지대 포함)이다. 에게해 연안은 처음으로 하나의 손에 통합되었다. 같은 날짜에 편입된 다른 지역: 쇠케.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["테케 지방 병합: 안탈리아 편입", "fdbeee5c"], "d": ["지중해 연안의 테케 지방이 오스만 영토에 편입되었다. 테케 가문은 하미드 가문에서 갈라져 나온 분파이다. 펠레퀴딘 뒨다르 베이가 자신이 정복한 안탈리아를 동생 유누스 베이에게 맡기면서 1321년 무렵 별도의 베이국이 생겨났다. 그래서 지도에서 안탈리아와 그 일대는 1321년 이후 하미드 가문의 색이 아니라 테케 가문의 색으로 표시된다. 이 베이국은 앙카라 전투 이후 재건되었으며, 확정적으로 청산된 것은 1423년에 이르러서였다.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["스코페 정복", "9e5a1af5"], "d": ["바르다르 마케도니아의 중심지가 점령되었고, 스코페는 루멜리아의 주요 접경 중심지 가운데 하나가 되었다.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["카스타모누 병합", "876330ba"], "d": ["잔다르 가문의 카스타모누 분파는 제거되었고 시노프 분파는 속국으로 존속했다. 같은 날짜에 편입된 다른 지역: 바르튼, 사프란볼루, 악차코자, 데브레크, 에플라니, 카라데니즈 에레일리, 토시아.", "c1158ca8"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["터르노보 함락 — 불가리아 병합", "ff666977"], "d": ["불가리아 차르국의 수도가 함락되었고, 불가리아는 오스만의 직접 통치 아래 들어갔다. 같은 날짜에 편입된 다른 지역: 플레벤, 로베치, 가브로보.", "c2c12ea0"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["로베치 요새의 오스만 귀속", "a55e87a0"], "d": ["불가리아 차르 이반 시슈만의 요새 가운데 하나인 로베치는, 터르노보가 함락된 1393년 원정에서 시슈만의 다른 지방들과 함께 오스만 영토에 편입되었다. 사료는 단정적으로 말하지 않는다. 정복이 이해였던 것으로 '추정된다'.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["도브루자 편입", "478e36f2"], "d": ["도나우 삼각주까지 뻗은 도브루자 지역이 편입되었다. 같은 날짜에 편입된 다른 지역: 실리스트라, 콘스탄차, 바바다그, 발치크, 허르쇼바, 툴체아, 망갈리아, 이삭체아, 투트라칸, 머친, 퀴취크 카이나르자.", "84901de2"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["테살리아 진출", "8bec60dd"], "d": ["예니셰히르(라리사)를 중심으로 한 테살리아 평야가 오스만의 행정 아래 들어갔다. 같은 날짜에 편입된 다른 지역: 트르할라, 이즈딘(라미아).", "d9f2128c"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["로비네 전투 — 왈라키아 원정", "343ae7a9"], "d": ["왈라키아 총독 미르체아와 벌인, 결과에 논란이 있는 유혈 전투 이후 왈라키아는 오스만에 공납을 바치기로 했으며, 도나우강 북쪽의 속국 체제가 세워졌다.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["니코폴리스 정복", "b9791717"], "d": ["1395년 왈라키아인을 상대로 한 로비네 전투 이후 이을드름 바예지드는 도나우강 변의 니코폴리스 요새를 점령했다. 일부 작자 미상의 불가리아 연대기는 정복이 1395년 6월 3일에 이루어졌다고 적는다. 정복 연대는 사료마다 하나가 아니다. TDV 이슬람 백과사전의 니코폴리스 전투 항목은 바예지드가 1394년의 도나우 원정에서 실리스트라와 니코폴리스를 손에 넣었다고 적는다. 이 요새는 1396년의 유명한 십자군 원정 때 포위되지만 함락되지 않는다. 같은 날짜에 편입된 다른 지역: 오흐리드.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["니코폴리스 요새의 오스만 귀속", "327012c9"], "d": ["로비네 습격 이후 이을드름 바예지드는 니코폴리스를 점령했으며, 오스만의 속국 통치자로서 그곳에 머물던 불가리아 차르 이반 시슈만은 제거되었다. 지도에서 니코폴리스는 이날부터 불가리아 차르국에서 오스만으로 넘어간 것으로 기록되어 있다.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["아나돌루 히사르 건설", "aa259b00"], "d": ["이스탄불 봉쇄를 지원하기 위해 보스포루스 해협의 아나톨리아 쪽에 귀젤제히사르(아나돌루 히사르)가 건설되었다. 해협 통제를 향한 최초의 영구적인 조치였다.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["비딘 병합", "ee1ae44b"], "d": ["니코폴리스의 승리 이후 마지막 불가리아 공국인 비딘도 병합되었다.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["카라만의 첫 번째 병합", "3cf07876"], "d": ["악차이 전투의 승리로 카라만 가문의 영토가 처음으로 오스만에 편입되었다(공위 시대에 다시 재건된다).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["자니크 해안 편입: 삼순", "af9c40fa"], "d": ["카드 부르하네딘이 백양 왕조의 카라윌뤼크 오스만 베이에게 포로가 되면서 생긴 공백 속에서, 이을드름 바예지드는 먼저 흑해 연안의 자니크 지역을 오스만 행정에 귀속시켰다. 이로써 삼순과 그 일대는 왕조의 첫 흑해 항구가 되었다. 내륙의 시바스-토카트-카이세리 선은 2주 뒤 카드 부르하네딘 국가가 사실상 해체되면서 편입된다.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["말라티아 점령", "7cb6ae16"], "d": ["맘루크 국경의 말라티아가 점령되었다. 이는 티무르와의 긴장을 높인 조치 가운데 하나였다.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["티무르가 말라티아를 점령해 카라윌뤼크 오스만에게 맡김 — 티무르 철수 후 둘카디르 가문이 탈환", "ad2ce7d8"], "d": ["이을드름 바예지드는 1399년에 점령한 말라티아를 둘카디르 가문의 나스레딘 메흐메드에게 맡기고 부르사로 돌아갔다. 1400년 아나톨리아에 들어온 티무르는 먼저 시바스와 엘비스탄을, 이어 말라티아를 점령했다. 도시와 그 일대는 약탈당했고, 통치는 티무르를 따르던 카라윌뤼크 오스만에게 맡겨졌다. 티무르가 이 지역을 떠나자 둘카디르 가문이 다시 말라티아를 장악했으며, 이로써 오스만의 지배는 앙카라 전투 이전에 끝났다.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["쉴레이만 첼레비와 비잔티움의 조약: 테살로니키 반환", "cc503cc2"], "d": ["공위 시대에 루멜리아를 다스리던 쉴레이만 첼레비는 비잔티움 및 라틴 국가들과 합의하여 테살로니키와 메셈브리아까지의 흑해 연안을 비잔티움에 넘겨주었다(TDV fetret-devri: 갈리폴리 조약, 1403년 2월). 지도에서 이으네아다, 레조보, 아흐토폴이 비잔티움으로 넘어가며, 테살로니키는 이 날짜에 지도상 오스만에서 벗어난다.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["갈리폴리 해전의 패배 (베네치아)", "b71d4d68"], "d": ["베네치아 함대가 갈리폴리 앞에서 오스만 함대에 대패를 안겼다. 이 사건은 초기 오스만 해양 활동의 한계를 보여 주었다.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["뒤즈메제 무스타파의 봉기", "0ec43138"], "d": ["이을드름의 아들이라고 주장한 무스타파 첼레비는 비잔티움의 지원을 받아 루멜리아에서 술탄을 자칭했다. 무라드 2세는 1422년에 봉기를 진압하고 경쟁자를 처형했다.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["무라드 2세의 이스탄불 포위", "4b9d9fba"], "d": ["비잔티움이 뒤즈메제 무스타파를 지원한 데 대한 대응으로 무라드 2세는 이스탄불을 포위했으나, 동생 퀴취크 무스타파가 아나톨리아에서 반란을 일으키도록 부추겨지자 포위를 풀었다.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["테살로니키의 베네치아 이양", "bfa6c4a0"], "d": ["오스만의 압박을 받던 비잔티움 총독은 도시를 베네치아에 넘겨주었으며, 7년 동안 이어질 오스만-베네치아 분쟁이 시작되었다.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["서아나톨리아 베이국들의 재병합: 멘테셰와 아이든", "aca30a48"], "d": ["공위 시대에 재건된 두 에게해 베이국은 무라드 2세 시대에 확정적으로 오스만 영토에 편입되었다. TDV의 멘테셰 베이국 항목에 따르면 무라드 2세는 827년(1424)에 멘테셰 지방을 손에 넣고 베이국을 이끌던 두 형제를 투옥했다. 아이든 베이국 항목에 따르면 아나톨리아 베일레르베이 함자 베이가 다시 복종을 거부한 쥐네이드 베이를 붙잡아 가족과 함께 처형했고(829/1425-26), 아이든 지방은 오스만에 넘어갔다. 1344년부터 이즈미르의 항구 요새를 쥐고 있던 성 요한 기사단은 1402년에 이를 티무르에게 빼앗겼고 이 지역은 다시 아이든 가문의 통제 아래 돌아갔는데, 이번 병합으로 이곳도 오스만에 편입되었다. 테케 지방(안탈리아)은 이 항목의 대상이 아니다. 테케 가문은 1423년에 따로 청산되었다. 한편 게르미얀은 1429년 유언에 따라 편입된다.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["유언에 의한 게르미얀 병합", "9eb86b77"], "d": ["자식 없이 죽은 게르미얀의 베이 야쿠브 2세는 유언으로 자신의 영토를 오스만에 남겼다. 전쟁 없는 병합의 교과서적 사례이다. 같은 날짜에 편입된 다른 지역: 카라히사르 이 사히브(아피온).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["테살로니키의 확정적 정복", "bc021768"], "d": ["베네치아가 통치하던 도시가 공격으로 함락되었으며, 루멜리아의 두 번째 대항구는 확정적으로 오스만의 것이 되었다. 같은 날짜에 편입된 다른 지역: 케센디레(카산드라).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["이오안니나 항복", "ee45cb52"], "d": ["에페이로스의 중심지 이오안니나가 협정에 따라 항복했다.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["스메데레보의 첫 점령", "c11ca17d"], "d": ["석 달의 포위로 세르비아 전제공국의 수도가 점령되었고 세르비아는 처음으로 병합되었다(1444년 에디르네-세게드 조약으로 반환된다).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["베오그라드 포위 (실패)", "3e05f425"], "d": ["6개월 동안 이어진 첫 대규모 베오그라드 포위는 성과를 거두지 못했으며, 이 요새는 80년 동안 오스만의 진격을 막는 자물쇠로 남았다.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["즐라티차의 패주 — '긴 원정'", "97df1466"], "d": ["후녀디가 한겨울에 발칸으로 끌고 들어간 군대는 니시와 소피아를 지나 즐라티차까지 밀고 들어왔고, 오스만의 방어는 가까스로 버텼다. 이 패주의 분위기가 에디르네-세게드 강화를 협상 탁자에 올려놓았다.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["에디르네-세게드 조약", "0aa4e0de"], "d": ["10년 평화 조약으로, 세르비아 전제공국이 반환되고 도나우강이 국경으로 인정되었다. 교황청의 선동으로 몇 달 만에 조약이 깨지면서 바르나의 참패로 이어졌다.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["스메데레보와 세르비아 요새들의 세르비아 반환", "cda3cf9e"], "d": ["에디르네-세게드 조약의 조항이 이행되었다. 무라드 2세는 1444년 8월 15일 스메데레보를 24개의 주요 요새 및 점령 중이던 다른 세르비아 영토와 함께 주라지 브란코비치에게 돌려주었다(TDV semendire). 니시(TDV nis), 알라자히사르(TDV alacahisar), 셰히르쾨이(TDV sehirkoy), 프리슈티나(TDV pristine)도 세르비아인에게 넘겨졌다. 비딘은 세르비아 땅이 아니었으므로 반환 대상에 들어가지 않았다. 지도에서 바르나 전투 승리 무렵에 보이는 북서부 영토 상실은 여기에서 비롯된다. 몇 달 뒤 바르나의 패주와 함께 조약은 어차피 무효가 된다.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["루멜리 히사르 완공 — '보아즈케센(해협을 끊는 성)'", "480e8a76"], "d": ["사료에 따르면 넉 달에서 다섯 달에 걸친 놀랄 만큼 빠른 공사로 완성된 이 성채로 보스포루스 해협의 통제권은 완전히 오스만에 넘어갔으며, 흑해에서 이스탄불로 가는 원조로는 막혔다. 이는 포위의 사실상 첫걸음으로 여겨진다.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["이스탄불 포위 시작", "8af50742"], "d": ["군대가 성벽 앞에 자리 잡았다. 54일 동안 이어진 포위에서 거대한 대포가 처음으로 한 수도의 성벽을 상대로 체계적으로 사용되었다.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["함선을 육로로 넘겨 골든혼에 내리다", "4f2ba07c"], "d": ["쇠사슬로 막힌 골든혼에 들어가지 못한 함대 가운데 약 70척이 기름칠한 활대(썰매)를 이용해 갈라타 능선을 넘어 하룻밤 사이에 골든혼에 내려졌고, 방어 측은 두 전선으로 나뉘었다.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["아테네 정복", "4f0f1bb2"], "d": ["아테네 공국이 끝났고 아크로폴리스에 오스만의 깃발이 올랐다. 같은 날짜에 편입된 다른 지역: 테베, 리바디아.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["세르비아 병합 (스메데레보 함락)", "75fd0a62"], "d": ["세르비아 전제공국의 수도 스메데레보가 항복했고, 세르비아는 오스만의 산자크가 되었다.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["모레아 정복", "7d5a3c18"], "d": ["모레아 전제공국이 청산되었고, 반도는 (베네치아 요새를 제외하고) 오스만의 통치 아래 들어갔다.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["시노프 편입", "e03c2739"], "d": ["시노프의 잔다르 가문 통치자가 싸우지 않고 항복했으며, 트라브존 원정의 길이 열렸다. 같은 날짜에 편입된 다른 지역: 카스타모누, 바르튼, 사프란볼루. TDV의 잔다르 베이국 항목은 볼루, 에플라니, 토시아도 1461년에 병합된 잔다르 베이국의 영토로 언급한다. 지도에서는 이 세 곳도 이날 잔다르에서 오스만으로 넘어간 것으로 기록되어 있다. 같은 날짜에 상실한 다른 정착지: 카라데니즈 에레일리, 데브레크, 악차코자(잔다르 영토).", "9ead5a1c"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["보스니아 왕국의 멸망 — 정복자의 보스니아 원정", "5362e3f2"], "d": ["마지막 보스니아 왕 스티에판 토마셰비치(1461-1463)가 서방의 지원을 믿고 공납을 거부하자 그는 더 이상 속국 통치자가 아닌 것으로 간주되었고, 정복자 술탄 메흐메드가 이끄는 군대는 한 번의 원정으로 보스니아 왕국을 청산했다. 왕은 붙잡혀 처형되었고 왕국은 사라졌으며 이 지역에 보스니아 산자크가 설치되었다. 그러나 왕국의 멸망은 보스니아의 정복과 같은 것이 아니다. 오스만 행정은 이미 15년 전부터 평야에 존재했다. 1448년에 호디디에드와 사라이 평야가 점령되었고, 이사 베이의 접경 영지가 왕국 한가운데에 세워져 있었다. 정복은 1463년에도 끝나지 않았다. 포차는 1465년, 리브노는 1469년, 헤르체고비나 공국은 1483년, 스레브레니크 반국은 1512년에 점령되었고, 북부의 야이체와 바냐루카는 모하치 전투 이후인 1528년에야 점령되었다. 헝가리는 1463년 이후 65년 동안 보스니아 북부에서 버틴 반국을 세웠던 것이다. 이 시점에 직접 주인이 바뀐 곳은 트라브니크이며, 야이체는 이때 오스만이 아니라 헝가리에 넘어갔다.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["카라만의 확정적 병합", "f1dcecaa"], "d": ["카라만 가문의 중심 영토가 확정적으로 편입되었으나 내분은 1470년대까지 이어졌다. 같은 날짜에 편입된 다른 지역: 니으데, 모스타르, 베이셰히르.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["네그로폰테 정복", "5c97daf3"], "d": ["에게해에서 베네치아의 주요 거점인 네그로폰테(에으리보즈)가 함락되었다.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["알라니아, 아나무르, 실리프케(이첼) 병합", "a0b9d461"], "d": ["카라만 가문에 속한 이첼 해안 지대(안탈리아와 메르신 사이의 지중해 연안 전체)가 게디크 아흐메드 파샤의 해상 원정으로 편입되었다. 알라니아는 셀주크 시대부터 이어진 전략적 조선소 때문에 중요했다.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["모스크바의 노브고로드 병합", "bed87170"], "d": ["대공 이반 3세는 노브고로드 민회(베체)의 상징적인 종을 철거하고 현지 관리들을 자신의 총독으로 교체하여 도시를 사실상 모스크바에 귀속시켰으며, 노브고로드는 독립 공화국이 아니게 되었다. 노브고로드의 영토는 발트해에서 백해와 우랄산맥까지 뻗어 있었다. 지도에서 노브고로드는 이날부터 노브고로드 공화국에서 모스크바로 넘어간 것으로 기록되어 있다.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["이스탄불 조약 — 알바니아와 슈코더르", "b09652f7"], "d": ["16년에 걸친 오스만-베네치아 전쟁이 끝났고, 슈코더르와 알바니아 해안은 오스만에 남았다. 같은 날짜에 편입된 다른 지역: 림노스, 사모스, 보즈바바(아기오스 에프스트라티오스).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["오트란토 상륙", "7916b89d"], "d": ["아풀리아(풀리아) 해안에 상륙한 오스만군은 오트란토 요새를 포위해 함락했다. 도시가 전투 끝에 점령되었기 때문에 저항한 유력자 가운데 일부는 처형되고 일부는 포로가 되었다. 교회 전승은 죽은 이들을 약 800명의 '오트란토 순교자'로 기린다. TDV는 이 숫자의 과장을 교회의 선전 탓으로 본다. 살렌토반도 끝의 요새와 좁은 주변 지역만 확보되었을 뿐, 타란토-브린디시-레체 선에 있는 나폴리 왕국의 나머지 영토는 상실되지 않았다. 이탈리아로 열린 이 교두보는 1년 동안 유지된다.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["오트란토 철수", "37371bb0"], "d": ["정복자 술탄 메흐메드의 죽음(1481년 5월 3일)으로 새 증원을 기대할 수 없게 된 오트란토 수비대는, 나폴리 왕세자 알폰소의 포위 앞에서 합의에 따라 요새를 비웠다. 이탈리아의 유일한 오스만 교두보는 이렇게 1년 만에 상실되었다.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["모돈과 코론 정복", "38b608c4"], "d": ["모레아에서 베네치아의 '두 눈'인 모돈과 코론이 점령되었다.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["두러스 정복", "1f231b98"], "d": ["1499-1503년 오스만-베네치아 전쟁 중에 메흐메드 베이가 지휘하는 부대가 아드리아해에서 베네치아의 마지막 알바니아 대항구인 두러스를 점령했다. 슈코더르(1479)와 블로러(1417)에 이은 이 정복으로 알바니아 해안 지대 전체가 오스만의 통제 아래 들어갔다.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["동아나톨리아 편입", "e0cb8f8f"], "d": ["찰드란 전투 이후 디야르바크르와 그 일대가 편입되었으며, 쿠르드 공국들은 이드리스 비틀리시를 통해 오스만에 귀속되었다.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["바라딘(페트로바라딘) 요새 정복", "abf392a5"], "d": ["모하치 원정에 나선 군대는 베오그라드에서 헝가리 영토로 넘어갔다. 먼저 바라딘의 외곽 지구가 점령되었고, 14일의 포위 끝에 요새도 함락되었다. 카누니는 길가의 마을들을 불태우지 말라고 명령했는데, 그곳들은 이제 오스만의 땅으로 간주되었기 때문이다.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["모하치 이후 부다의 항복 — 헝가리 왕위의 두 국왕", "9d3568a0"], "d": ["모하치 전투의 승리 후 부다로 진군한 오스만군에게 1526년 9월 11일 도시의 열쇠가 술탄에게 바쳐졌다. 그러나 카누니는 부다를 보유하지 않고 군대를 철수시켰다. 국왕이 없어진 헝가리에서 귀족들은 두 명의 왕을 따로 선출했다. 1526년 11월 10일 서포여이 야노시, 1526년 12월 17일 합스부르크의 페르디난트 1세이다. 페르디난트는 1527년 8월 부다를 점령했다. 서포여이가 오스만의 보호를 받는 왕으로 부다에 자리 잡는 것은 1529년의 원정을 통해서였고(1529년 항목 참조), 오스만의 직접 통치는 1541년에 수립된다.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["서포여이 야노시의 헝가리 왕 선출 — 오스만은 속국을 조건으로 왕위를 승인", "32bc6baf"], "d": ["모하치에서 국왕이 죽어 비게 된 헝가리 왕위에 귀족 일부가 트란실바니아 총독 서포여이 야노시를 선출했으며, 서포여이는 세케슈페헤르바르에서 대관했다. 부다를 비운 오스만은 이 지역을 완충지대로 두기 위해 서포여이가 자신들에게 예속되는 것을 조건으로 그의 왕위를 승인했다. 지도에서 서포여이에게 속한 곳은 이 날짜부터 오스만의 속국으로 표시된다.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["페르디난트 1세의 헝가리 왕 선포 — 서·북 헝가리가 합스부르크 왕관 아래로", "b3910a2f"], "d": ["합스부르크의 대공 페르디난트는 누이가 러요시 2세와 혼인한 것을 근거로 헝가리 왕위의 권리를 주장했고, 일부 귀족에 의해 왕으로 선포되었다. 이로써 헝가리는 두 왕 사이에 분열되었고 서부와 북부는 페르디난트를 인정했다. 크로아티아 귀족들은 1527년 초에 그를 따로 선출했다.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["두 국왕의 다툼: 에스테르곰은 합스부르크의 보호 아래, 세게드는 서포여이에게", "da92dee5"], "d": ["1526년부터 두 왕 사이에서 주인이 바뀌던 에스테르곰은 대주교가 문서고와 재물을 가지고 북쪽으로 옮겨 간 뒤 합스부르크의 보호 아래 들어갔다. 같은 해부터 1541년까지 세게드는 서포여이의 통치 아래 남았다.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["페치 주민, 서포여이 편으로 돌아서다", "3fc4e7f2"], "d": ["1528년에 페르디난트에게서 특권을 받은 페치는 얼마 지나지 않아 서포여이 편으로 돌아섰으며, 야노시 왕은 1533년에 한동안 이 도시에 머물렀다. 1541년 부다가 함락되자 도시는 다시 페르디난트 편으로 돌아섰다.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["트리폴리 정복", "8c659986"], "d": ["성 요한 기사단에게서 트리폴리를 빼앗았으며, 북아프리카의 중부 해안이 오스만의 것이 되었다. 같은 날짜에 편입된 다른 지역: 미스라타.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["테메슈바르 정복", "e9fd4995"], "d": ["바나트 지역이 점령되고 테메슈바르 베일레르베이령이 설치되었다.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["튀니스의 확정적 정복", "7bbd11bc"], "d": ["스페인-하프스 왕조의 통제 아래 있던 튀니스가 확정적으로 오스만의 통치 아래 들어갔으며, 북아프리카 선이 완성되었다. 같은 날짜에 편입된 다른 지역: 카이르완, 가베스, 스팍스.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["카니제 정복", "0c7b6aa3"], "d": ["장기 전쟁에서 카니제가 점령되었으며, 이듬해 티리야키 하산 파샤의 방어는 서사시가 되었다.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["우이바르 원정의 시작 — 파즐 아흐메드 파샤, 에디르네에서 오스트리아로 진군", "306a86db"], "d": ["오스트리아가 트란실바니아를 공격해 세케이히드와 콜로주바르 요새를 점령하자 이스탄불은 합스부르크에 대한 원정을 결정했다. 대재상 쾨프륄뤼자데 파즐 아흐메드 파샤는 1663년 4월 13일 에디르네를 출발했다. 베오그라드에 오스트리아의 강화 요청이 도착했으나, 오시예크에서 열린 두 차례의 회담에서 오스만의 조건은 거절되었다. 부다에서의 협의에서도 목표는 우이바르로 정해졌다.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["우이바르 정복", "ce289470"], "d": ["북헝가리의 요충 요새 우이바르(노베잠키)가 점령되었으며, '우이바르 앞의 튀르크처럼 강하다'는 표현이 유럽의 여러 언어에 들어갔다. 우이바르에 이어 니트라와 레바도 짧은 저항 끝에 항복했으나, 드 수슈가 1664년 봄에 두 곳 모두를 되찾았다.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["모레아 탈환", "9b6460f1"], "d": ["카를로비츠에서 베네치아에 넘겨졌던 모레아가 한 번의 원정으로 되찾아졌다. 같은 날짜에 편입된 다른 지역: 파트라(발랴바드라), 이네바흐트(레판토).", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["베오그라드의 두 번째 상실 — 오이겐 공의 포위", "6a194354"], "d": ["바라딘의 패주와 테메슈바르 상실 이후 오이겐 공은 베오그라드를 포위했다. 도시를 구하러 온 구원군마저 패주하자 요새는 항복했다. 카를로비츠 이후 1690년에 되찾았던 이 도시는 이렇게 다시 상실되었고 도나우 방어선이 무너졌다. 베오그라드는 22년 뒤인 1739년 베오그라드 조약으로야 되찾을 수 있었다. 같은 날짜에 상실한 다른 정착지: 스메데레보. 지도는 또한 히사르즈크(그로츠카)와 야고디나 지방을 이날 합스부르크 영토로 기록한다(지역 단위의 날짜이며, 개별 지점의 날짜는 사료에 없는 명시된 근사치이다). 한편 메하디아는 1717년 8월 27일자로 합스부르크에 넘어간다(Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["외지(오차코프) 함락", "90a67a6c"], "d": ["흑해 북쪽의 요충 요새 외지(오차코프)가 유혈 돌격으로 러시아의 손에 넘어갔으며, 도시 주민은 칼에 학살되었다.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["부쿠레슈티 조약 — 베사라비아 상실", "932da4d6"], "d": ["1806-1812년 러시아 전쟁을 끝낸 조약으로 프루트강 동쪽(베사라비아)이 러시아에 넘겨졌다. 같은 날짜에 상실한 다른 정착지: 아케르만, 킬리야, 호틴, 벤데르, 이즈마일. 지도는 또한 베사라비아 안의 키시너우, 벌치, 카훌, 오르헤이를 같은 날 몰다비아(오스만의 속국)에서 러시아로 넘어간 것으로 본다. 소로카도 같은 날 러시아에 넘어간다.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["에디르네 조약", "b3a8fe4c"], "d": ["러시아군이 에디르네에 입성한 전쟁의 끝에 도나우 삼각주를 잃었고, 그리스의 자치/독립이 사실상 인정되었다. 같은 날짜에 상실한 다른 정착지: 브러일라, 아나파, 아할치헤. 조약은 영토를 돌려주었지만 점령을 곧바로 끝내지는 않았다. 왈라키아-몰다비아와 실리스트라는 전쟁 배상금이 지불될 때까지 담보로 러시아의 통치 아래 남았으며, 이것이 지도에서 이곳들이 1829년 이후에도 점령 상태로 보이는 이유이다. 체르케스(마이코프)와 체르케스 해안(소치, 투압세)에 대한 오스만의 권리 주장도 이 조약으로 끝났으며, 해안은 이후 러시아에 넘어갔다(소치와 투압세는 1838년).", "5666619b"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["세르비아 자치 칙령 — 세습 크네즈 지위와 수비대 조건", "6a5d901d"], "d": ["에디르네 조약의 세르비아 관련 조항에 따라 발표된 황제 칙서(핫트 휘마윤)는 밀로시 오브레노비치를 세습 크네즈(공)로 인정하고, 세르비아를 내정은 자유롭되 대외적으로는 오스만에 속한 자치 공국으로 만들었다. 조항은 다음과 같다. 크네즈 지위는 부자 세습하며, 연간 세금은 정액으로 납부하고, 세르비아 의회가 자체 내정 기구를 세우며, 교회는 자치를 가진다. 그 대신 베오그라드, 스메데레보, 샤바츠, 뵈위르델렌, 페튈이슬람 요새에는 오스만 수비대가 남는다. 이 이중 구조는 1867년 수비대가 철수할 때까지 이어졌다. 지도에서 베오그라드시는 이 날짜에 자치 세르비아에 편입되며, 칼레메그단 요새는 1867년까지 오스만 수비대 지배로 표시된다.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["키프로스를 영국의 통치에 맡기다", "423da3ee"], "d": ["러시아의 위협에 대한 동맹의 대가로 키프로스의 통치가 영국에 이양되었으며, 법적으로는 오스만 영토로 남았다. 같은 날짜에 상실한 다른 정착지: 니코시아, 파마구스타, 키레니아, 리마솔, 라르나카(투즐라), 파포스, 모르푸, 아크로티리, 에피스코피, 데켈리아. 즉 섬 전체이다.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["테살리아를 그리스에 이양", "ac614d24"], "d": ["베를린 회의의 결정에 따라 테살리아와 아르타 일대가 그리스에 이양되었다. 같은 날짜에 상실한 다른 정착지: 아르타, 라리사, 트리칼라, 라미아. 이 이양으로 볼로스, 칼람바카, 카르디차(테살리아)가 그리스에 넘어갔다.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["동루멜리아의 불가리아 합병", "ee43f137"], "d": ["자치 동루멜리아주가 쿠데타를 통해 불가리아에 합쳐졌고, 오스만 정부(바브알리)는 기정사실을 받아들였다. 이 합병으로 동루멜리아 전체(스타라 자고라, 파자르지크, 슬리벤, 하스코보, 부르가스, 아이토스, 엘호보)가 불가리아 공국으로 넘어갔다.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["도모코스 전투", "9c6f29a5"], "d": ["1897년 오스만-그리스 전쟁에서 군대는 도모코스에서 결정적인 승리를 거두었으나, 외교적 압력 때문에 영토 획득은 제한적이었다.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["크레타 자치", "2e764881"], "d": ["오스만-그리스 전쟁이 오스만의 승리로 끝났음에도, 영국, 러시아, 프랑스, 이탈리아는 1897년 12월 18일 크레타의 자치를 선포했다. 섬은 오스만의 주권 아래 중립적인 자치주가 될 것이었다. 1898년 11월 6일 이후 칸디아와 키사모스에는 더 이상 튀르키예 국기가 게양되지 않았고, 그리스 왕의 아들 게오르게 왕자가 1898년 12월 22일 특별 고등판무관으로 취임하면서 크레타는 사실상 오스만의 통치에서 벗어났다(공식적으로는 1913년에 분리되었다). 같은 날짜에 상실한 다른 정착지: 칸디아(크레타), 하니아.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["불가리아 독립과 보스니아 병합", "393feaa4"], "d": ["입헌 혁명의 혼란 속에서 불가리아는 독립을 선언했고, 오스트리아-헝가리는 보스니아-헤르체고비나를 병합했다. 이 선언으로 불가리아 공국의 모든 영토(바르나, 슈멘, 루세, 부르가스, 슬리벤 등)가 독립 불가리아 왕국이 되었다.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["에디르네 탈환", "536e5599"], "d": ["제2차 발칸 전쟁에서 군대는 마리차강을 건너 전투 없이 에디르네를 되찾았다. 같은 날짜에 편입된 다른 지역: 크르클라렐리, 테키르다으.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["쿠트 알아마라 전투의 승리", "98b972bc"], "d": ["쿠트에서 포위된 영국 사단은 사단장과 1만 3천 명의 병사와 함께 항복했다. 이는 제1차 세계 대전에서 오스만이 거둔 가장 큰 승리 가운데 하나이다.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["바그다드 상실", "2c18a816"], "d": ["383년 동안 오스만의 것이던 바그다드가 영국군에 넘어갔다. 같은 날짜에 상실한 다른 정착지: 카르발라, 크즐루바트.", "880969bf"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["예루살렘 상실", "94067617"], "d": ["401년 동안 오스만의 것이던 예루살렘이 방어되지 못한 채 넘겨졌다.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["다마스쿠스 상실", "ed177b68"], "d": ["팔레스타인 전선의 붕괴로 다마스쿠스가 철수되었고, 시리아에서 4세기에 걸친 오스만 통치가 끝났다. 같은 날짜에 상실한 다른 정착지: 하마, 홈스.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["메디나의 항복", "76b505f6"], "d": ["휴전 72일 뒤, '사막의 호랑이' 파흐레딘 파샤의 저항은 술탄의 칙령으로 끝났으며, 히자즈에 남은 마지막 오스만 부대가 무기를 내려놓았다.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["이즈미르 점령", "e32e5e77"], "d": ["그리스군이 이즈미르에 상륙했으며, 첫 총탄과 함께 시작된 저항은 민족 투쟁의 도화선이 되었다. 한편 아이든은 1919년 5월 27일에 점령되었다(별도 항목).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["이스탄불의 공식 점령", "a8e98ada"], "d": ["협상국 군대가 이스탄불을 공식 점령하고 하원(메즐리시 메부산)이 해산되었으며, 의원들은 앙카라로 향했다.", "09ed005b"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["사우드-와하비 세력의 하일 토후국 장악 — 통치는 압다 씨족의 이븐 알리 가문에 있었다", "2d29ceb9"], "d": ["제1차 사우드 국가의 군대가 하일 토후국을 장악했을 때 도시의 통치는 샴마르 부족의 압다 씨족에 속한 이븐 알리 가문이 맡고 있었다. 이 가문은 1835년 압둘라 이븐 라시드가 토후국을 장악할 때까지 하일을 다스렸으며, 라시드 왕조는 그때에야 세워졌다. 지도에서 하일은 지금까지 1836년까지 주인 없는 곳으로 표시되었으나, 사료는 1820년 도시의 아미르를 이름과 함께 전한다.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["크바르네르 제도의 나폴레옹의 이탈리아 왕국 편입, 코토르만의 러시아 통치 이관", "c5e411c8"], "d": ["프레스부르크 조약 이후 크바르네르 제도는 달마티아와 달리 프랑스에 직접 편입되지 않고 나폴레옹의 이탈리아 왕국에 속하게 되었으며, 일리리아 주에는 1809년에야 편입되었다. 한편 코토르만에서는 오스트리아의 통치가 끝나고 1806-1807년에 러시아의 통치가 수립되었으며, 코토르만은 1807년에야 프랑스에 넘어갔다. 이 두 가지 구분은 지도의 단일한 '프랑스' 시기로는 표현할 수 없다.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["달마티아의 프랑스 통치 이관 — 프레스부르크(브라티슬라바) 조약의 이행", "00bfe4f6"], "d": ["1805년 12월 26일의 프레스부르크(브라티슬라바) 조약은 오스트리아에 이스트리아, 달마티아, 그리고 아드리아해의 모든 섬을 포기하도록 강요했다. 프랑스는 1806년 2월에 사실상 통치권을 인수했으며, 자다르는 총감독관의 중심지로 남았고 1806-1810년에는 베네치아인 비첸초 단돌로가 이 직책을 맡았다. 달마티아는 1809년 쇤브룬 조약 이후 일리리아 주에 편입되었다. 이로써 1797년부터 이어진 제1차 오스트리아 통치가 끝났다. 지도에서 이 시기는 지금까지 중단 없는 오스트리아령으로 표시되어 있었다.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["오스트리아의 일리리아 주와 달마티아 수복 — 나폴레옹 통치의 종말", "1b2ac942"], "d": ["1813년 말 합스부르크 군대는 사바강 남쪽 지역을 되찾았고 옛 국경 조직이 다시 세워졌다. 오스트리아군은 1813년 10월 이스트리아에 진입했다. 카를로바츠는 그때부터 오스트리아령 일리리아 왕국의 일부가 되었다. 달마티아에서의 프랑스 통치 시기도 1813년에 끝났다. 이 지역의 오스트리아 귀속은 1814년 파리 강화와 1815년 빈 회의의 결정으로 공식 승인되었다. 이 작전으로 필라흐, 타르비스, 고리치아, 그라디스카, 풀라(일리리아 주)가 1813년 말 오스트리아로 돌아갔다.", "bf1e49a8"]}
});
